(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).ps={"1":{"1":"Блажен, кто советам нечестивых не последовал, и на путь грешников не вступил, и среди хулителей не сидит,","2":"кто Закону Господа верен, кто твердит его день и ночь.","3":"Он – как дерево, посаженное у воды, чьи плоды созревают в срок и чьи листья не увядают. За что ни взялся – все идет на лад!","4":"Не таков удел нечестивых: они – мякина, гонимая ветром,","5":"нечестивым не устоять на суде, грешным – в собрании праведных!","6":"За путем праведных смотрит Господь, а путь нечестивых – гибель."},"2":{"1":"Почему народы бушуют? Почему пустое твердят?","2":"Собрались цари земли, властители сговорились против Господа и Помазанника:","3":"«Стряхнем с себя их ярмо, сбросим с себя их путы!»","4":"Смеется Тот, чей престол – небо! Потешается над ними Господь!","5":"В ярости Он им скажет, Своим гневом повергнет в ужас:","6":"«Это Я возлил елей на царя Моего на Сионе, Моей святой горе!» [Царь: ]","7":"– Решение Господа я возвещу: так Он сказал мне: «Ты Мой сын, Я сегодня родил тебя!","8":"Проси – Я отдам народы тебе во власть, все отдам тебе, до краев земли,","9":"жезлом железным народы ты сокрушишь, разобьешь, как глиняные горшки!»","10":"А потому, цари, образумьтесь! Опомнитесь, владыки земли:","11":"служите Господу трепеща и со страхом","12":"целуйте стопы Его! А иначе разгневается Он, и ждет вас гибель на вашем пути! Мгновенно вспыхнет Его ярость! Блаженны все, кто уповает на Него!"},"3":{"1":"[Псалом Давида. Сложен, когда Давид бежал от своего сына Авессалома.]","2":"О Господь! Сколько врагов у меня! Многие против меня поднялись!","3":"Многие говорят про меня: «Бог его не спасет!» [Музыка]","4":"Но Ты, Господь, – Щит мой; Ты – Слава моя; Ты даешь мне голову гордо поднять!","5":"Громко Господа я призову – и с горы Своей святой отзовется Он. [Музыка]","6":"Я ложусь, и сплю, и встаю – Господь мне силы дает.","7":"Не страшусь я полчищ людских, со всех сторон окруживших меня.","8":"Вступись, Господь! Спаси меня, мой Бог! Сломай челюсть врагам моим! Выбей зубы злым!","9":"Спасенье придет от Господа. Благословенье Твое – на народе Твоем. [Музыка]"},"4":{"1":"[Начальнику хора: под музыку струнных. Псалом Давида.]","2":"Ответь, когда я зову, Бог, в чьих руках оправданье мое! Тесно мне – дай увидеть просвет! Помилуй, мольбу услышь!","3":"Люди! Долго ль еще вам бесчестить меня? Долго ли любить пустоту и ложь? [Музыка]","4":"Знайте, что с верным Господь не таков, как с другими: когда я зову, слышит меня Господь.","5":"Трепещите и не грешите, на ложах своих задумайтесь, притихните. [Музыка]","6":"Принесите жертвы как должно, на Господа уповайте.","7":"Твердят многие: «Даст ли нам кто-нибудь счастье?..» О Господь! Светлым взором на нас посмотри!","8":"Моему сердцу дал Ты радость, какой не бывает даже у тех, у кого хлеба и вина вдоволь!","9":"С миром я лягу и ко сну отойду. О Господь, один Ты мне даруешь покой!"},"5":{"1":"[Начальнику хора: напев «Ханехилот…». Псалом Давида.]","2":"Услышь слова мои, о Господь! Мольбу прими!","3":"Крик мой услышь, о мой Царь и мой Бог, я молю Тебя!","4":"О Господь! Что ни утро – Ты слышишь меня, что ни утро – с надеждою я пред Тобой!","5":"Ты Бог, который не терпит зла, злому рядом с Тобой не место!","6":"Дерзким не выдержать взора Твоего, негодяи ненавистны Тебе,","7":"клеветников уничтожишь Ты, мерзок для Господа убийца и лжец.","8":"А я в Твой дом войду, по милости Твоей, и в Твоем Храме трепеща паду ниц.","9":"Господи! Веди меня дорогой правды Твоей! Сделай путь мой прямым, наперекор врагам.","10":"В их словах правды нет, в их сердцах – смерть, рот – раскрытый склеп, язык лжив.","11":"Покарай их, Боже! Пусть их козни погубят их. Прогони их, грешников! Ведь они отвергли Тебя!","12":"Пусть ликуют все, кому Ты защита, пусть вечно радуются, что Ты – заступник их! Ты – веселье для любящих имя Твое.","13":"Праведника Ты благословишь, Господь, оградишь его милостью Своей как щитом."},"6":{"1":"[Начальнику хора: под музыку струнных; напев «Ха – шеминит…». Псалом Давида.]","2":"О Господь, не карай меня в ярости Своей! В гневе Своем не наказывай меня!","3":"Сжалься, Господь, – больше нет сил! Исцели меня – кости мои дрожат!","4":"И душа содрогается! О Господь! Долго ль еще?","5":"Пожалей! Сохрани мне жизнь! Милосердный, спаси меня!","6":"Ведь там – в смерти – Тебя не помянет никто, в мире мертвых – кто прославит Тебя?!","7":"Я от стонов уже изнемог, что ни ночь, изголовье в слезах, орошаю слезами постель.","8":"Помрачило горе мои глаза – я не в силах взглянуть на врагов.","9":"Уходите, злодеи, прочь, – ибо слышит Господь мой плач!","10":"Господь слышит молитву мою, Господь примет мою мольбу!","11":"Содрогнутся враги мои, их покроет позор, они тотчас с позором уйдут!"},"7":{"1":"[Плач Давида. Эту песнь он пел Господу, когда узнал про Куша из племени Вениамина.]","2":"О Господь, мой Бог, у Тебя я защиты ищу! От погони – избавь меня и спаси!","3":"Иначе враг растерзает меня как лев, на куски разорвет – и никто не спасет!","4":"О Господь, мой Бог! Если я что-то сделал не так, запятнал мои руки неправдой,","5":"другу злом отплатил, а обидчика стал выручать –","6":"пусть за мною погонится враг, пусть настигнет меня, мою жизнь втопчет в землю, мою честь попирает в пыли! [Музыка]","7":"В гневе воспрянь, Господь, подымись против злобы врагов моих, пробудись, мой Бог, верши суд!","8":"Соберутся народы вокруг Тебя, Ты над ними, в выси, на престол воссядь!","9":"Господь народы будет судить. Реши же, Господь, и тяжбу мою: я прав, нет за мной вины.","10":"Пусть злобе злодеев придет конец! Поддержи правого, праведный Бог, насквозь видящий и сердце, и нутро!","11":"Щит мой – Бог! Он чистых сердцем спасет!","12":"Бог – праведный судия, что ни день – в ярости Он.","13":"Он вновь наточил Свой меч, лук напряг, натянул,","14":"Он оружие смерти взял, приготовил горящие стрелы!","15":"Кто неправду зачал, тот забеременел злом и рождает ложь.","16":"Кто другому рыл яму – тот в нее и провалится сам!","17":"Его зло обернется против него, ему ж на голову и падет.","18":"Справедливого Господа славлю я – воспою имя Господа Вышнего!"},"8":{"1":"[Начальнику хора: напев «Ха – гиттит…». Псалом Давида.]","2":"Господи, Боже наш! По всей земле славится имя Твое! Выше небес раздается Тебе хвала","3":"из уст младенцев, грудных детей! Против врагов Ты воздвиг оплот, и злобного недруга смирил.","4":"Вижу небо, творение рук Твоих, и луну, и звезды – созданья Твои…","5":"Что такое человек? – а Ты помнишь о нем! Что любой из людей? – а Ты печешься о нем!","6":"Ты сделал так, что немногим он ниже божеств, Ты величьем и славой его увенчал,","7":"дал власть над твореньями рук Твоих – всех поверг Ты к его стопам:","8":"и овец, и коз, и быков, и даже диких зверей,","9":"и птиц небесных, и рыб морских, что плывут в глубинах морей…","10":"Господи, Боже наш! По всей земле славится имя Твое!"},"9":{"1":"[Начальнику хора: напев «Алмут лаббен…». Псалом Давида.]","2":"Всем сердцем я славлю Тебя, Господь, возвещаю Твои чудеса.","3":"Я ликую и радуюсь о Тебе, Твое имя, Вышний, пою.","4":"Обратились враги мои вспять пред Тобою – упали, погибли!","5":"Так Ты тяжбу мою решил – суд свершил Ты, Судья Справедливый!","6":"Усмирил Ты народы, уничтожил злодеев, стер их имя на веки веков!","7":"Больше нету врага – лишь руины навек! Города их низверг Ты, стерлась память о них.","8":"Вечно будет царить Господь, для Суда Он воздвиг Свой престол –","9":"Он будет справедливо судить весь мир, народам вынесет приговор.","10":"А гонимому будет опорой Господь, оплотом во время беды!","11":"Ты надежда для помнящих имя Твое, Ты не покинешь зовущих Тебя!","12":"Славьте Господа, чей престол – Сион, возвещайте народам деянья Его.","13":"Он припомнит убийцам пролитую кровь, не забыт Им стон бедняков!","14":"Господи, сжалься! Меня теснят враги! Из врат смерти меня подними!","15":"У сионских врат я прославлю Тебя, возликую, что Ты меня спас!","16":"Народы вырыли яму – и пали в нее, и запутались в своих же сетях,","17":"так стал явным Господень суд – злодей попался в свою западню! [Пауза. Музыка]","18":"Пусть в мир мертвых вернутся злодеи – все народы, забывшие Бога.","19":"Не навсегда бедный забыт, не навеки надежд лишены бедняки!","20":"Явись, Господь, сбей с людей спесь, пусть предстанут народы на Твой суд!","21":"Ужасом их порази, Господь, чтобы знали, что они всего лишь люди. [Музыка]","22":"Почему, Господи, Ты стоишь вдалеке, и в час беды не видно Тебя?!","23":"Бедняка преследует наглый злодей. Да угодит он в свою же ловушку!","24":"Когда негодяй славословья поет, добившись, чего хотел, и разжившись, читает благословенья, этим Господа он хулит!","25":"Он глядит свысока: «Отвечать не придется, Бога нет!» – так думает он.","26":"На всех путях его ждет успех, Твой суд для него высок и далек, а враги для него ничто!","27":"Думает он: «Я не пошатнусь, не узнаю горя вовек».","28":"На устах – лишь проклятия, ложь и зло, на языке – беда и обман.","29":"Во дворах, в засаде, таится он, в тайном месте, невинного хочет убить, смотрит, слабого подстерегает.","30":"Притаился в засаде, как в чаще лев, притаился, несчастного хочет поймать, – и поймает его в свою сеть!","31":"Раздавит его – и слабый падет, станет жертвой силы его!","32":"Злодей думает, что забывчив Бог, дескать, Он отвернулся, не видел ничего…","33":"Но воспрянь, Господь! Простри руку, Бог! Обездоленных не забывай!","34":"Почему Бога хулит злодей? Думает, к ответу Ты его не призовешь?","35":"Но Ты смотришь, Ты видишь – и горе, и боль. Ты воздашь за все Своею рукой! Тебе вручает себя бедняк, Ты помощник сирот!","36":"Сломай руку злодею и подлецу; сделай так, чтоб его было не найти!","37":"Господь – царь во веки веков. Чужеземцы да сгинут с Его земли!","38":"Чаянья бедных Ты слышишь, Господь! Их сердца ободри! Внемли!","39":"За нищих и сирот заступись, пусть не станет притеснителей на земле!"},"10":{"1":"[Начальнику хора: сложено Давидом.] Защита моя – Господь! А вы говорите мне: «Улетай в горы, словно птица».","2":"Натянули злодеи лук, приложили стрелу к тетиве – чистых сердцем во тьме подстрелить…","3":"Все разрушено до основанья – что же праведник может сделать?","4":"Господь в Храме Своем святом. На небе Его престол. Смотрят очи Его на людей, испытывает их Его взор.","5":"Испытывает Господь, кто прав, кто виноват, и ненавидит тех, кто любит насилие.","6":"На злодеев обрушит Он дождь горящих углей и серы. Вихрь огненный – вот их участь.","7":"Справедлив Господь, справедливость Он любит, праведник узрит лик Его."},"11":{"1":"[Начальнику хора: напев «Ха – шеминит…» Псалом Давида.]","2":"Спаси, Господь! Праведных больше нет! Средь людей больше некому верить!","3":"Все друг другу лгут, лживы их уста, они думают не то, что говорят.","4":"Покарает Господь их лживые уста, отсечет кичливый язык.","5":"Пусть не думают: «Мы мастера говорить! Язык – наше оружье! Нам никто не указ».","6":"«Бедняки ограблены, нищие стонут – Я за них вступлюсь, – говорит Господь, – Я униженного спасу!»","7":"Слова Господа чисты, как серебро, переплавленное в горниле земном и очищенное семь раз.","8":"О Господь, Ты нас Сам хранишь! Нас бережешь и сейчас, и вовек!","9":"А нечестивые рыщут вокруг, и пустое в почете у людей."},"12":{"1":"[Начальнику хора: псалом Давида.]","2":"Надолго ли, Господь, Ты оставил меня? Неужели навсегда? Надолго ли отвернулся Ты от меня?","3":"Сколько сетовать мне еще? Весь день в сердце боль! Долго ли глумиться врагу надо мной?","4":"Взгляни на меня, отзовись, о Господь, мой Бог! Дай глазам видеть свет, сном смерти не дай уснуть!","5":"Пусть не думает враг, что осилил меня, и не веселится, что я упал.","6":"Я надеюсь на милость Твою! Ты даруешь мне радость – спасенье даешь, я буду петь, как Господь меня спас!"},"13":{"1":"[Начальнику хора: псалом Давида.] Безумец думает: «Бога нет». Преступленья людские – гадки, гнусны… Никто не творит добра.","2":"Господь взирает с небес на людей, смотрит: есть ли мудрец, есть ли ищущий Бога?","3":"Все сбились с пути, никуда не годны, добра никто не творит – ни один!","4":"Неужели ничего не понимают они – люди, делающие зло? Мой народ пожирают они, будто хлеб, и Господа не призывают.","5":"Там объяли их страх и ужас, ибо с праведниками – Бог.","6":"Вам смешны наставления бедняка? Но Господь – защита его!","7":"– О если бы с Сиона пришло спасенье для Израиля! – Когда Господь возвратит Свой народ из плена, будет тогда веселье Иакову, радость Израилю!"},"14":{"1":"[Псалом Давида.] – О Господь! Кто в Шатре Твоем может жить? Обитать на Твоей святой горе?","2":"– Тот, чей путь непорочен и чьи дела праведны, кто правду в сердце своем говорит,","3":"не клевещет, не делает другу зла, ближних своих не срамит.","4":"Презренный в его глазах – ничто, а боящихся Бога он чтит. Другу поклялся – и слово сдержал,","5":"серебра не пускал в рост, невинного не обвинял за взятку. Кто поступает так – вовек не падет!"},"15":{"1":"[Стихотворение Давида.] Храни меня, Бог, у Тебя я защиты ищу!","2":"Скажу Господу: Ты мой Владыка, Ты Благо мое! И нет выше Тебя никого","3":"средь святых, почитаемых в этой земле, могучих, любимых всеми!","4":"Многочисленных идолов делают люди, и за богом иным спешат – не участник я их возлияний и жертв, их имен мои уста не помянут!","5":"Господь – мое достоянье и чаша моя. В Твоих руках жребий мой.","6":"Мне по жребию выпал прекрасный надел, и роскошны владенья мои.","7":"Слава Господу, что вразумляет меня, даже ночью в душе наставленье звучит!","8":"Всегда вижу я Господа перед собой, раз Он рядом – я не упаду.","9":"Мое сердце радо, ликует душа, спокойно тело – нечего бояться.","10":"Ты не оставишь в Шеоле меня, не дашь праведнику видеть мир тлена.","11":"Ты путь жизни укажешь мне, полнота радости – перед лицом Твоим, блаженство вечное – в руке Твоей."},"16":{"1":"[Молитва Давида.] Услышь, о Господь, мой крик, о справедливости я молю, прошенье мое прими – ибо не лжив мой язык!","2":"Ты рассудишь тяжбу мою – Твои очи видят, кто прав.","3":"Ты всмотрелся в сердце мое, пришел ночью меня испытать, не нашел Ты за мной вины, на устах моих нет зла.","4":"Что бы ни делали люди, соблюдаю я слово Твое, мне с преступником не по дороге.","5":"Мои ноги идут по путям Твоим, я иду и не оступлюсь.","6":"Я взываю к Тебе, Бог, отзовись! Ухо склони, услышь!","7":"Яви милость надеющимся на Тебя – Своей рукой от врага защити.","8":"Как зеницу ока меня храни и в тени Твоих крыл укрой","9":"от моих обидчиков злых, от врагов, что вокруг меня.","10":"Они жиром заплыли, надменны их речи,","11":"они выследили, окружили меня, смотрят, как бы повергнуть на землю.","12":"Они – как добычи жаждущий лев, как в засаде сидящая львица.","13":"Вступись, Господь, выйди им навстречу, заставь склониться, Своим мечом меня избавь от злодеев,","14":"рукой Своей – от этих людей, от этих людей, Господь! Их участь – среди живых. То, что припас Ты им, наполнит их чрево, будут сыты и останется еще и детям их, и младенцам.","15":"Мне, за правду мою, дано видеть Твой лик, встав ото сна, вдоволь образ Твой созерцать."},"17":{"1":"[Начальнику хора: сложено Давидом, рабом Господним. С этой песней он обратился к Господу после того, как Господь спас его от всех врагов и от Саула. Сказал Давид:] Я люблю Тебя, Господь. Ты – сила моя!","3":"Господь – моя скала, опора и оплот. Мой Бог – это утес, где я защиты ищу, мой щит, гора спасения, твердыня.","4":"Господа я, воспев, призову – и спасусь от моих врагов!","5":"Узы Смерти оплели меня, реки Гибели меня страшат,","6":"и я связан узами Шеола, и капканы Смерти предо мной.","7":"В горе Господа я призываю, я взываю к Богу моему. В Своем Храме Он меня услышал, и мой вопль дошел до Его слуха.","8":"Задрожала, затряслась земля, поколебались основанья гор, от ярости Его затрепетали.","9":"Дымом полыхали Его ноздри, пламенем уста Его пылали, искры сыпались вокруг Него.","10":"Небеса склонил Он и сошел, море мрака под Его ногами,","11":"полетел, воссев на херувима, мчался Он на крыльях ветра.","12":"Тьму вокруг простер как Свой покров, тучи, темень вод – как балдахин.","13":"От сиянья, что пред Ним, пылали тучи. Град и искры…","14":"Громом в небе прогремел Господь, голос Вышнего разнесся… Град и искры…","15":"Стрелы пустил и рассеял врагов, молниями обратил их в бегство.","16":"И явились истоки вод, и опоры мира обнажились от Твоего оклика, Господь, от дыханья гнева Твоего.","17":"Господь руку с высоты простер, из пучины вытащил меня,","18":"спас меня от лютого врага – от врага, что был меня сильней!","19":"В день беды напали на меня – но моей опорой был Господь!","20":"На простор Он выведет меня, по любви ко мне меня спасет,","21":"наградит меня Господь за правоту, и за то, что руки мои чисты –","22":"что я следовал Его путям, Богу моему не изменял.","23":"Все Его законы предо мной, я не отвергал Его велений.","24":"Непорочен перед Ним я, и не совершал греха!","25":"Он наградит меня за правоту – видит Он, что руки мои чисты!","26":"Ты верен тем, кто верен Тебе, кто добр, с теми добр и Ты.","27":"Ты искренен с тем, кто искренен сам, с коварным и Ты коварен.","28":"Ты спасешь народ бедняков, заставишь гордого взгляд опустить.","29":"Ты светильник мой зажигаешь: Господь, мой Бог, мою тьму озарит!","30":"С Тобой я иду на врагов, с моим Богом – стену одолею.","31":"Божий путь – непорочен и прям, слова чисты, как будто из тигля. Он щит для всех, кто уповает на Него.","32":"Разве есть иной бог, кроме Господа? Скала иная, кроме Бога нашего?","33":"Бог меня силой вооружил, путь мой сделал прямым,","34":"дал ногам силу ног оленьих, дал твердо стоять на земле.","35":"Мои руки научил воевать – и руками я гну медный лук!","36":"Щит спасения Ты мне вручил, помогла мне рука Твоя, Ты, услышав, меня возвеличил.","37":"Моим шагам даровал Ты простор, и нога моя не оступится.","38":"Я настигну моих врагов, не вернусь, пока не истреблю их.","39":"Разобью их – им больше не встать, у меня под ногами будут.","40":"Ты придал мне для битвы сил, Ты врагов предо мной поверг,","41":"Ты в бегство их обратил, я уничтожил ненавидевших меня.","42":"На помощь звали – никто их не спас, звали Господа – Он не ответил.","43":"Я их развеял – как пыль на ветру, я их разбрызгал, как уличную грязь.","44":"Ты меня спас от людских мятежей, во главе народов поставил, племена, что прежде были мне неведомы, служат мне,","45":"исполняют мой приказ, чужеземцы заискивают передо мной,","46":"дрожа выползают из убежищ своих.","47":"Жив Господь, Он моя Скала, благословен и вознесен Бог, спасающий меня!","48":"Бог, вступившийся за меня и народы мне покоривший.","49":"Ты меня от напавших спас, над врагами возвысил, от злодеев избавил.","50":"Средь народов, Господь, я Тебя воспою и прославлю имя Твое:","51":"Ты даруешь великие победы царю. Ты верен избраннику своему, Давиду, и потомкам его – навек!"},"18":{"1":"[Начальнику хора: псалом Давида.]","2":"О Божьей славе говорят небеса, о деяньях Его повествует твердь.","3":"День дню слово передает, ночь ночи знание возвещает.","4":"Звука не слышно, не слышно слов, голос их не звучит –","5":"но разносится речь их по всей земле, и до всех краев мира – их весть. А там для Солнца раскинут шатер –","6":"выходит, радостное, оно, как из-под свадебного балдахина жених, и как атлет, начинает свой бег.","7":"Пускается в путь от края небес, добежит до края и вспять повернет. От его жара не скрыться нигде!","8":"Совершенен закон Господень, он возвращает жизнь. Непреложен устав Господень и простецам дает мудрость.","9":"Верны повеления Господа и радость сердцу несут. Светла заповедь Господа и просвещает взор.","10":"Страх перед Господом чист и пребывает вовек. Предписанья Господа праведны, из них каждое – правда сама.","11":"Вожделенней, чем груды золота, они слаще меда и патоки.","12":"Я, Твой раб, соблюдаю их, за соблюденье их – награда великая.","13":"…Разве наши ошибки нам ведомы? От незримых грехов очисти меня!","14":"От бесстыжих меня избавь – пусть не властвуют над рабом Твоим! И тогда непорочен буду я, от греха великого чист!","15":"Прими благосклонно мои слова, вздохи, идущие из сердца моего! Ты, Господь, – моя Скала, Избавитель мой!"},"19":{"1":"[Начальнику хора: псалом Давида.]","2":"В день беды да откликнется Господь на твой зов, имя Бога Иакова тебя да хранит.","3":"Из святилища Он да поможет тебе, да пошлет подмогу с горы Сион.","4":"Да вспомнит все приношенья твои, всесожженьями да будет доволен. [Музыка]","5":"Да исполнит желания сердца твоего, твои замыслы осуществит,","6":"а нам даст ликовать о победе твоей, знамя поднять во имя нашего Бога! Да исполнит Господь все прошения твои!","7":"Я знаю, что Господь Помазанника спас, с небес Своих святых откликнулся на зов, могучею рукой ему победу даровал.","8":"У тех – колесницы, у этих – кони, а мы призвали имя Господа, нашего Бога.","9":"И вот они повержены, пали, а мы стоим – мы тверды!","10":"О Господь! Даруй победу царю, отзовись, когда мы призываем Тебя!"},"20":{"1":"[Начальнику хора: псалом Давида.]","2":"Твоя сила, Господь, – радость для царя! Как ликует он о победе Твоей!","3":"Ты исполнил все, чего он желал, не отверг Ты просьбу его. [Музыка]","4":"Благословеньями встретил его, увенчал золотым венцом.","5":"Он просил у Тебя жизнь, и Ты дал ему долголетие – навек!","6":"Твоя победа прославила его, Ты ниспослал ему величье и блеск.","7":"Ты навеки его благословил, дал пред лицом Твоим веселиться.","8":"На Господа уповает царь и по милости Вышнего не дрогнет.","9":"Твоя рука настигнет врагов, всех Твоих недругов настигнет.","10":"Когда Ты им явишь Свой лик, Ты словно бросишь их в горящую печь, гнев Господень поглотит их, пожирать их будет огонь.","11":"Ты уничтожишь их плод на земле – их потомков не будет среди живых.","12":"Против Тебя они задумали зло, строили замыслы – да не вышло!","13":"Ты в бегство их обратишь, Твой лук им нацелен в лицо.","14":"Поднимись, о Господь, в силе Своей! Мы будем славить и петь Твою мощь!"},"21":{"1":"[Начальнику хора: напев «Аййелет Ха – Шахар…». Псалом Давида.]","2":"Боже мой! Боже мой! Почему Ты оставил меня? Ты далек, не поможешь, далек от стонов моих.","3":"Боже мой! Целый день я зову Тебя – нет ответа. И ночами зову – но нет утешения мне.","4":"Ты свят, восседаешь на троне среди славословий Израиля.","5":"В Тебя верили наши отцы, в Тебя верили, и Ты их спас.","6":"Тебя звали на помощь – и обрели избавление. В Тебя верили – и не посрамились они!","7":"Я же не человек, а червь: люди поносят, презирают меня.","8":"Как увидят – смеются надо мной. Головою качают, глумясь:","9":"«Верил Господу? – пусть Тот и выручает его! Господь любит его? – пусть спасет!»","10":"Ты меня из утробы извлек, у грудей материнских баюкал.","11":"Едва выйдя из чрева – Тебе я вручен, от рожденья – Ты мой Бог.","12":"Так не будь же далек от меня! Беда все ближе и никто не поможет.","13":"Много быков обступило меня, окружили меня быки Башана!","14":"Словно лев, что над добычей рычит, на меня раскрывают свою пасть!","15":"Я как пролитая вода, кости больше не держат друг друга, сердце, как воск свечи, тает в моей груди.","16":"Моя сила что сухой черепок, мой язык к небу присох. Ты низвел меня в прах могильный.","17":"Окружили меня псы, свора злобная обложила, прокусили мне руки и ноги.","18":"Я могу пересчитать свои кости. А эти – смотрят, глядят на меня,","19":"меж собой делят одежду мою – кидают жребий, кто рубаху возьмет.","20":"О Господь, не будь вдалеке! Моя Подмога, на помощь спеши!","21":"Спаси меня от меча, сохрани мою жизнь от псов,","22":"избавь от львиных зубов, от бычьих рогов! Отзовись!","23":"Твое имя провозглашу я пред братьями моими, средь Собрания прославлю Тебя:","24":"«Чтущие Господа, хвалите Его! Племя Иакова, славь Его! Трепещи пред Ним, племя Израиля!","25":"Он не гнушался бедняком, не презирал его, не отвернулся от него, внял его воплю».","26":"Ты дал мне воспевать Тебя в Великом Собрании на глазах у чтущих Господа я обеты исполню.","27":"Досыта будут есть бедняки, Господа восхвалят призывавшие Его! И сердца ваши вовек будут живы!","28":"Обратятся, вспомнят Господа по всем концам земли, все племена людские падут ниц перед Тобой.","29":"Царская власть в руках Господа, над народами властвует Он.","30":"Падут перед Ним все, кому спать в земле, склонятся перед Ним все, кто нисходит во прах – кто утратил дыхание жизни.","31":"А дети их станут Ему служить, грядущим поколениям о Господе расскажут,","32":"возвестят тем, кто родится на свет, о Его праведности, о Его делах!"},"22":{"1":"[Псалом Давида.] Меня пасет Господь, и я ни в чем не знаю нужды:","2":"пасет на сочных лугах, у тихих вод отдохнуть дает,","3":"подкрепляет силы мои, путем правым меня ведет – ради имени Своего.","4":"Даже если по долине смертной тени пойду, мне не страшно, ведь Ты со мной. Посох, палка пастушья в Твоей руке и потому я спокоен.","5":"У моих врагов на виду накрываешь Ты стол для меня, умащаешь мне голову маслом, чаша моя полна.","6":"Да пребудут со мной доброта и любовь все время, пока я жив. В доме Господнем я поселюсь на долгие дни!"},"23":{"1":"[Псалом Давида.] Владенье Господа – земля и все, что на ней, весь мир и все, кто живет в нем.","2":"Он над морями землю воздвиг, водрузил над потоками вод.","3":"– Кто на гору Господню взойдет? Кто станет на месте Его святом?","4":"– Тот, чьи руки невинны, кто сердцем чист, не уповал на пустое, не запятнал ложью клятв.","5":"Вот кого благословит Господь, вознаградит Бог, спаситель его.","6":"Вот племя тех, кто приходит предстать пред Ним – пред лицом Твоим, Бог Иакова! [Музыка]","7":"– Выше станьте, врата! Поднимитесь, древние двери! Пусть Царь Славы войдет!","8":"– Кто этот Царь Славы? Господь, могучий и сильный. Господь, могучий воитель.","9":"– Выше станьте, врата! Поднимитесь, древние двери! Пусть Царь Славы войдет!","10":"– Кто этот Царь Славы? Господь Воинств – это Царь Славы."},"24":{"1":"[Псалом Давида.] Господи, я вручаю Тебе мою жизнь,","2":"на Тебя я надеюсь, мой Бог! Пусть не постигнет меня позор, пусть не осилит враг!","3":"Кто доверился Тебе, тех позор не ждет, опозорятся предатели, останутся ни с чем.","4":"Господь, укажи мне Твои пути, Твоим стезям научи меня.","5":"Веди меня дорогами правды Твоей, научи меня следовать им! Ведь Ты мой Бог, Ты Спасенье мое, на Тебя я надеюсь всегда.","6":"Свои милости вспомни, Господь, Свою извечную доброту.","7":"Не вспоминай грехов моей юности, злых поступков моих, а вспомни Свою доброту ко мне – Ты же добр, Господь!","8":"Добр Господь, справедлив Господь, грешников Он наставит на путь.","9":"На дорогу правды направит бедняков, научит бедных путям Своим.","10":"Пути Господни – вера и правда, они для тех, кто хранит договор с Ним и заповеди.","11":"О Господь, ради имени Твоего, прости грех мой, как бы он ни был велик!","12":"Если человек Господа чтит, Бог покажет ему, какой путь избрать.","13":"В счастье пройдет его жизнь, земля достанется потомкам его.","14":"Кто чтит Господа, тем открывает Он тайну: возвещает им Свой договор.","15":"Мои очи всегда обращены к Господу, Он извлекает ноги мои из силков.","16":"Посмотри на меня и помилуй меня, ибо я одинок и беден.","17":"В горе сердцу моему дай простор, из теснины выведи меня!","18":"Посмотри на мои беды и несчастья и прости все мои грехи.","19":"Посмотри, сколько врагов у меня, как они люто меня ненавидят!","20":"Сохрани мою жизнь, выручи, не постыжусь я, что Ты был моей надеждой.","21":"Правота и непорочность защитят меня, на Тебя вся надежда моя.","22":"Боже, избавь Израиль от всех несчастий его!"},"25":{"1":"[Псалом Давида.] Рассуди, Господи, тяжбу мою, безупречен я в жизни своей! У Господа я защиты ищу – и я не пошатнусь!","2":"Испытай меня, Господи, и проверь! Переплавь, очисть нутро и сердце мое!","3":"Твоя доброта перед глазами у меня, в своей жизни храню я верность Тебе.","4":"С людьми лживыми вместе не сяду я, с лицемерами вместе – не пойду,","5":"невыносимо мне общество злых, и с нечестивыми сидеть я не буду.","6":"В знак невинности омою я руки мои и обойду Твой жертвенник, Господи,","7":"громко буду провозглашать хвалу, возвещать о чудесных делах Твоих!","8":"Господи! Люблю я быть в доме Твоем, там, где обитает Слава Твоя.","9":"Вместе с грешными не погуби меня – вместе с теми, кто пролил чужую кровь,","10":"с теми, чья рука преступленья творит и берет взятку за взяткой.","11":"Незапятнанной идет моя жизнь, так спаси меня и помилуй!","12":"На ровную дорогу стали ноги мои. Среди собравшихся – благословляю Господа!"},"26":{"1":"[Псалом Давида.] Господь мне свет и спасение, так кого мне бояться? Господь – оплот жизни моей, так кого мне страшиться?","2":"Если злодеи подступят, чтоб растерзать мою плоть, враги мои, ненавистники, они пошатнутся и рухнут!","3":"Окружит меня вражье войско – моему сердцу не страшно! Война подступит ко мне – я полон твердой надежды!","4":"Одного я прошу у Господа, к одному стремлюсь: всю жизнь быть в Храме Господнем, созерцать красоту Господню, ждать в святилище ответа от Него.","5":"В день беды Он меня скроет под навесом у Себя, в глубине шатра Своего спрячет, на высокой скале поставит меня,","6":"даст смотреть свысока на врагов вокруг. В Его шатре я жертвы и хвалы вознесу, я буду Господа петь и славить.","7":"Господи, мой голос услышь, я зову Тебя – смилуйся, ответь!","8":"Звучат в моем сердце Твои слова: «Стремитесь увидеть лицо Мое!» И стремлюсь я увидеть лицо Твое, Господи!","9":"Не отворачивай лицо Свое от меня! В гневе не отталкивай раба Своего! Ты помощник мой! Не отвергни меня, не оставь меня, Боже, Спаситель мой!","10":"Отец мой и мать моя оставили меня, но Господь примет меня к себе!","11":"Господь! Научи меня пути Твоему! Прямым путем веди, наперекор врагам.","12":"На произвол врагов меня не отдавай! Лжесвидетели против меня выступают, обвинители расправы хотят.","13":"Но я верю, что увижу, как добр Господь, что увижу это на земле живых!","14":"– Уповай на Господа, стойким будь, пусть твердым будет сердце твое – уповай на Господа!"},"27":{"1":"[Псалом Давида.] Тебя зову я, Господь, моя Скала! Не молчи же в ответ! Если Ты будешь молчать, я стану словно мертвец.","2":"Услышь моленья мои, когда взываю к Тебе, воздев руки к святилищу святому Твоему.","3":"Вместе с нечестивцами меня не погуби, вместе с теми, кто неправду творит, кто мирно с ближними говорит, а в сердце замыслил зло.","4":"Отплати им за то, что они творят, за все злые поступки их. За дела их рук – отплати им! Дай им то, что они заслужили!","5":"В дела Господа не вникают они, в то, что руки Его сотворили. Господь снесет их до основанья и не даст отстроиться вновь.","6":"Благословен Господь – Он услышал моленья мои.","7":"Господь – сила моя, мой щит, на Него мое сердце уповает, Он помог мне – ликует сердце мое, и я прославлю Его песней моей.","8":"Господь – сила народа Своего, прибежище, спасенье для Помазанника.","9":"Даруй спасение народу Своему, благослови достоянье Свое! Будь для них Пастухом, неси их на руках Своих – навеки!"},"28":{"1":"[Псалом Давида.] Величайте Господа, Божьи сыны, величайте Господню славу и мощь!","2":"Величайте славу Господнего имени! Падите ниц пред Ним во славе Его святой!","3":"Голос Господа – над водами, Бог славы громом гремит, Господь – над просторами вод!","4":"Голос Господа – сама мощь, голос Господа – величье само,","5":"голос Господа валит кедры, Господь валит кедры Ливанские!","6":"Заставляет горы скакать! Скачут горы Ливана, словно бычок, Сирионские горы – как юный тур.","7":"Голос Господа высек искры огня.","8":"Голос Господа пустыню заставил дрожать, Господь дрожать заставил пустыню Кадеш.","9":"Голос Господа сотрясает дубы, обнажает леса. Пусть скажут все в Его Храме: «Слава!»","10":"Над бескрайними водами восседает Господь, Господь на престоле, Он царь навек.","11":"Господь даст силу народу Своему – благоденствием Свой народ одарит!"},"29":{"1":"[Псалом Давида. Песнь при торжественном открытии Храма.]","2":"Воспеваю Тебя, Господь, Ты из ямы вытащил меня, не дал врагам торжествовать надо мной.","3":"О Господь, мой Бог! Я Тебя звал, и Ты меня исцелил.","4":"Из мира мертвых вывел душу мою, оживил меня, сходящего в могилу.","5":"Верные Господу, пойте Ему, славьте имя святое Его.","6":"Гнев Его – на одно мгновение, а милость Его на всю жизнь; вечером водворится плач, а наутро настанет радость.","7":"В дни благоденствия думал я, что мне паденье вовек не грозит.","8":"О Господь, когда была на то воля Твоя, Ты меня делал могучим, как гора. Но вот, Ты отвернулся – и я в смятеньи.","9":"Я воззвал к Тебе, Господи, взмолился к Владыке моему.","10":"Разве есть Тебе польза в моей крови – в том, чтоб я в могилу сошел? Разве прах могильный славит Тебя? Говорит о правде Твоей?","11":"Услышь, Господи, и помилуй меня! О Господь! Будь помощником мне!","12":"Плач мой Ты обратишь в ликование, снимешь рубище с меня и в веселье облачишь.","13":"Мое сердце Тебя будет воспевать, не умолкая. Буду славить Тебя вечно, о Господь, мой Бог."},"30":{"1":"[Начальнику хора: псалом Давида.]","2":"Господь, Ты защита моя, я не посрамлюсь вовек! Яви справедливость, спаси!","3":"Склони ко мне ухо Твое, поспеши избавить меня, будь мне скалой и оплотом, прибежищем и спасением.","4":"Ты – утес мой, твердыня моя, веди меня, направляй мой путь ради имени Твоего!","5":"Избавь меня от сетей и ловушек. Ты защита моя!","6":"Я вручаю Тебе свой дух. О Господь, верный Бог, спаси!","7":"Я не с теми, кто чтит тщету и ничто, я на Господа уповаю.","8":"Я ликую, видя Твою доброту: Ты узнал про мою беду, и Ты понял, как тяжко мне,","9":"Ты не отдал меня врагу, Ты выводишь меня на простор.","10":"Сжалься, Господь: тяжко мне, воспалились от горя глаза, и душа, и нутро мое.","11":"Жизнь моя тает от горя, годы мои – от стонов; за грехи моя сила увяла, и мои кости иссохли.","12":"Надо мной глумятся враги и даже соседи мои, друзьям страшно смотреть на меня, встретив на улице, прочь спешат.","13":"Я забыт, как будто мертвец, я как будто разбитый горшок.","14":"О себе слышу сплетни везде, окружает меня ужас: люди против меня сговорились, замышляют меня убить.","15":"На Тебя я надеюсь, Господь, говорю: «Мой Бог – это Ты».","16":"В Твоей власти – вся моя жизнь. Спаси меня от гонителей и врагов,","17":"на меня светлым взором взгляни, спаси раба Твоего, ведь Ты добр.","18":"Пусть же мне не придется стыдится, что Тебя, Господь, я призывал! Пусть срам покроет злодеев, пусть в Шеоле смолкнут они!","19":"Пусть онемеют их лживые уста, что праведного злобно, со спесью поносят!","20":"О, какое сокровище Ты приготовил для чтущих Тебя, для уповающих на Тебя приготовил – у всех на глазах!","21":"Ты скрываешь их под сенью лица Своего, укрываешь от злобы людской, даешь убежище от клеветы.","22":"Благословен Господь! Я был словно в осаде – Он явил мне милость Свою!","23":"Я подумал в смятении моем: «Ты не хочешь смотреть на меня». Но Ты услышал мою мольбу, когда я Тебя призывал.","24":"Любите Господа, все, кто предан Ему! Верных Господь хранит, а гордецам – отплатит с избытком.","25":"Мужайтесь, да будет ваше сердце твердо, все уповающие на Господа!"},"31":{"1":"[Псалом Давида; песнь искусная.] Блажен тот, чья вина прощена и чей грех стерт,","2":"блажен, кому Господь не поставит в вину проступки его, и чей дух – без лукавства.","3":"Я умолк, рассыпаются кости мои, весь день я кричу.","4":"Днем и ночью я чувствую руку Твою – как она тяжела! Мой язык пересох, словно летом, в жару. [Музыка]","5":"Я открыл Тебе свой грех, не скрывал своего паденья; я решился: «Вину мою Господу открою!» – и Ты простил мне падение, грех мой. [Музыка]","6":"Пусть Тебе всякий праведник молится во время беды, и тогда многоводный потоп до него не дойдет.","7":"Ты прибежище мне, Ты меня охраняешь от бед, Ты меня спас, и кругом меня – радость об этом! [Музыка]","8":"«Я тебя вразумлю и научу, каким путем идти, Я твой советчик, Я смотрю за тобой.","9":"Не будьте неразумными как конь или мул, чей бег укрощают уздой и удилами – чтобы они подошли к тебе».","10":"Много бед ждут нечестивого, а милость Господня – вокруг того, кто уповает на Него.","11":"Пусть Господь будет для праведных весельем и радостью! Да ликуют все, чье сердце чисто!"},"32":{"1":"Радуйтесь, праведники, о Господе – хвала Господу праведных украшает.","2":"Славьте Господа звуками лиры, игрой на арфе десятиструнной.","3":"Пойте Ему новую песнь, стройно играйте, восклицайте от радости!","4":"Ибо истинно слово Господне, все дела Его справедливы.","5":"Правда и праведность угодны Ему, Его добротою полна земля.","6":"Словом Господа созданы небеса, дуновеньем уст Его – все воинство их.","7":"Он собрал, как в бурдюк, воду морей, пучины вод под замок поместил.","8":"Пусть трепещет пред Господом вся земля, все обитатели мира пусть трепещут пред Ним.","9":"Он сказал – и стало. Он повелел – и свершилось!","10":"Замыслы народов разрушил Господь, решенья народов в ничто обратил!","11":"А Господне решенье вовек неизменно, что Он постановил – то из века в век.","12":"Счастлив народ, чей Бог – Господь! Народ, избранный Им, – достоянье Его!","13":"Смотрит Господь на землю с небес, всех сынов человеческих видит,","14":"с престола Своего взирает Господь на людей, на земле живущих.","15":"Сердца всех Он сотворил и знает все их дела.","16":"Не защитит царя огромное войско, не спасет богатыря его мощь.","17":"Конь подведет, не сможет помочь, не спасет никакая сила.","18":"Обращены очи Господа к чтущим Его, к уповающим на милость Его.","19":"Он их спасет от смерти, в годину голода даст им выжить.","20":"На Господа мы уповаем, Он нам – помощь и щит.","21":"Наше сердце ликует о Нем, Его имя святое – нам надежда.","22":"Да будет с нами милость Твоя, Господь! Мы надеемся на Тебя."},"33":{"1":"[Сложено Давидом после того, как он притворялся безумным перед Авимелехом, и тот прогнал его, и Давид ушел от него.]","2":"Ежечасно я Господа благословляю, хвала Ему всегда на устах моих,","3":"прославляет Господа моя душа – бедняки меня услышат и обрадуются.","4":"Славьте Господа вместе со мной, будем вместе воспевать Его имя.","5":"Я обратился к Нему – и ответил Он, от всех страхов меня избавил.","6":"Сияют лица тех, кто смотрит на Него, и этих лиц не покроет срам.","7":"Взывает бедняк – его слышит Господь, от всех бед спасает его.","8":"Ангел Господень стражу несет вокруг чтущих Его – и хранит их.","9":"Вкусите и увидите, как благ Господь, счастлив тот, кто уповает на Него,","10":"Чтите Господа, все святые Его, у тех, кто чтит Его, ни в чем нет нужды.","11":"Львы терпят бедность и голод, кто ищет Господа – не знает нужды.","12":"Подойдите, дети, и слушайте меня, я научу вас Господа чтить.","13":"Кто из вас хочет жить, желает видеть счастливые дни?","14":"Пусть тот удержит язык свой от зла, и уста – от лживых речей.","15":"Пусть отвернется от зла и творит добро, ищет мира и стремится к нему.","16":"Очи Господа к праведным обращены, Его уши слышат их зов.","17":"Свой гневный взор на злодеев Господь устремит – так, что и памяти о них не останется.","18":"Кто к Нему взывает, тех слышит Господь, из любой беды выручает.","19":"Господь рядом с теми, чье сердце разбито, и спасет тех, чей дух сокрушен.","20":"Много бед праведного ждет, но от всех его спасает Господь.","21":"Хранит в целости все кости его, ни одна их них не сломается.","22":"Зло само грешника умертвит, кто ненавидит праведника – поплатится.","23":"Господь вызволяет жизнь Своих рабов, кто уповает на Него – избегнет кары."},"34":{"1":"[Сложено Давидом.] Суди, Господь, тех, кто судит меня; борись с теми, кто борется со мной.","2":"Щит и броню возьми и заступись за меня.","3":"Копье и топор возьми, встречай тех, кто гонит меня! Скажи мне, что Ты – спасенье мое!","4":"Пусть покроют срам и позор тех, кто гибели жаждет моей; пусть уйдут со стыдом те, кто хотят мне зла.","5":"Да будут мякиной на ветру, и ангел Господень да развеет их;","6":"темен, скользок да будет их путь, и ангел Господень да гонит их.","7":"Ни за что они ставят мне сети, ни за что – мне копают яму.","8":"Да придет им нежданный конец, да попадутся в свои же сети, да попадут туда в час конца!","9":"Как душа моя рада, что рядом Господь! Как ликует, спасенная Им!","10":"Мои кости взывают к Нему: «Господь! Кто подобен Тебе?! Ты спас слабого от рук сильного, бедного, нищего – от грабителей!».","11":"На суде поднимаются клеветники, о том, чего я не знаю, ведут допрос;","12":"за добро они отплатили мне злом. Ждут в засаде, чтобы отнять мою жизнь.","13":"А я ведь в рубище ходил, когда болели они, я себя изнурял постом. (Да зачтется мне молитва моя!)","14":"Я был словно их друг и брат; я горевал, будто оплакивал мать.","15":"А я в беде – они собрались, смеясь, собрались, когда я сокрушен. Не понимаю, за что беспрестанно терзают меня,","16":"как нечестивые – глумятся, глумятся и скрежещут зубами на меня.","17":"Господь! Доколе Ты будешь смотреть? От их козней спаси мою жизнь – мою единственную жизнь – от хищных львов.","18":"Я пред всей общиной Тебя воспою, пред всем народом прославлю Тебя.","19":"Не дай ликовать тем, кто понапрасну ненавидят меня, не дай довольно подмигивать тем, кто ни за что стал моим врагом!","20":"Не о мире толкуют они, против невинных людей строят козни!","21":"Раскрывают на меня свою пасть, говорят: «Вот – вот! Мы все видели!»","22":"Ты, Господь, видишь! Ты видишь все, не молчи! Господь! Не покидай меня!","23":"Подымись, пробудись, рассуди мое дело, Бог и Господь мой, мою тяжбу реши!","24":"Суди меня справедливо, Господь, Бог мой, пусть не торжествуют они надо мной.","25":"Пусть не думают: «Вот! Все как мы хотели!» Пусть не думают: «Вот, мы сожрали его!»","26":"Пусть опозорятся, осрамятся все, кто рад моему несчастью, пусть покроет стыд и бесчестье тех, кто мнит себя выше меня.","27":"А те, кто мне желал добра, пусть ликуют и торжествуют, пусть всегда повторяют: «Велик Господь, желающий счастья рабу Своему!»","28":"Мой язык воспоет справедливость Твою, ежедневно будет славить Тебя."},"35":{"1":"[Начальнику хора. Сложено Давидом, рабом Господним.]","2":"Грех мил нечестивцу, он – в сердце его, а страх Божий неведом ему.","3":"Лжет он самому себе, будто вину свою увидев, отвратился от нее.","4":"Слова уст его – беззаконие и ложь; не стремится ни к мудрости он, ни к добру,","5":"на ложе своем замышляет беззаконие, на путь недобрый становится, не гнушается злом.","6":"Господи! Милость Твоя до небес, истина Твоя до облаков!","7":"Правда Твоя – горы Божий, правосудие Твое – бездна великая! И людей и скот спасешь Ты, Господи!","8":"Как драгоценна милость Твоя, Боже! В безопасности люди под сенью крыл Твоих.","9":"Насыщаются яствами Дома Твоего, Ты поишь их потоками сладости Твоей.","10":"Ибо у Тебя – источник жизни, мы во свете Твоем увидим свет.","11":"Одари Своей милостью тех, кто знает Тебя, Своей праведностью – тех, чье сердце честно.","12":"Пусть гордыня не подступит ко мне, пусть рука злодея не столкнет меня.","13":"Наземь пали творящие зло! Низвержены – и не подняться им!"},"36":{"1":"[Псалом Давида.] Не завидуй злодеям, пусть не волнуют тебя удачи злых.","2":"Как трава, они скоро будут скошены, словно зелень полей – увянут.","3":"Положись на Господа, делай добро; живи на земле, храни верность.","4":"Ищи себе радость в Господе, и Он даст, чего просит сердце Твое.","5":"Вручи Господу свою жизнь, положись на Него – и Он все сделает:","6":"твоя правда взойдет как заря, правота твоя – как солнце в полдень.","7":"Безмолвно предстань пред Господом, на Него возложи надежду. Не завидуй преуспевающим, людям, погрязшим во лжи.","8":"Не гневайся и не злись, не завидуй – до добра не доведет!","9":"Злодеи уничтожены будут, земля достанется уповавшим на Господа.","10":"Еще немного – и не станет нечестивца. Туда посмотришь, где он был – и уже нет его.","11":"Земля достанется беднякам, и насладятся они благоденствием.","12":"Злоумышляет нечестивый против праведника и от злости скрежещет зубами.","13":"Но смеется над ним Господь, видя, что близок день отмщенья ему.","14":"Нечестивые меч обнажили и натянули свой лук, чтобы бедного и нищего сразить, идущих правым путем – зарезать.","15":"Пусть их меч им в сердце вонзится, и пусть луки их разломаются!","16":"Лучше малый достаток праведника, чем великое богатство злодеев.","17":"Нечестивцам будут сломаны руки, а праведным Господь дает силу.","18":"Вся жизнь добрых – пред очами у Господа, их надел – за ними навек.","19":"В дни беды им не придется стыдиться, во время голода будут сыты.","20":"А злодеи уничтожены будут, враги Господа исчезнут как дым, как трава полевая исчезнут.","21":"Негодяй берет взаймы – и не отдаст! А праведник щедро взаймы дает.","22":"Земля достанется тем, кого Бог благословил, и погибнут те, кого Он проклял.","23":"Шаги достойного Господь сделал твердыми, и пути его Господу угодны,","24":"даже если упадет – не разобьется: Господь за руку поддержит его.","25":"Был я молод, теперь старик уже – но не видел я праведника брошенным, а потомков его просящими милостыню.","26":"Он всегда щедро взаймы дает, и благословенно потомство его!","27":"Будь от зла в стороне и твори добро, и будешь ты жить вовек.","28":"Правосудие Господу дорого: верных Ему не покинет Он. Вовек сохранятся они, а род злодеев будет уничтожен.","29":"Праведным достанется земля, и они вечно будут жить на ней.","30":"Уста праведника изрекают мудрость, его язык возвещает правосудие,","31":"Закон Бога в сердце его, он идет – и тверды шаги его.","32":"Нечестивец следит за праведником, ищет, как бы его убить.","33":"Но не выдаст Господь ему праведника, не даст оклеветать на суде!","34":"Уповай на Господа, следуй пути Его, и Он хозяином земли тебя сделает! И ты увидишь, как погибнут нечестивые.","35":"Видел я нечестивца грозного, он возвышался как кедр зеленеющий.","36":"Но вот, прошло время – и нет его. Стал я искать – и не нашел его.","37":"Смотри на кроткого, смотри на праведного: кто живет мирно, у того есть будущее.","38":"А преступники все будут уничтожены, и нет будущего у нечестивых.","39":"От Господа придет спасенье к праведным, во время беды Он им прибежище.","40":"Господь им поможет, избавит их, от нечестивых избавит и спасет их – ибо искали они защиты у Него!"},"37":{"1":"[Псалом Давида. Громко, вслух.]","2":"О Господь! Не карай меня в ярости Своей! В Своем гневе меня не казни!","3":"Стрелы Твои в меня впились, Твоя рука настигла меня.","4":"На теле здорового места нет – это сделала ярость Твоя. Не знают покоя кости мои – это мне за мои грехи.","5":"С головою грехи накрыли меня, я не в силах нести их груз.","6":"Смердят и гноятся раны мои, это мне за безумье мое.","7":"Сгорбился я, до земли поник, я весь день хожу горем объят.","8":"Поясницу терзает боль, на теле целого места нет.","9":"Я изнемог, я разбит, из глубин нутра стоны идут.","10":"Господь! Ты знаешь, о чем я прошу, и не скрыт от Тебя мой вздох.","11":"Сердце трепещет, нет больше сил, и свет меркнет в моих глазах.","12":"Друзья мои, знакомые гнушаются больным, близкие в отдаленьи стоят.","13":"…Мне ловушки ставят, хотят убить, мне желают зла и проклятья твердят, на меня клевещут весь день.","14":"Но не слышу я – как глухой, как немой, я рта не раскрыл.","15":"Словно стал я слуха лишен, словно я отвечать не могу.","16":"На Тебя, Господь, я надеюсь, жду – Ты отзовешься, Господь мой, Бог мой!","17":"Молю: пусть надо мной не глумятся они, не торжествуют, что пошатнулся я!","18":"Я уже вот – вот упаду. Боль моя неразлучна со мной.","19":"Исповедаю я свой грех. Я скорблю о своей вине.","20":"А враги мои живы, сильны, много их: без причин ненавидят меня.","21":"Они воздают мне злом за добро: я хочу добра – мне за это мстят!","22":"Не оставь меня, о Господь, мой Бог! Не покидай меня!","23":"Поспеши, помоги мне! Мой Господь! Спасенье мое!"},"38":{"1":"[Начальнику хора: напев Едутуна. Псалом Давида.]","2":"Я решил: буду следить за путями своими и не дам языку согрешить, надену узду на свои уста, пока злодей стоит передо мной.","3":"Я был нем и безгласен, я молчал, лишаясь всего, и горе мое росло.","4":"Мое сердце в груди меня жгло, мои мысли огнем загорелись, и тогда я заговорил:","5":"«Скажи, Господи, когда же кончина моя, сколько дней мне еще остается, дай мне знать, каков мой век.","6":"Ты отмерил мне дней – считанные пяди, весь мой век – ничто пред Тобою. Человек стоит – как мираж. [Музыка]","7":"Человек ходит как тень, ради миража суетится, собирает – и не знает для кого.","8":"Чего еще ждать мне, Господи? Надежда моя – на Тебя.","9":"От моих беззаконий спаси меня, не отдай глупцам на поругание.","10":"Я стал нем, я рта не раскрыл, ведь все, что ныне со мной, – сделал Ты.","11":"Отклони от меня кару Твою: я исчезаю от ударов руки Твоей.","12":"Ты наказываешь человека, за преступления караешь его, как моль, подточил то, что ему дорого… Любой человек – мираж! [Музыка]","13":"Услышь, Господи, молитву мою и внемли моему стону, не молчи, видя слезы мои, у Тебя я бесправный странник, переселенец, как и отцы мои.","14":"Отверни от меня Свой взор, дай вкусить хоть немного радости, прежде чем я уйду и не будет меня»."},"39":{"1":"[Начальнику хора: псалом Давида.]","2":"Я надеялся на Господа, надеялся и ждал, Он склонился ко мне и услышал мой крик.","3":"Из смертной ямы Он поднял меня, из трясины болотной вытащил, Он поставил меня на твердой скале, дал ногам моим крепко стоять.","4":"Новую песнь вложил мне в уста – хвалу нашему Богу. Многие, увидев это, станут трепетать, и Господь будет их надеждой!","5":"Блажен, кто на Господа уповает, кто не идет к гордецам и к тем, кто с ложью блудит!","6":"Господь, Бог мой! Сколько Ты всего сотворил, сколько чудес Ты задумал о нас – никто не в силах сравниться с Тобой! Я буду говорить и проповедовать о них, но они так велики, что не расскажешь!","7":"Ни жертв, ни приношений не хочешь Ты, ни всесожжении, ни жертв очистительных. …Ты отверзаешь мой слух.","8":"…И я сказал: «Вот я. Я пришел. Про меня написано в свитке.","9":"Бог мой! Я хочу исполнить волю Твою, Твой закон у меня в сердце».","10":"Я возвестил о правде Твоей, не стал молчать среди Великого Собранья, о Господь, – Ты ведь и Сам это знаешь!","11":"Твою правду в себе я не стал таить, я поведал, что Ты верный заступник. Средь Великого Собранья не стал я скрывать Твою верность и доброту.","12":"О Господь, не лиши меня милости Своей! Доброта Твоя и верность пусть всегда меня хранят!","13":"Окружили меня беды, им нет числа. Мои грехи настигли меня и застят взор. Их больше, чем волос на моей голове, и мое сердце мне изменило!","14":"Господи! Будь ко мне добр и спаси меня! На помощь, Господи, поспеши!","15":"Да покроют срам и позор тех, кто хотел погубить мою жизнь. Пусть с позором уйдут назад те, кто желал мне зла.","16":"Пусть, пристыженные, отвернутся, кто надо мной насмехался: «Вот, вот он!»","17":"А у тех, кто стремится к Тебе, пусть настанут веселье и радость. Пусть всегда говорят: «Как велик Господь», те, кто любят Тебя, о Заступник!","18":"Я беден и нищ, но печется Господь обо мне. Ты помощник мой и спаситель, так не медли же, Боже мой!"},"40":{"1":"[Начальнику хора: псалом Давида.]","2":"Блажен, кто заботится о бедняке, – Господь спасет его в день беды.","3":"Господь сохранит его, даст ему жизнь, и счастье пошлет на земле. – Ты врагам не выдашь его!","4":"На одре болезни Господь даст ему силы. – Ложе больного Ты преобразишь!","5":"Молюсь я: «Господи! Помилуй меня! Исцели меня, грешен я пред Тобой!»","6":"А враги мои злобно толкуют про меня: «Когда ж умрет он – чтобы исчезла и память о нем?»","7":"Приходят меня посетить – и лгут, в сердце злобу копят, выйдут – всем разгласят.","8":"Друг с другом шепчутся про меня, и их мысли злобой полны:","9":"«Сатанинская напасть настигла его! Он слег – и ему не встать!»","10":"Даже тот, кто был мне другом, кому я доверял, кто ел мой хлеб – и тот готов растоптать меня.","11":"Господи! Помилуй меня, подыми меня – я им отплачу.","12":"Если враг надо мной не прокричит победный клич, то я пойму, что я угоден Тебе.","13":"Невредимым и целым Ты поддержишь меня, навек меня сохранишь пред лицом Твоим!","14":"Благословен Господь, Бог Израиля, от века и до века! Аминь, аминь!"},"41":{"1":"[Начальнику хора: псалом сынов Кореевых; песнь искусная.]","2":"Как олень стремится к потокам воды, так душа моя жаждет Тебя, Боже!","3":"Душа моя жаждет Бога, Бога живого! Когда приду и явлюсь пред лицо Божие?","4":"День и ночь слезы стали пищей моей, каждый день слышу я: «Где же Бог твой?»","5":"Вспоминаю об этом – и плачет душа моя. Но я приду в обитель Прославленного, в дом Божий, под звуки радости, среди славословий людей ликующих.","6":"Что ж ты унываешь, душа моя, и что ты печальна? Уповай на Бога! Я еще буду славить Его, Он мой спаситель и Бог мой.","7":"Унывает душа моя, я о Тебе вспоминаю на земле Иорданской, на горах Хермонских, горе Мицар.","8":"Пучина зовет пучину голосом водопадов Твоих; все валы и волны Твои надо мною прошли.","9":"Днем явит Господь милость Свою, и ночью песнь Ему у меня на устах, молитва к Богу жизни моей.","10":"Скажу Богу, Твердыне моей: почему Ты меня забыл? Почему я поникший хожу и меня оскорбляет враг?","11":"Словно кости мои все перебиты! Меня дразнят мои враги, каждый день говорят: «Где же Бог твой?»","12":"Что ж ты унываешь, душа моя, и что ты печальна? Уповай на Бога! Я еще буду славить Его, Он мой спаситель и Бог мой."},"42":{"1":"Будь, Боже, моим судьей и рассуди тяжбу мою. От народа неправедного, от людей лживых и подлых избавь меня,","2":"Ты – Бог мой и Сила моя. Для чего Ты оставил меня? Почему я поникший хожу и меня оскорбляет враг?","3":"Пошли свет Твой и истину Твою, пусть они поведут меня, приведут на святую Твою гору и в жилище Твое.","4":"Подойду я к жертвеннику Божьему, к Богу радости и веселия моего, и на арфе прославлю Тебя, Боже, Бог мой!","5":"Что же ты унываешь, душа моя, и что ты печальна? Уповай на Бога; я еще буду славить Его, Он мой спаситель и Бог мой."},"43":{"1":"[Начальнику хора: псалом сынов Кореевых; песнь искусная.]","2":"Мы слышали, Боже, своими ушами рассказы наших отцов о том, что Ты сделал в их времена, в те далекие дни:","3":"Своей рукою Ты другие народы убрал – а их насадил, как сад, все прочие племена сокрушил – а им даровал простор.","4":"Не мечом они эту землю добыли, не их сила победу им принесла, но рука Твоя, десница Твоя! Твой взор был светел – Ты был за них!","5":"Ты, о Боже, мой царь! Ниспошли спасенье Израилю!","6":"С Тобой мы – как быки – забодаем врагов, с Твоим именем их растопчем.","7":"Не на лук мой надежда моя, и не меч мой – спасенье мое.","8":"Это Ты нас спас от врагов, наших недругов посрамил.","9":"Мы весь день восхваляем Бога, вечно славим имя Твое! [Музыка]","10":"– Что ж Ты нас опозорил, отверг, с нашим войском уже не идешь?","11":"Обратил нас вспять перед недругом, нашу землю враги разорили!","12":"Отдал нас как овец на убой, нас рассеял по всем народам,","13":"ни за что уступил Свой народ, за бесценок продал его!","14":"На посмешище отдал соседям, на бесчестие и поругание,","15":"сделал притчею во языцех, все народы на нас кивают.","16":"Мой позор весь день предо мною и лицо покрыто стыдом –","17":"поношенья и ругань вокруг, смотрят мстительные враги.","18":"Да, все это случилось с нами – все равно мы Тебя не забыли, договор с Тобой не нарушили,","19":"и не дрогнули наши сердца, мы не сошли с Твоего пути.","20":"Ты сокрушил нас там, где бродят шакалы, Ты в смертную тьму погрузил нас.","21":"Если б мы забыли имя Бога нашего, к чужому богу простерли руки,","22":"разве скрылось бы это от Бога? Знает Он, что таится в сердце!","23":"За Тебя нас каждый день убивают, мы стали словно овцы на бойне.","24":"Вступись, Господь! Что Ты спишь?! Пробудись! Не бросай нас навеки!","25":"Зачем Ты от нас отвернулся? Не видишь нашего горя и бед?","26":"Наша жизнь повержена в пыль, наши тела прижаты к земле.","27":"Встань и помоги нам! Будь же милостив к нам, спаси!"},"44":{"1":"[Начальнику хора: напев «Шошаним…». Псалом сынов Кореевых; песнь искусная; песнь любовная.]","2":"Слово возвышенное из сердца рвется: вслух читаю я творение свое – о царе! Мой язык – что перо писца искусного.","3":"Ты – прекраснейший из людей, уста твои – благодати источник, так, навек, благословил тебя Бог!","4":"Повяжи свой меч у бедра, возвеличься силой и славой.","5":"Да будет успешен твой путь, вперед выезжай – во имя правды, смиренья, справедливости! Пусть подвиги свершит твоя рука!","6":"Стрелы твои остры, народы у ног твоих. Пали духом враги царя.","7":"Твой престол, как престол Божий, стоит во веки веков. Жезл твой царский – справедливости жезл.","8":"Ты любишь правду, ты ненавидишь зло, за это Бог – твой Бог – елеем радости помазал тебя, как никого из тех, кто рядом с тобой!","9":"Одеянья твои – в мирре, в алоэ и в кассии, из чертогов слоновой кости веселят тебя арфы.","10":"Царские дочери – в почетной свите твоей, стала царица одесную тебя, в золоте Офирском.","11":"Слушай, девица, посмотри и вслушайся, забудь свой народ и дом отца своего.","12":"Воспламенится царь желаньем красоты твоей, он – твой господин, поклонись ему!","13":"О дочь Тира! Богатейшие из народа, с дарами, будут милости твоей искать!","14":"Величава дочь царская в покоях своих, одеянье ее золотом украшено,","15":"в расшитой одежде ее подводят к царю. За ней ведут к тебе дев, подружек ее.","16":"С весельем, с ликованием подходят они, входят в чертог царя.","17":"Твои потомки займут место предков твоих, по всей земле ты их поставишь правителями.","18":"Твое имя поминать буду в роды родов, во веки веков народы прославят тебя."},"45":{"1":"[Начальнику хора. Сынов Кореевых. Напев «Аламот…». Песнь.]","2":"Бог – прибежище наше и сила, помощь в любой беде,","3":"нам не страшно, когда трясется земля, когда горы рушатся в глубь морей.","4":"Шумят и кипят воды, содрогаются горы, вздымаясь. [Музыка]","5":"Вот река, чьи потоки веселят Божий город, святое жилище Вышнего.","6":"Бог посреди него, и город не дрогнет: придет утро – Бог поможет ему.","7":"Шумят народы, волнуются царства; Бог подал голос – и тает земля.","8":"Господь сил с нами, наш оплот – Бог Иакова. [Музыка]","9":"Придите, взгляните, что сделал Господь, как Он землю пустыней сделал,","10":"положил конец войнам по всей земле, сломал луки и копья и сжег колесницы.","11":"Утихните, знайте, что Я – Бог: Я возвышусь над народами, над всею землей!","12":"Господь сил с нами, наш оплот – Бог Иакова. [Музыка]"},"46":{"1":"[Начальнику хора: псалом сынов Кореевых.]","2":"Все народы! Рукоплещите и криками радости Бога славьте!","3":"Ибо страшен Господь Всевышний – Царь Великий над всею землею.","4":"Он народы поверг пред нами, к нашим стопам племена поверг,","5":"Сам выбрал землю, которой мы будем владеть, – достояние Иакова, любимого Богом! [Музыка]","6":"Подымается Бог, восклицанья несутся! Подымается Господь, и трубят в рог!","7":"Пойте же Богу хвалу, пойте! Царю нашему пойте хвалу, пойте!","8":"Бог – это Царь над всею землей, пойте искусную песнь!","9":"Воцарился над всеми народами Бог! Бог воссел на престоле Своем святом!","10":"Вожди народов – с народом Авраамова Бога! Властелины земли обратились к Богу! Бог – вознесен над всеми!"},"47":{"1":"[Песнь. Псалом. Сынов Кореевых.]","2":"Господь велик. Прославляют Его в городе нашего Бога. Там святая Его гора,","3":"краса вершин, радость всей земли гора Сион, Цафонские склоны, город великого Царя.","4":"Бог – в твердынях его, Бог – надежный оплот.","5":"Соединились цари, вместе пустились в путь;","6":"увидели, изумились, устрашились, бежали;","7":"трепет их охватил, муки, будто при родах,","8":"будто восточный ветер крушит корабли Таршишские.","9":"Все, что слышали мы, – мы видим, что это правда, в городе Господа воинств, в городе нашего Бога, Бог его основал – навек!","10":"О Твоей доброте – наши мысли во Храме Твоем, Боже.","11":"Твое имя и слава, Боже, достигают концов земли; и в руке Твоей правосудие.","12":"Да веселится гора Сион, и да радуются девы Иудеи о правосудии Твоем.","13":"Обступите Сион, обойдите его, сосчитайте башни его;","14":"в вашем сердце да будут стены его, в вашей памяти – твердыни его, чтоб рассказать поколениям будущим.","15":"Этот Бог – Он навек наш Бог, и во веки веков наш вождь."},"48":{"1":"[Начальнику хора. Сынов Кореевых. Псалом.]","2":"Слушайте, все народы; внимайте, жители мира, –","3":"и простые и знатные, и богатый и бедный.","4":"Мои уста возвестят вам мудрость, мое сердце научит знанию.","5":"Мое ухо внимает притчам, под звуки лиры загадку раскрою.","6":"Чего бояться мне в день беды? Вокруг – коварство и зло!","7":"Вы, кто надеется на силу свою и похваляется богатством своим!","8":"Человек не выкупит ближнего – нет, не купит у Бога жизнь для него –","9":"слишком уж дорог выкуп! Исчезает человек навсегда.","10":"Разве будет он вечно жить? Разве он не увидит могилы?","11":"Видишь: мудрые умирают, все равно, что глупцы и невежды, – гибнут и оставляют чужим богатство свое.","12":"Могила теперь для них – вечный дом. Таково их жилище на веки веков. Так нарекли они свои владенья именами своими!","13":"Невдомек человеку, пока он в почете, что он подобен обреченным животным.","14":"Таков их путь – а как надежен он казался для них! Вот чем он кончится – а как он нравился им! [Музыка]","15":"Как овец их загонят в Шеол; их пастухом будет Смерть, и сойдут они прямо в глубь. Придет утро – их облик растает; Шеол будет жилищем их.","16":"(Да спасет меня Бог от рук Шеола, и да примет меня к Себе!)","17":"Не трепещи перед тем, кто стал богачом, когда слава его дома все растет.","18":"Умрет он – с собою не возьмет ничего, и не пойдет его слава за ним.","19":"Пусть величают его, пока жив, – когда ты счастлив, все хвалят тебя! –","20":"все равно он уйдет к отцам, что не увидят света вовек.","21":"Невдомек ему, пока он в почете, что он подобен обреченным животным."},"49":{"1":"[Псалом Асафа.] Бог богов, Господь, начинает речь, призвав всю землю, от востока до запада.","2":"С Сиона, из обители красоты, Бог являет Себя,","3":"грядет Бог наш! Не в безмолвии Он: пред Ним пылает огонь, а вокруг Него грозная буря.","4":"Он призывает небесную высь и землю – судить народ Свой!","5":"– Соберите ко Мне тех, кто верен Мне, кто над жертвой заключил договор со Мной!","6":"Небеса подтверждают правду Его, и Бог совершает суд. [Музыка]","7":"– Слушай, народ Мой, Я буду говорить, Израиль! Я буду тебя обвинять, ибо Я – Бог, твой Бог.","8":"Не за жертвы Я буду тебя укорять: всесожженья твои – предо Мной;","9":"но не приму Я твоих быков и козлов из загонов твоих,","10":"ибо все звери в лесу – Мои, и все животные на тысячах гор,","11":"знаю Я всех птиц на горах, и вся живность полевая – Моя.","12":"Будь Я голоден – не стал бы Я тебя просить: Мой – весь мир и все, что в нем есть.","13":"Но разве ем Я мясо быков, разве Я пью кровь козлов?","14":"Принеси Богу жертву благодаренья обеты, данные Вышнему, исполни.","15":"Ты призовешь Меня в день беды: спасу тебя, и ты прославишь Меня.","16":"А грешнику Бог ответит: – Зачем ты говоришь про законы Мои, твердишь про договор со Мной,","17":"а сам презрел наставление Мое, отвергаешь Мои слова?","18":"Видишь вора – и дружишь с ним, общаешься с прелюбодеями;","19":"уста твои изрыгают зло, язык твой сплетает ложь;","20":"сидишь и клевещешь на брата твоего, на сына матери твоей наговариваешь!","21":"Ты это сделал – Я промолчал, и ты решил, что Я такой же, как ты. Нет! Я изобличу тебя и предъявлю обвинение тебе.","22":"Задумайтесь об этом, забывшие Бога, Я схвачу – и не поможет никто.","23":"Меня чтит приносящий жертву благодарения, кто встал на Путь, тому явлю Я спасение Божье."},"50":{"1":"[Начальнику хора: псалом, сложенный Давидом, когда к нему пришел пророк Нафан; было это после того, как Давид овладел Вирсавией.]","3":"Помилуй меня, милосердный Бог! Многомилостивый, мои грехи сотри!","4":"Нечистоту мою отмой, отстирай, очисти меня от греха!","5":"Я знаю свою вину, мой грех всегда перед глазами у меня.","6":"Пред Тобой, Тобой одним, я согрешил, у Тебя на глазах сделал зло. Так что правдивы Твои слова, и Твой суд справедлив.","7":"Едва я родился, грех был со мной, едва мать меня зачала.","8":"Правда о сокрытом угодна Тебе; Ты показал, что Твоя мудрость знает тайны.","9":"Окропи меня иссопом – я стану чист, омой меня – буду снега белей.","10":"Весельем, радостью наполни мой слух, Ты сокрушил мои кости – пусть отрада им будет!","11":"От проступков моих отверни Свой взор и сотри все мои грехи.","12":"Сотвори, Боже, чистым сердце мое, дай духу правды вновь жить во мне.","13":"Не гони меня прочь от лица Своего, святого духа Своего не лишай.","14":"Верни мне радость – быть спасенным Тобой, духом благим поддержи.","15":"Научу я заблудших Твоим путям, и согрешившие вернутся к Тебе.","16":"От кровавой доли спаси меня – Боже, Боже спасения моего! – и мой язык прославит правосудие Твое.","17":"Отверзи, Господь, мои уста, и они восхвалят Тебя!","18":"Не хочешь Ты, чтоб я жертву принес, всесожжения неугодны Тебе.","19":"Жертва Богу – сокрушенный дух, сокрушенного сердца не отвергнет Бог.","20":"Будь милостив, Сиону помоги, стены Иерусалима построй!","21":"И тогда Ты примешь оправдательные жертвы – жертвы всесожжения, всецелые жертвы; тогда быков вознесут на Твой алтарь."},"51":{"1":"[Начальнику хора. Песнь искусная, сложена Давидом после того, как Доэг – эдомитянин пришел и донес Саулу: «Давид пришел к Ахимёлеху».]","3":"Что ты хвалишься злым делом, храбрец? Верность Божия не знает конца!","4":"Твой язык преступление замыслил; он коварен, как отточенный нож!","5":"Тебе зло милее добра, тебе ложь – милее, чем правда. [Музыка]","6":"Милы тебе речи, несущие гибель, мил коварный язык.","7":"Но Бог навеки тебя уничтожит, вырвет, выбросит тебя из шатра твоего и корень твой – из земли живых.","8":"Увидят праведники – страх охватит их, посмеются над тобою и скажут:","9":"«Вот, он не Бога считал своим прибежищем, он на богатство свое надеялся, богател за счет преступлений».","10":"А я в Храме Божьем – как маслина зеленеющая, на милость Божью я надеюсь, во веки веков,","11":"вечно славлю Тебя за то, что Ты сделал, уповаю на имя Твое: оно благо для тех, кто верен Тебе."},"52":{"1":"[Начальнику хора: на напев «Махалат». Песнь искусная, сложена Давидом.]","2":"Безумец думает: «Бога нет». Преступленья людские – гадки, гнусны… Никто не творит добра.","3":"Бог взирает с небес на людей, смотрит: есть ли мудрец, есть ли ищущий Бога?","4":"Все отступники, все никуда не годны, добра никто не творит – ни один!","5":"Неужели ничего не понимают они – люди, делающие зло? Мой народ пожирают они, будто хлеб, и Бога не призывают.","6":"Страх и ужас объяли их там, где нечего было страшиться. – Бог рассыпал кости врагов твоих, посрамились они, ибо Бог их отверг!","7":"– О если бы с Сиона спасенье пришло для Израиля! – Когда Бог возвратит Свой народ из плена, будет тогда веселье Иакову, радость Израилю!"},"53":{"1":"[Начальнику хора: под музыку струнных. Песнь искусная, сложена Давидом, когда зифеи пришли и донесли Саулу: «У нас скрывается Давид».]","3":"Боже! Спаси меня именем Твоим, разреши мою тяжбу силой Твоей.","4":"Боже! Молитву мою услышь, внемли словам уст моих,","5":"чужаки враждуют со мной, жестокие хотят убить меня; Бога нет у них пред глазами! [Музыка]","6":"Но Бог помогает мне, Господь поддержал мою жизнь.","7":"Он отплатит моим врагам! Яви верность Свою: истреби их!","8":"Я принесу Тебе жертву, Господи, воспою Твое имя благое!","9":"Ты избавил меня от всех бед, мне не страшно смотреть на врагов."},"54":{"1":"[Начальнику хора: под музыку струнных. Песнь искусная, сложена Давидом.]","2":"Услышь, Боже, молитву мою, не отвернись от моей мольбы;","3":"внемли мне и ответь; я в смятеньи, дрожу и плачу,","4":"слыша голос врага, испытав притесненье злодеев. Они возводят на меня напраслину и со злобой меня обвиняют.","5":"Сердце мое трепещет, ужас смертный меня сдавил;","6":"страх и трепет меня объяли, и отчаяние охватило.","7":"Я шепчу: «Будь у меня крылья голубя, я улетел и покой нашел бы;","8":"я бы скрылся вдали и поселился в пустыне;","9":"поскорей бы в убежище скрылся от ветра, вихря и бурь».","10":"Господь, смешай их языки и раздели! Я вижу в городе насилие и распри,","11":"днем и ночью они кружат по стенам его; а внутри – бесправие и горе.","12":"Посреди города – гибель; обман и ложь с его улиц не сходят!","13":"Не враг меня поносит – я стерпел бы; не враг меня теснит – я бы укрылся;","14":"но ты, человек мне близкий, мой товарищ и друг!","15":"Мы друг в друге души не чаяли, мы ходили вместе в дом Божий…","16":"Пусть же настигнет их смерть, пусть живыми сойдут в Шеол: ведь в их жилищах гнездится зло.","17":"Я воззвал к Богу, и Господь меня спасет.","18":"Вечером, утром, в полдень я в смятении и плаче – но услышит Он голос мой,","19":"сохранит целым и невредимым – от врагов, как бы много их ни было;","20":"услышит Бог, усмирит их Тот, Кто от века на троне, [Музыка] в Ком нет перемены. Но они не боятся Бога!","21":"Руку подняли на тех, кто с ними в мире, и нарушили договор;","22":"речь их скользка, как масло, а в сердце – вражда; слова нежнее елея, а по сути – мечи.","23":"Вручи Господу свои заботы – и Он поддержит тебя, вовек не даст пошатнуться праведнику!","24":"Ты, Боже, бросишь их в могильную яму; убийца, лжец – не проживут и полжизни. Я уповаю на Тебя!"},"55":{"1":"[Начальнику хора. Напев «Йонат – элем – рехокйм». Стихотворение Давида. Сложено, когда филистимляне захватили его в Гате.]","2":"Помилуй меня, Боже! Люди преследуют меня; весь день воюют и враждуют со мной.","3":"Весь день мои враги преследуют меня, как много тех, кто враждует со мной. О Всевышний!","4":"Когда мне страшно, я обращаюсь к Тебе. Я уповаю","5":"на Бога, я славлю слово Его; уповаю на Бога и не боюсь; что может сделать мне человек?","6":"День за днем они поносят мои слова и дела; мечтают, как бы мне навредить.","7":"Напасть готовы, наблюдают, следят за мной, хотят отнять мою жизнь.","8":"Неужели избегнут воздаяния за зло? Во гневе Своем, Боже, народы низложи.","9":"Ты – моя книга, сосуд для слез; мои слезы в сосуд собери, – пусть будут в книге Твоей!","10":"Я воззвал – и враги мои обращаются вспять, это значит, что Бог за меня.","11":"На Бога, чье слово я славлю, на Господа, чье слово я славлю,","12":"на Бога надеюсь я – и не боюсь; что может сделать мне человек?","13":"Я исполню, Боже, обеты свои; Тебе вознесу хвалу,","14":"Ты избавил меня от смерти, мои ноги – от того, чтоб оступиться, и я буду ходить перед Богом – во свете жизни!"},"56":{"1":"[Начальнику хора: напев «Ал – ташхет…». Стихотворение Давида. Сложено, когда он бежал от Саула в пещеру]","2":"Помилуй меня, Боже, помилуй меня, у Тебя ищет убежища душа моя, под сенью крыл Твоих укрываюсь я, пока не пройдет беда.","3":"Я взываю к Богу Всевышнему, к Богу, который добр ко мне.","4":"Он пошлет помощь с небес, чтоб меня спасти – посмеяться над теми, кто гонит меня – [Музыка] пошлет Бог милость и истину Свою!","5":"Душа моя среди львов; я среди хищников – людоедов, их зубы – копья и стрелы, их язык – острый меч.","6":"Будь превознесен, Боже, выше небес, и над всею землей да будет слава Твоя!","7":"Раскинули сети ногам моим, и поникла душа моя; на пути моем выкопали яму, да только сами в нее и упали!","8":"Твердо сердце мое, Боже, твердо сердце мое: буду петь, воспевать песнопенья.","9":"Пробудись же, душа моя, пробудитесь, арфа и лира, и я разбужу рассвет.","10":"Среди народов прославлю Тебя, Господь, средь всех племен Тебя воспою.","11":"Велика милость Твоя – до небес, верность Твоя – до облаков.","12":"Будь превознесен, Боже, выше небес, и над всею землей да будет слава Твоя!"},"57":{"1":"[Начальнику хора: напев «Ал – ташхет…». Стихотворение Давида.] [Бог: ]","2":"Справедливы ли ваши решенья, божества? Разве по правде вы судите людей?","3":"Злое вы замышляете в сердце, на земле – ваши руки помогают насилию! [Псалмопевец: ]","4":"Нечестивцы от самого рожденья отступники. Лжецы от чрева матери сбились с пути.","5":"Яд их – словно яд змеи, они как кобра, что уши свои заткнула,","6":"чтобы не слышать голос заклинателей, искусных мастеров заклинания.","7":"Боже! Выбей зубы во рту у них! Сломай челюсти этим львам, о Господь!","8":"Пусть исчезнут – как пролитая вода, пусть увянут – как вытоптанная трава.","9":"Пусть будут как слизняк, что ползет и тает, пусть, как выкидыш, не увидят солнца!","10":"Они даже не успеют понять, что с ними, а их – как будто колючки и терн, как будто репей и сухую траву – вихрь унесет прочь!","11":"С радостью праведник увидит их расплату, в кровь нечестивцев окунет стопы.","12":"Люди скажут: «Праведник вознагражден! Воистину есть Бог, Судия земли!»"},"58":{"1":"[Начальнику хора: напев «Ал – ташхет…». Стихотворение Давида. Сложено, когда Саул послал своих людей стеречь дом и убить Давида.]","2":"Спаси меня от врагов, мой Бог, от напавших меня защити,","3":"спаси меня от творящих зло, от убийц избавь!","4":"В засаде сидят, жизнь хотят отнять, наступают, лютые, на меня – но ни вины, ни греха за мной нет, о Господь!","5":"Сбегаются, готовы на невинного напасть. Воспрянь, подойди и взгляни!","6":"Господь, Ты – Бог воинств, Бог Израиля, воспрянь! Всем народам по заслугам воздай! Злых предателей не щади! [Музыка]","7":"…Настает вечер – и снова они тут как тут, рычат, как псы, и по городу кружат.","8":"Изрыгают слова – словно меч изо рта у них. Думают: «Кто нас услышит?»","9":"Но Ты посмеешься над ними, Господь! Все народы поднимешь на смех!","10":"Моя Сила! Взгляд мой к Тебе устремлен! Бог – твердыня моя!","11":"Бог верен мне, Он придет ко мне! Он мне даст взглянуть врагам в глаза!","12":"Только Ты их не убивай – а не то мой народ все забудет. Низложи их силой Твоей и скитаться заставь. Господи, Ты наш щит!","13":"Грех у них на губах, грех – слова их уст. Пусть попадутся в капкан гордыни своей за проклятья свои и за ложь!","14":"Уничтожь их в гневе Своем! Уничтожь, чтобы их не было больше! Пусть познают люди, что Бог – владыка над Иаковом – и до краев земли! [Музыка]","15":"…Настает вечер – и снова они тут как тут, рычат, как псы, и по городу кружат.","16":"Скитаются, чтобы пищу найти, не наедятся – останутся на ночь…","17":"А я воспеваю силу Твою, пою с рассвета о Твоей доброте, ибо Ты был прибежищем мне, был защитою в день беды.","18":"Моя сила! Я восхвалю Тебя, Бог – твердыня моя, Бог мой добр ко мне!"},"59":{"1":"[Начальнику хора: напев «Шушан эдут…». Стихотворение Давида, для заучивания. Сложено,","2":"когда он разгромил Арам – Нахараим и Арам – Цову, а Иоав, вернувшись, перебил в Соляной долине двенадцать тысяч эдомитян.]","3":"Ты отверг нас, Боже, и сокрушил; Ты в гневе! Но верни нам милость Свою!","4":"Ты землю сотряс, расколол ее, она дрогнула! Раны ее исцели!","5":"Ты нам показал, что такое горе, вином дурманящим Свой народ напоил.","6":"Тем, кто чтит Тебя, Ты дал знак отступать, чтобы они бежали от града стрел, [Музыка]","7":"чтобы уцелели те, кто дорог Тебе. Спаси их рукой Своей. Дай нам ответ!","8":"В Своем святилище Бог сказал: «Торжествуя, буду земли Шехема делить, делить земли в долине Суккот.","9":"Галаад – Мой, Манассия – Мой, Ефрем – шлем на главе Моей, Иудея – скипетр Мой.","10":"Моав – Мой умывальный таз, Эдому брошу сандалию Мою. Над Филистией Мой клич прозвучит!»","11":"Кто поможет войти в укрепленный город? Кто в поход на Эдом поведет?","12":"Ведь Ты, Боже, нас отверг! С нашим войском в бой не идешь!","13":"Помоги победить врага: нет надежды нам на людей.","14":"С Божьей помощью мы победим, Он одолеет наших врагов."},"60":{"1":"[Начальнику хора: под музыку струнных. Сложено Давидом.]","2":"Услышь, о Господь, мой крик, моей молитве внемли!","3":"Я на краю земли Тебя зову, и в отчаянии сердце мое. Возведи меня на утес: самому мне туда не попасть!","4":"Ты – прибежище мне, укрепление мощное против врага.","5":"Навек приют я найду в Твоем шатре, я укроюсь в тени Твоих крыл. [Музыка]","6":"Ты, Боже, слышал обеты мои, дал мне долю – с чтущими имя Твое.","7":"Долгие дни ниспошли царю, из поколенья в поколенье длится жизнь его!","8":"Пусть всегда перед Богом на престоле сидит; да хранят его вера и правда.","9":"Я вечно буду имя Твое воспевать, день за днем исполнять мои обеты."},"61":{"1":"[Начальнику хора: напев Иедутуна. Псалом Давида.]","2":"Лишь в Боге душа моя находит покой, от Него ко мне спасение придет.","3":"Он один – мой утес и Спаситель мой, Он – мой оплот, никогда я не дрогну.","4":"Долго ль вы будете делать зло? Вы замышляете человека убить! Вы – как наклонившаяся стена, как ограда, готовая рухнуть.","5":"Замышляете наземь повергнуть его, лгать – отрада для вас! Благословенье у них на устах, но проклятье на сердце! [Музыка]","6":"Лишь в Боге, душа моя, ищи покой, на Него – надежда моя.","7":"Он один – мой утес и Спаситель мой, Он – мой оплот, я не дрогну.","8":"В Боге – мое спасение и честь, Бог – прибежище мне, мой могучий утес.","9":"Всегда на Него надейся, народ! Все, что на сердце у вас, изливайте пред Ним. Бог – прибежище нам. [Музыка]","10":"Человек – что вздох, люди – лишь мираж: положи на весы – они легче, чем вздох.","11":"Не надейтесь на силу и на грабеж, не прельщайтесь пустым. Когда богатство приходит к вам, ему сердца не отдавайте!","12":"Бог сказал, и я это слышал не раз: что сила исходит от Бога!","13":"Господь, Ты добр. Ты дашь каждому, что он заслужил."},"62":{"1":"[Псалом Давида. Сложен, когда Давид был в Иудейской пустыне.]","2":"Боже! Ты Бог мой! К Тебе я стремлюсь, Тебя жаждет моя душа, и плоть томится жаждой по Тебе – как в пустыне безводной, сухой.","3":"Я в святилище видел Тебя – видел силу и славу Твою.","4":"Лучше жизни милость Твоя! Уста мои восхваляют Тебя.","5":"Благословлять Тебя буду всю жизнь, воздев руки, имя Твое призывать.","6":"Словно сытные яства вкусила душа, и уста ликуя славят Тебя!","7":"Я Тебя вспоминаю на ложе моем, ночами я твержу о Тебе.","8":"Ты моим заступником стал; и я пою под сенью Твоих крыл!","9":"К Тебе прильнула моя душа, и рука Твоя держит меня.","10":"А те, кто смерти моей хотят, пусть уйдут в земную глубь!","11":"Да станут они добычей меча, да будут пищей шакалам!","12":"Да веселится царь перед Богом! Кто Богом клянется, тот будет рад, и замолкнут уста лжецов!"},"63":{"1":"[Начальнику хора: псалом Давида.]","2":"Услышь, Боже, мой голос, молитву мою, я боюсь врагов! Мою жизнь спаси!","3":"От замысла злобных меня защити, от коварства злодеев.","4":"Они наточили язык, как меч. Ядовитая речь у них на тетиве,","5":"чтобы в невинного из засады стрелять. Внезапно выстрелят – им нечего бояться!","6":"На злодейство подбадривают друг друга, обсуждают, как поставить капкан, говорят: «Кто может заметить нас?","7":"Разглядеть нами скрытое зло?» Тот увидит, Кто видит людей насквозь, до самых глубин сердца!","8":"Господь в них пустит Свою стрелу, внезапно будут они сражены!","9":"Их язык их самих же повергнет наземь, кто увидит – головой покачает.","10":"Страхом будут объяты люди – и расскажут, что сделал Бог, уразумеют, что Он совершил.","11":"Ликует праведник, у Господа защиту найдя. И торжествуют все чистые сердцем!"},"64":{"1":"[Начальнику хора: псалом Давида, песнь.]","2":"Пред Тобой, Боже, звучит на Сионе хвала, пред Тобой да будут исполнены обеты,","3":"Ты слышишь мольбу. Всякий смертный к Тебе да придет!","4":"Одолели меня грехи, Ты очистишь нас от вины.","5":"Блажен тот, кого Ты избрал, к Себе приблизил, дал во дворах Храма Твоего обитать. Дай нам счастьем насытиться в доме Твоем, в Храме Твоем святом.","6":"Ты грозен и справедлив, ответь, о Бог, спасающий нас, Ты, Надежда всех пределов земли и дальних заморских стран!","7":"Силой Своей Ты горы воздвиг, Тебя опоясала мощь.","8":"Шум морей Ты укротил – рокот волн и ропот племен.","9":"От Твоих знамений трепещут на краю земли, Ты заставляешь прославлять Тебя и запад, и восток.","10":"Ты заботишься о земле, утоляешь жажду ее, изобилие ей даешь: полноводен Божий поток. Ты растишь урожай, подготовляешь землю:","11":"борозды орошаешь, ровняешь бугры, размягчаешь дождем, благословляешь ростки.","12":"Ты венчаешь венцом год щедрот Твоих, где Ты проедешь – там масло источает земля,","13":"степные пастбища соком сочатся. Холмы опоясаны радостью,","14":"и стадами оделись луга, долины покрылись хлебами, и ликуют они и поют."},"65":{"1":"[Начальнику хора: песнь, псалом.] Славьте Бога, все жители земли,","2":"славьте имя Его, славьте Его хвалой!","3":"Скажите Богу: «Как грозны Твои дела! Ты могуч, враги заискивают пред Тобой.","4":"Да склонятся пред Тобою все жители земли, да воспоют Тебя, да воспоют Твое имя!» [Музыка]","5":"Поглядите на то, что Бог совершил: грозны деянья Его для людей.","6":"Море в сушу Он превратил, реку переходили пешком. Будем пред Ним ликовать!","7":"Он могуч и правит вовек, все народы пред взором Его: пусть мятежники не восстают! [Музыка]","8":"Благословите нашего Бога, все народы, громогласно хвалите Его!","9":"Он поддерживает в нас жизнь, оступиться нам не дает.","10":"Боже, Ты нас испытанью подверг, переплавил в горниле нас, как серебро.","11":"Ты нам дал попасться в силки, наши спины на муку обрек,","12":"Ты дал людям нас оседлать. Мы огонь и воду прошли, и Ты вывел нас на простор.","13":"Приду в Храм Твой со всесожжениями, пред Тобою исполню обеты –","14":"я изрек их своими устами, я их дал, когда был в беде.","15":"Всесожжения Тебе принесу, жирных баранов в жертву сожгу, принесу в жертву быков и козлов. [Музыка]","16":"Послушайте, все, кто боится Бога, я расскажу вам, что Он сделал для меня.","17":"К Нему воззвали мои уста, и возвеличил Его мой язык.","18":"Если б зло было в сердце моем, то Господь бы не слышал меня.","19":"Но услышал меня Бог, Он внял молитве моей.","20":"Благословен Бог: Он молитву мою не отверг, и со мною милость Его!"},"66":{"1":"[Начальнику хора: псалом под музыку струнных, песнь.]","2":"Бог да помилует нас, да благословит, да обратит на нас светлый Свой взор! [Музыка]","3":"Тогда путь Твой ведом будет на земле, и все страны увидят спасение Твое.","4":"Да восхвалят народы, Тебя, Боже! Все народы да восхвалят Тебя!","5":"Пусть радуются и ликуют племена: Ты будешь народы по правде судить, укажешь путь племенам земли.","6":"Да восхвалят народы, Тебя, Боже! Все народы да восхвалят Тебя!","7":"Земля дает урожай. Да благословит нас Бог, Бог наш!","8":"Да благословит нас Бог! И пусть трепещут перед Ним во всех концах земли!"},"67":{"1":"[Начальнику хора. Псалом Давида. Песнь.]","2":"Да поднимется Бог – и да рассеются враги Его, и да разбегутся ненавидящие Его.","3":"Заставь их исчезнуть, как дым исчезает. Словно тает воск от огня, да сгинут нечестивцы пред Богом!","4":"А праведники да ликуют! Да веселятся они пред Богом, да радуются, ликуя.","5":"Пойте о нашем Боге, воспевайте имя Его, путь готовьте Едущему по небесам. Господь – имя Его, и радуйтесь перед Ним!","6":"Он – отец сирот и заступник вдов. Бог – в жилище Своем святом.","7":"Бог одиноким дает дом и семью, избавляет узников от оков. А мятежники пусть остаются в пустыне!","8":"Боже! Когда Ты шел пред народом Твоим, когда Ты шествовал через пустыню, [Музыка]","9":"содрогалась земля, с небес ливень лил – перед Богом Синайским, перед Богом, Богом Израиля.","10":"Боже, ты дождем Свои щедроты изливал; Твоя страна изнемогала – Ты ее подкреплял.","11":"Твои стада пасутся на этой земле; и Ты, Боже, готовишь блага бедняку.","12":"Господь посылает слово; провозвестниц – целое воинство!","13":"Цари воинств бегут, бегут! А ты, оставшаяся дома, добычу дели!","14":"Если ляжете вы меж кострищ… Крылья голубя в серебре, перья его в золоте!","15":"Когда Всесильный прогнал царей этой земли – снег белел на Цалмоне!","16":"О гора Божья, гора Башан, гора высокая, гора Башан!","17":"Что вы так смотрите, высокие горы, на гору, где Бог захотел обитать, где Господь обитает вечно?","18":"Колесниц Божьих тысячи и тысячи тысяч, Господь среди них; Бог Синая – во святилище.","19":"Ты восшел на высоту, увел пленников в плен, принял дань от людей, от тех, что были непокорны, и сотворил там обитель – о Господь Бог!","20":"День за днем – да будет благословен Господь! Он наше бремя несет, Бог – спасение наше. [Музыка]","21":"Бог для нас – Бог спасения; во власти Господа Бога путь, уводящий от смерти.","22":"Сокрушит Бог голову врагов Своих, волосатое темя преступника.","23":"Господь обещал: «Я верну их с горы Башан, Я их верну из пучины морской!»","24":"Так что ты окунешь ногу в кровь, и твои псы язык окунут в кровь врагов.","25":"Видно шествие Твое, о Боже, как идет мой Бог, мой Царь во святилище:","26":"впереди певцы, позади музыканты, посредине девушки с бубнами.","27":"«В собраниях благословите Бога, Господа, Он – источник Израилев!»","28":"Там Вениамин – младший – во главе их; вожди Иуды, с его многолюдством, вожди Завулона, вожди Неффалима.","29":"Боже, силе Твоей дай приказ – той силе, Боже, что Ты слал нам на помощь!","30":"В Храм Твой, в Иерусалим, цари Тебе принесут дань.","31":"Пригрози зверю, что в тростнике, стаду могучих быков – народов, пусть падут в ноги, принесут серебро! Разгони племена, хотящие войн!","32":"Послы придут из Египта; кушиты руки к Богу возденут.","33":"Царства земные! Воспойте Бога, воспевайте Господа! [Музыка]","34":"Он едет по древним небесам небес и подает Свой голос, могучий голос!","35":"Воздайте славу Богу! Словно покров над Израилем – сила Его, и мощь Его – на облаках.","36":"Страшен Ты, Боже, во святилище Своем, о Бог Израиля! Он дает силу и мощь народу! Благословен Бог!"},"68":{"1":"[Начальнику хора: напев «Шошанним…».]","2":"Боже, спаси меня: подступила к горлу вода.","3":"Я в трясине увяз, не на чем стать, Я в глубине, под водой, и уносит меня поток.","4":"От крика я изнемог, пересохшее горло горит. Слепнут мои глаза, глядя вдаль: где же помощь Божья?","5":"Ненавидящих меня без вины у меня больше, чем волос на голове. Они сильны и меня гонят – ни за что. Я должен вернуть, чего не крал.","6":"Боже! Ты знаешь безумье мое, от Тебя не скрыты паденья мои.","7":"Не посрами меня, Господи, Господь Воинств, не посрами со мною всех, кто уповает на Тебя! Не опозорь меня, Бог Израиля, не опозорь со мною всех, кто прибегает к Тебе!","8":"Ради Тебя я бесчестье терпел, и позор мне лицо покрывал,","9":"братья меня признавать не хотят, для детей матери моей я чужой.","10":"Обида за Храм Твой снедает меня; смеются над Тобой – а я сгораю со стыда.","11":"Я плакал и постился – и стал мишенью насмешек.","12":"В рубище я одет – насмехаются надо мной.","13":"Судачат про меня у городских ворот, обсуждают меня, обо мне поется в песнях пьяных гуляк.","14":"Господь, я Тебе молюсь в час, когда Ты благосклонен ко мне. Бог многомилостивый, ответь – будь мне надежным спасеньем!","15":"Извлеки из трясины, не дай утонуть, от врагов избавь, из пучины спаси.","16":"Не дай потоку меня унести, пусть бездна не поглотит меня, и не сомкнет челюстей своих яма!","17":"Господь, ответь мне, Ты верен и добр, Милосердный, взгляни на меня!","18":"Не отвернись от меня, раба Твоего. Мне тяжело. Скорее ответь!","19":"Подойди, спаси мою жизнь, наперекор всем врагам – спаси.","20":"Знаешь Ты, как поносят меня, как бесчестят меня и срамят; Ты моих противников знаешь.","21":"Поношенья сломили мое сердце, горько мне, я сочувствия жду – его нет, жду утешителя – нет никого.","22":"Вместо еды мне отраву дают, я хочу пить – меня уксусом поят.","23":"Пусть их трапеза станет для них западней, возмездием и ловушкой.","24":"Пусть навеки померкнут у них глаза, пусть тела их трясутся всегда!","25":"Излей на них Свой гнев, пусть настигнет их ярость Твоя!","26":"Пусть жилище их будет пусто, и пустыми стоят их шатры,","27":"раз они гнали тех, кого Ты ранил, потешались над пронзенными Тобою.","28":"Припомни грехи их, грех за грехом, и не дай им оправдаться.","29":"Пусть будут стерты из книги живых, пусть не числятся там вместе с праведными.","30":"Я нищ, я страдаю, спаси, Боже, и сохрани!","31":"Я прославлю Божье имя песней, славословием его возвеличу,","32":"это Господу приятней, чем жертвы, чем быки рогатые, с копытами.","33":"Увидят нищие – и возликуют. И оживут сердца ищущих Бога!","34":"Обездоленных слышит Господь, своих людей Он не бросит в тюрьме.","35":"Пусть прославят Его небо и земля, и моря и все, что живет в них!","36":"Бог придет на помощь Сиону и отстроит города Иудеи, люди снова будут там жить и владеть своей собственной землей,","37":"потомки слуг Его получат наделы, там будут жить те, кто любит Его имя."},"69":{"1":"[Начальнику хора: сложено Давидом. Восклицание.]","2":"Боже, спаси меня на помощь, Господи, поспеши!","3":"Да покроют срам и позор тех, кто смерти моей хотел; пусть с позором уйдут назад те, кто желал мне зла.","4":"Пусть, пристыженные, отвернутся, кто надо мной насмехался: «Вот, вот он!»","5":"А у тех, кто стремится к Тебе, пусть настанут веселье и радость. Пусть всегда говорят: «Как велик Бог!» те, кто любят Тебя, о Заступник!","6":"Я беден и нищ. О Бог мой, ко мне поспеши! Ты помощник мой и спаситель, так не медли же, о Господь!"},"70":{"1":"Господь, Ты – защита моя, я не посрамлюсь вовек.","2":"Яви справедливость, избавь и спаси, услышь меня, помоги!","3":"Будь для меня скалой, будь всегда убежищем мне, помощь Свою мне пошли: Ты – утес мой, твердыня моя.","4":"Боже мой, от злодея меня избавь, от обидчика и гонителя:","5":"Ты, Владыка, – надежда моя; уповал я на Господа с юности.","6":"Ты – опора моя от чрева матери, из утробы ее Ты извлек меня. Я славлю Тебя всегда.","7":"Для народа я стал притчей и знамением, Ты мне – крепкий оплот.","8":"Хвала Тебе – на устах моих, что ни день они славят величье Твое.","9":"Не покинь меня на старости лет, когда иссякнет моя сила, не оставь меня.","10":"Толкуют враги обо мне, ждут моей смерти и держат совет,","11":"говорят: «Бог оставил его. В погоню! Схватить! Никто его не спасет!»","12":"Боже, не стой в стороне! Бог мой, на подмогу спеши!","13":"Пусть посрамятся и сгинут те, кто ненавидит меня; да покроет срам и позор тех, кто желает мне зла!","14":"А я всегда буду надеяться на Тебя, Тебя славить снова и снова.","15":"Каждый день прославлять справедливость Твою, возвещать, что Ты делал, спасая меня: но перечислить всего не смогу!","16":"О мощи Господа Бога я речь поведу, о том, что Ты, Ты один – справедлив!","17":"С младых лет, Боже, Ты наставляешь меня, я доныне прославляю Твои чудеса.","18":"И до старости, до седых волос, Боже, не оставляй меня, чтоб я людям возвестил мощь Твоей руки, поколенью грядущему – силу Твою.","19":"Боже, справедливость Твоя – до небес. Деянья Твои велики. Боже, кто подобен Тебе?","20":"Сколько лютых бед Ты нам послал – но верни меня к жизни вновь; подними из подземных бездн.","21":"Вновь возвысь меня и утешь.","22":"А я звуками лиры прославлю Тебя, воспою Твою верность, о Бог мой! Я буду на арфе Тебе играть, о Израиля Бог Святой!","23":"Уста ликуют, когда поют Тебе песнь, моя жизнь спасена Тобой!","24":"Что ни день мой язык славит справедливость Твою, и позор покрыл тех, кто желал мне зла!"},"71":{"1":"[О Соломоне.] Даруй, Боже, царю справедливость Твою, правосудье Твое – царскому сыну.","2":"Пусть по правде судит он Твой народ и решит справедливо тяжбы бедняков Твоих.","3":"Пусть с гор благополучие к народу придет, пусть холмы по справедливости плоды принесут.","4":"Пусть он тяжбы обездоленных решит, спасет детей бедняка, угнетателя истребит.","5":"Пусть он живет долго, как солнце, из рода в род – пока светит луна.","6":"Пусть дождем он прольется на луг, ливнем землю оросит.","7":"Пусть праведник процветает при нем, пусть изобилует счастье, пока светит луна.","8":"Пусть он правит от моря до моря, от Реки до краев земли.","9":"Пусть звери пустыни падут ниц перед ним, и враги его пусть лижут пыль.","10":"Цари Таршиша и островов пусть везут ему дань, цари Сабы и Савы пусть дары несут.","11":"Пусть склонятся пред ним все цари, все народы пусть служат ему.","12":"Он спасет тех, кто беден и заступника зовет, тех, кто нищ, кому никто не поможет.","13":"Над бедным и нищим сжалится он, обездоленным он поможет,","14":"от насилия и гнета избавит их, тяжко видеть ему их смерть.","15":"Пусть живет и здравствует он! Пусть несут ему золото Сабы! Пусть всегда молятся за него, благословляют его каждый день!","16":"И настанет в стране изобилие зерна, на горах плоды будут, как на Ливане, людей в городе – что травы .","17":"Да пребудет его имя вовек, пусть его род не прервется под солнцем. Для всех народов он станет благословеньем – и счастливым его назовут.","18":"Благословен Господь Бог, Бог Израиля: только Он творит чудеса;","19":"благословенно и славно Его имя вовек, и пусть наполнится Его славой земля! Аминь, аминь!","20":"[Конец молитв Давида, сына Иессея.]"},"72":{"1":"[Псалом Асафа.] Как добр к Израилю Бог – добр к тем, чьи сердца чисты!","2":"А я чуть было не оступился, я едва не сбился с пути:","3":"позавидовал наглецам, видя, как процветают злодеи,","4":"как до смерти они не страдают и как не покидает их сила.","5":"Человеческое горе минует их, и все муки людей – не для них.","6":"Их гордыня на них – ожерельем, и насилие – их наряд.","7":"Жиром заплыли глаза. Их замыслам нет границ.","8":"Глумлива и злобна их речь, спесива, полна угроз.","9":"Задирают пасть свою к небу, язык шарит по всей земле.","10":"И за ними идет Мой народ, полной чашей их воду пьет!","11":"Говорят они: «Как Бог узнает? Разве Вышний может узнать?»","12":"Благоденствуют вечно злодеи, умножают богатство свое.","13":"«Значит, зря я был сердцем чист? И в знак невинности руки омывал?","14":"Каждый день для меня был мукой? Было каждое утро – горем?»","15":"Если бы стал я так рассуждать, то я предал бы племя сынов Твоих!","16":"Я хотел понять, почему все так, трудно было мне с этим смириться,","17":"пока я в Божий Храм не пришел: и там узнал я, что ждет их в конце.","18":"Скользким сделаешь Ты их путь, уничтожишь их, истребишь.","19":"Внезапна будет погибель их! Они сгинут, конец их ужасен.","20":"Как исчезает сон, когда проснешься, Ты, Господь, встав, их сочтешь за призрак!","21":"А когда в сердце моем была обида и пронзала болью нутро,","22":"то я был просто глуп, был невеждой, словно скот я был пред Тобой!","23":"Я с Тобою всегда, и Ты за руку держишь меня.","24":"Ты мудро меня направляешь, Ты со славою примешь меня.","25":"Кто еще мне нужен на небе? С Тобой никто на земле мне не нужен.","26":"Тают тело мое и разум, моя скала, мой удел – Бог, навеки!","27":"Кто от Тебя удалился, погибнет. Ты губишь всех, кто Тебе изменил.","28":"Я рядом с Богом, и мне хорошо. Господь Бог – прибежище мне, я возвещаю все деянья Твои."},"73":{"1":"[Искусная песнь. Сложена Асафом.] Боже, отчего Ты нас навеки отверг, пышешь гневом на стадо Своих овец?","2":"Вспомни общину, которую от века избрал, племя, что Ты выкупил и сделал достоянием Своим, вспомни гору Сион, где поселился Ты.","3":"Приди к месту, что стало руиной навек: здесь злодействовал враг средь святынь.","4":"Там, где являлся Ты, рычат ныне Твои враги, здесь свои знамена водрузили они.","5":"Словно заносят топор над сплетеньем деревьев в лесу,","6":"так по резным украшеньям топор и секира бьют.","7":"Твое Святилище предали огню, попрали место, где Твое имя живет.","8":"Решили: «Уничтожим их до конца!», по всей стране сожгли места, где являлся Бог.","9":"Наших знамений не видно, пророков больше нет, и никто из нас не знает, надолго ли.","10":"Боже! Доколе неприятелю глумиться? И всегда ль будет враг Твое имя хулить?","11":"Почему Ты убрал Свою руку? Скрыл руку Свою под плащом?","12":"Бог – от века мой Царь, чудеса Он творил на земле.","13":"Ты Своею мощью море рассек, головы змеев в воде разбил,","14":"Ты размозжил головы Левиафана, отдал его в пищу диким зверям.","15":"Ты пробил путь источникам и ручьям, полноводные реки Ты осушил,","16":"в Твоей власти день, в Твоей власти ночь, Ты луну и солнце сотворил,","17":"Ты очертил пределы земли, лето и зиму создал Ты.","18":"Вспомни, как над Господом глумится враг, как народ глупцов Твое имя поносит.","19":"Свою голубку не отдай на расправу зверям, Своих нищих не забывай насовсем.","20":"Что стало с договором, взгляни! Полны насилия мрачные закоулки земли.","21":"Пусть бедняк не уйдет посрамленным, да прославят Твое имя те, кто нищ и убог.","22":"Боже, поднимись, верши суд, вспомни: что ни день, Тебя поносят глупцы.","23":"Не забывай, как здесь неприятель кричит и постоянно бушуют Твои враги."},"74":{"1":"[Начальнику хора: напев «Ал – ташхет…». Псалом Асафа. Песнь.]","2":"Мы славим Тебя, Боже, славим, с наших уст Твое имя не сходит, возвещаем Твои чудеса! [Бог: ]","3":"– Я назначу время и срок и вершить буду правый суд!","4":"Колеблется земля и ее жители – но Я укрепил ее опоры! [Музыка]","5":"Говорю дерзким: «Оставьте дерзость!», злым: «Свои гордые рога не вздымайте!","6":"Не вздымайте их до небес! Не говорите, надменно голову задрав!» [Псалмопевец: ]","7":"– Не с востока, не с запада, не из пустыни грядет Суд, и не с гор.","8":"Бог – Судья! Одного Он низвергнет – другого Он вознесет!","9":"Чаша в руке у Господа, и вино в ней крепкое, пряное. Он нальет его всем нечестивцам земли: они до дна, до осадка выпьют чашу!","10":"Я же буду вовек петь хвалу, возносить хвалу Богу Иакова! [Бог: ]","11":"– Сокрушу Я злодеев крутые рога, и гордо вознесется рог праведника!"},"75":{"1":"[Начальнику хора: под музыку струнных. Псалом Асафа. Песнь.]","2":"В Иудее прославлен Бог, велико Его имя в Израиле.","3":"В Салиме Он обитает, Его жилище – Сион.","4":"Там сокрушил Он молнии стрел, оружие, щиты и мечи. [Музыка]","5":"Как, Могучий, Ты воссиял с вековечных гор!","6":"Беззащитной добычей стали храбрые воины: спят они, не проснутся, бессильны руки бойцов.","7":"Ты прикрикнул на них, Бог Иакова, вечным сном спят колесницы и кони.","8":"Ты грозен; кто устоит пред Тобой, когда Ты приходишь в ярость?","9":"Ты с небес возвестил приговор – и в страхе земля стихла,","10":"когда Бог поднялся, чтоб суд вершить, спасти всех бедняков земли. [Музыка]","11":"В гневе Ты попираешь людей, на уцелевших – вооружился Ты яростью!","12":"Господу, вашему Богу, дайте обеты – и выполняйте их. Все, кто живут вокруг, пусть несут дань Грозному Богу.","13":"Дух правителей Он смиряет, страшен он всем царям земли."},"76":{"1":"[Начальнику хора: напев Иедутуна. Псалом Асафа.]","2":"К Богу взываю я, зову Бога – и Он слышит меня.","3":"В день беды Господа я искал, воздевал неустанно руки всю ночь, утешения душа не нашла.","4":"Вспоминая о Боге, я буду стенать, в изнеможении духа скажу: [Музыка]","5":"«Ты не даешь мне очей сомкнуть, я от горя утратил дар речи».","6":"Размышляю о том, что было встарь. О былом","7":"вспоминаю я. Я пою в ночи. Говорю с сердцем моим, и ответа ищет душа.","8":"Неужели Господь отвернулся навек? И впредь милостивым не будет?","9":"Навсегда ли иссякла Его доброта? Навсегда Его слово умолкло?","10":"Неужели Бог про жалость забыл? И, разгневавшись, отверг сострадание? [Музыка]","11":"Я сказал: «Вот в чем горе мое: рука Вышнего не такова, как встарь».","12":"Вспомню я деяния Господа, вспомню чудеса, что творил Ты встарь;","13":"поведу речь о том, что Ты совершил, и делам Твоим удивлюсь.","14":"Боже, святы Твои пути. Кто средь богов так велик, как Бог?","15":"Ты – Бог, который творит чудеса. Ты народам явил Свою мощь.","16":"Ты сильной рукою спас Свой народ – сынов Иакова и Иосифа. [Музыка]","17":"Боже! Воды, увидев Тебя, воды, увидев Тебя, дрожат, и трепещут пучины.","18":"Хлынул ливень из облаков, гром раздается из туч, Твои стрелы повсюду летят.","19":"Твоя колесница громом гремит, озаряют молнии мир, трепещет, дрожит земля.","20":"Ты шествуешь через море, Ты идешь средь глубоких вод, никому не ведом Твой путь.","21":"Ты вел Свой народ, как отару овец, поручив его Моисею и Аарону."},"77":{"1":"[Искусная песнь. Сложена Асафом.] Мой народ! Внимай моему наставлению! Прислушайтесь к словам уст моих,","2":"я открою уста – и притчу скажу, возвещу древние тайны,","3":"что мы слышали, что узнали мы, что отцы передали нам,","4":"мы не станем от их потомков таить: возвестим поколению грядущему о том, как славен Господь и могуч, о том, как Он творил чудеса,","5":"как с Иаковом Он заключил договор, Закон дал Израилю. Он нашим отцам повелел передать это дальше, потомкам,","6":"чтобы поколение грядущее знало, и, родив детей, рассказало им;","7":"чтоб на Бога они возложили надежду, не забывали о Божьих деяниях, соблюдали Его повеления.","8":"Чтобы не были такими, как отцы их – поколение упрямое, мятежное, которое не было с Богом всем сердцем, не хранило Ему верность в душе.","9":"Сыны Ефремовы, воины – лучники, обращены были в бегство в день битвы","10":"за то, что договор с Богом нарушили, Его Закону не следовали,","11":"позабыли Его деяния, чудеса, что Он им явил.","12":"На глазах у их предков Он творил чудеса, в Египте, на равнинах Танисских:","13":"раздвинул море, провел их по дну, заставил воды стоять стеной.","14":"Днем перед ними, как облако шел, а ночью – как свет огня;","15":"расщепил в пустыне утесы, чтобы дать им воду – как из великой пучины;","16":"потоки заставил литься из скал, они текли словно реки.","17":"Но отцы вновь согрешили пред Ним, против Вышнего бунтовали в пустыне.","18":"Искушать задумали Бога, стали требовать себе пищи.","19":"Говорили, оскорбляя Бога: «Может Бог накрыть нам стол в пустыне?","20":"Он ударил в утес и вода полилась, все наводнили ручьи. Может, Он даст и хлеб? Накормит народ Свой мясом?»","21":"Услышал Господь, пришел в ярость, и запылал Его гнев на Иакова, закипел – против Израиля.","22":"Ведь они не положились на Бога, и не верили, что Он спасет их!","23":"Он дал облакам приказ, небесные двери раскрыл,","24":"пролил манну на них, как дождь, дал им в пищу небесный хлеб.","25":"Люди ели пищу Могучих, вдоволь Он их накормил.","26":"В небе поднял восточный ветер, привел южный Своею мощью –","27":"и засыпал их мясом, как пылью, птицами, как песком морским;","28":"заставил птиц упасть среди стана, вокруг шатров.","29":"Они ели и объедались – Он исполнил желание их.","30":"Но еще не прошел их голод, еще мясо было во рту,","31":"Божий гнев их постиг, убил сильнейших, поверг юношей Израиля наземь.","32":"А они все продолжали грешить, все не верили Его чудесам,","33":"и Он сделал их жизнь мимолетной, они жили, трепеща и дрожа.","34":"Когда Он убивал их – они к Нему возвращались, вновь принимались искать Бога,","35":"вспоминали, что Он – их Скала, что Бог Вышний – их избавитель,","36":"и заискивали перед Ним, их уста льстиво лгали Ему,","37":"но сердца их не были с Ним, они не были верны договору.","38":"Он, милосердный, прощал им вину, не хотел Он их истребить, много раз удерживал Свой гнев, Своей ярости не дал разгореться.","39":"Он помнил, что они – лишь плоть, дуновение, что уйдет и не вернется.","40":"Сколько раз бунтовали они в пустыне, досаждали Ему в стране безлюдной!","41":"Вновь и вновь искушали Бога, оскорбляли Святого Израилева.","42":"Не вспоминали про мощь Его руки, про то, как Он их спас от врага;","43":"как в Египте Он творил чудеса, творил знамения на равнинах Танисских;","44":"как все реки Египта Он в кровь обратил, и нельзя было воду пить;","45":"наслал оводов, чтобы жалили египтян, наслал жаб, чтобы их погубить;","46":"урожай их отдал саранче, насекомым – плоды долгих трудов;","47":"градом побил их лозы, сикоморы побил льдинами;","48":"граду обрек их скот, молниям – их стада;","49":"Он обрушил на них Свой гнев, ярость, проклятье, беду – наслал ангелов – губителей на них.","50":"Проложил путь для гнева Своего, не пощадил их жизнь, сделал их добычей чумы.","51":"Перебил всех первенцев в Египте, первый плод мужской силы – в шатрах Хамовых.","52":"И повел Свой народ, как овец, по пустыне их вел, словно стадо.","53":"Вел их так, что им нечего было бояться, а врагов поглотило море.","54":"Так привел Он их в землю святую Свою, к горе, которую взял Себе, Своею рукой.","55":"Он ради них народы изгнал, землю роздал израильским племенам, дал им вселиться в чужое жилище.","56":"А они искушали Его, бунтовали против Вышнего Бога, договор с Ним не соблюдали.","57":"Как отцы их, изменяли, предавали, подводили, словно лук ненадежный.","58":"Вызывали Его гнев своими капищами, Его ярость – своими идолами.","59":"Услышал Бог и разгневался, отверг полностью Израиль.","60":"Он покинул святилище в Силоме, Шатер, где среди людей обитал.","61":"Свою мощь позволил взять в плен, врагу дал захватить Свою славу,","62":"Свой народ Он обрек мечу, в гневе был на достояние Свое.","63":"В огне погибли их юноши, брачных песен девушкам не спели,","64":"священники пали от меча, на похоронах не плакали вдовы.","65":"Но воспрял Господь, как ото сна, как богатырь, опьяненный вином;","66":"Своих врагов разгромил, прогнал, покрыл их вечным позором.","67":"Он отверг жилища Иосифа, не избрал Себе племя Ефремово,","68":"а избрал племя Иуды, полюбил гору Сион.","69":"Как небеса, Он воздвиг свой чертог, как землю, сделал незыблемым вовек.","70":"Он избрал Давида, раба Своего, из овчарен забрал,","71":"от овечьих стад, чтобы Давид пас Его народ – Иакова, чтобы пас Израиль, Его достояние.","72":"И Давид их пас – с сердцем праведным, и заботился о них руками мудрыми."},"78":{"1":"[Псалом Асафа.] Язычники вторглись в надел Твой, Боже, они осквернили святой Твой Храм, Иерусалим превратили в руины!","2":"Трупы рабов Твоих бросили на растерзание птицам, тела праведников Твоих – на съедение зверям.","3":"Их кровь рекою лилась вокруг Иерусалима, и некому их хоронить.","4":"Посмешищем стали мы для соседей, глумятся, издеваются над нами все вокруг.","5":"Доколе, Господи, будешь Ты гневаться? Вечно? Доколе будет ярость Твоя пылать, как огонь?","6":"Обрати Свой гнев на народы, что не знают Тебя, на царства, не призывающие имя Твое,","7":"которые пожирают Иакова и опустошают владенья его.","8":"Грех наших предков нам не вменяй в вину, поспеши нам явить милосердие Свое, мы уже измождены!","9":"Помоги нам, Боже, спасающий нас, вступись за славу имени Твоего. Спаси нас, прости нам наши грехи ради имени Твоего!","10":"Хватит язычникам смеяться: «Где же Бог их?» Да узнают они на наших глазах, как Ты за кровь рабов Своих мстишь!","11":"Стоны узников пусть достигнут Тебя, Ты могуч: сохрани обреченных на смерть!","12":"Семикратно нашим соседям воздай за то, Господь, как они поносили Тебя!","13":"А мы, народ Твой, и овцы стада Твоего, вечно будем Тебя прославлять, из поколенья в поколенье – петь Тебе хвалу."},"79":{"1":"[Начальнику хора: напев «Шошанним эдут…» Псалом Асафа.]","2":"Услышь, о Бог, пасущий израильский народ, людей Иосифа – как отару овец! Восседающий на херувимах, явись!","3":"Пред Ефремом, Вениамином и Манассией яви силу Свою! Приди на помощь нам!","4":"Боже! Восстанови нас! Да будет светел Твой взор – и мы спасены!","5":"Господи, Боже сил! Доколе будешь пылать гневом на мольбы народа Твоего?","6":"Ты, словно хлебом, накормил нас слезами, напоил слезами – полной чашей,","7":"для соседей сделал нас посмешищем, враги наши издеваются над нами.","8":"Боже сил! восстанови нас! Да будет светел Твой взор – и мы спасены!","9":"Из Египта принес Ты виноградную лозу, прогнал народы прочь и посадил ее;","10":"Ты расчистил для нее место, она пустила корни, заполнила землю.","11":"Горы были осенены ее тенью, кедры Божьи – ее ветвями;","12":"до моря протянулись побеги ее, до Великой Реки – ее отростки.","13":"Для чего же разрушил Ты ограду ее? Все, кто мимо идут, – обрывают ее!","14":"Лесной вепрь ее объедает, и грызет ее зверь полевой.","15":"О Бог Воинств! Обернись, посмотри с небес и взгляни на эту лозу,","16":"на виноградник, который насадил Ты Своею рукой, на человека, которого Ты укрепил силой Своей.","17":"Она сожжена огнем, порублена… Да сгинут враги от гнева Твоего!","18":"Поддержи Своей рукой того, кто одесную Тебя – человека, которого Ты укрепил силой Своей!","19":"Мы не отступим от Тебя! Оживи нас, и мы имя Твое призовем.","20":"Господи, Боже сил! Восстанови нас! Да будет светел Твой взор, и мы спасены!"},"80":{"1":"[Начальнику хора: напев «ха – Гиттит». Сложено Асафом.]","2":"Воспойте Бога, Он – наша сила, восклицайте пред Богом Иакова!","3":"Пойте песни и бейте в бубны, на звучной арфе и лире играйте!","4":"В новолуние трубите в рог, в полнолуние – в день праздника нашего.","5":"Это закон для Израиля, повеление Бога Иакова.","6":"Эту заповедь дал Он Иосифу, когда выступил против Египта. Я слышал голос, мне прежде неведомый.","7":"Он говорил: «Я бремя снял с твоих плеч, твои руки от корзин освободил.","8":"В беде ты звал – и Я вызволил тебя; из грозовой тучи ответил тебе, Я испытал тебя у вод Меривы . [Музыка]","9":"Народ Мой, услышь Мой призыв! Израиль, послушай Меня!","10":"Пусть не будет у тебя чужих богов, не поклоняйся чужеземному богу!","11":"Я – Господь, Я твой Бог, который вывел тебя из Египта. Раскрой уста, и Я насыщу тебя.","12":"Но мой народ не послушал Меня, Израиль был Мне непокорен.","13":"Я оставил их во власти их упрямства: пусть сами выбирают свой путь.","14":"Если бы Мой народ Меня слушал, если бы Израиль шел путем Моим!","15":"Я бы тотчас смирил всех врагов их, Свою руку простер на притеснителей!","16":"Враги Господа пред Ним стали бы заискивать, вечным было бы их наказание.","17":"А вас кормил бы Он отборной пшеницей и мед заставил для вас течь из скалы!»"},"81":{"1":"[Псалом Асафа.] Встал на Божьем совете Господь и богам произнес приговор:","2":"«Доколе будете суд неправый творить? Становиться на сторону злодеев? [Музыка]","3":"Защищайте бедного и сироту, за смиренного и нищего вступайтесь.","4":"Выручайте гонимого и бедняка, от рук злодея спасите его!»","5":"Не поняли – не уразумели они! Во тьме ходят! Пошатнулись основанья земли!","6":"Хотя Я и сказал вам: «Вы – боги, и все вы – сыны Вышнего,","7":"но вы умрете смертью людей, как земной владыка падете».","8":"Боже, воспрянь! Будь судьей земли! Все народы – владенье Твое!"},"82":{"1":"[Песнь. Псалом Асафа.]","2":"Боже, не будь безучастен! Не молчи, не безмолвствуй, Боже!","3":"Встрепенулись Твои враги, ненавистники голову подняли.","4":"Сговорились против народа Твоего, злоумышляют против тех, кто дорог Тебе,","5":"говорят: «Уничтожим этот народ, пусть забудется имя Израиля!»","6":"Все они заодно, в сговоре, все в союзе против Тебя:","7":"эдомитяне в своих шатрах, измаильтяне, Моав, агарян'е,","8":"Библ, Аммон, амалекитяне, филистимляне, жители Тира.","9":"И Ассирия их поддержала, стала опорой сынам Лота! [Музыка]","10":"Поступи ж с ними как с Мидианом, как с Сисерой и Явином при реке Кишон,","11":"как с убитыми при Эн – Доре, чьи трупы в землю легли, как навоз!","12":"С их вожаками – как с Вороном и Волком, с их вождями – как с Зевахом, как с Цалмунной,","13":"как с теми, кто говорил: «Мы захватим владения Божий!»","14":"Гони их, Боже, как ветер – мякину или перекати – поле.","15":"Как пожар выжигает леса, как огонь опаляет горы,","16":"так смети их бурей Своей, Своим вихрем повергни в ужас!","17":"Лица их позором покрой! Пусть взыщут имя Твое, Господь!","18":"Пусть в бесчестье и сраме будут навек, пусть опозорены будут – и сгинут!","19":"Пусть узнают, что Ты, чье имя Господь, – Бог Вышний над всей землею!"},"83":{"1":"[Начальнику хора: напев «ха – Гиттит». Псалом сынов Кореевых.]","2":"Как желанны жилища Твои, Господь Воинств!","3":"Как я жажду войти во двор Храма Господня! Мои сердце и плоть поют, ликуя перед Богом Живым!","4":"Нашла птица себе жилище; ласточка – гнездо для птенцов, у алтарей Твоих, Господь Воинств, Царь мой и Бог мой!","5":"Блаженны живущие в доме Твоем – они вечно будут Тебя восхвалять. [Музыка]","6":"Блажен, кто черпает силу в Тебе, у кого в сердце – путь паломника,","7":"кто, идя долиной плача, делает ее долиной родников, и дождь покрывает ее озерами.","8":"Они идут, обретая силы, они предстанут пред Богом на Сионе.","9":"Господи, Боже сил! Услышь молитву мою! Внемли мне, о Бог Иакова! [Музыка]","10":"Боже, защитник наш! Посмотри, взгляни на помазанника Твоего.","11":"Один день во дворах Храма Твоего лучше тысячи дней! Лучше в доме Божьем стоять на пороге, чем жить в шатрах нечестивцев.","12":"Господь Бог – это солнце и щит, Господь милость и славу дает; тех, чей путь непорочен, Он не оставит без награды.","13":"О Господь Воинств! Блажен, кто уповает на Тебя!"},"84":{"1":"[Начальнику хора. Кореевых сынов. Псалом.]","2":"Господи! Ты был милостив к Своей стране, возвратил народ Иакова из плена;","3":"простил вину народа Твоего, отпустил ему все грехи, [Музыка]","4":"гневаться перестал, миновала ярость Твоя.","5":"Восстанови нас, Бог спасения нашего, перестань на нас негодовать.","6":"Неужели будет вечен гнев Твой на нас, из поколенья в поколенье будет ярость Твоя?","7":"Неужели нас снова не оживишь, чтобы народ Твой ликовал, что Ты с ним?","8":"Яви нам, Господи, милость Твою и даруй спасение Твое.","9":"Я слышу, что скажет Господь Бог. Он возвестит мир Своему народу – тем, кто верен Ему, кто живет надеждой.","10":"Близко спасение к тем, кто чтит Его: будет Слава обитать в стране нашей!","11":"Милость и верность встретятся, справедливость и мир расцелуются;","12":"верность произрастет из земли, праведность склонится с небес;","13":"Господь ниспошлет благо, а земля наша даст плоды свои.","14":"Праведность перед Ним пойдет и проложит путь для Него."},"85":{"1":"[Молитва Давида.] Прислушайся, Господи, ответь мне, ведь я беден и нищ.","2":"Сохрани мою жизнь, ибо я верен Тебе; спаси, меня, Твоего раба, ведь Ты мой Бог, я уповаю на Тебя.","3":"Помилуй меня, Господи, я к Тебе взываю весь день.","4":"Обрадуй меня, раба Твоего, на Тебя, Господи, надежда моя.","5":"Ты, Господи, благ и милосерд, Ты многомилостив ко всем, кто призывает Тебя.","6":"Услышь, Господи, молитву мою, внемли молению моему.","7":"В день скорби моей я взываю к Тебе, и Ты мне даешь ответ.","8":"Нет богов, подобных Тебе, нет деяний, подобных Твоим.","9":"Все народы, Тобою сотворенные, придут к Тебе, Господи, и склонятся, прославят имя Твое.","10":"Ты велик и творишь чудеса, – Ты Бог и другого нет.","11":"Направь меня, Господи, на Твой путь, чтоб я шел по нему, храня верность Тебе; веселиться будет сердце мое, почитая имя Твое.","12":"Всем сердцем хвалю Тебя, о Господь, мой Бог, буду вечно славить имя Твое,","13":"велика Твоя милость ко мне: Ты избавил мою душу от глубин Шеола.","14":"Боже! Напали на меня наглецы, скопище злодеев хочет смерти моей! До Тебя им и дела нет!","15":"Но Ты, Господи, Боже щедрый и добрый, долготерпеливый, многомилостивый, верный,","16":"Ты Сам взгляни на меня и помилуй меня; даруй силу Твою рабу Твоему, спаси сына Твоей рабы.","17":"Дай знак, что Ты добр ко мне, пусть увидят враги мои, посрамленные, что Ты, Господи, помог мне и утешил меня!"},"86":{"1":"[Сынов Кореевых. Псалом. Песнь.]","2":"Основал Он город на святой горе! Этот город на Сионе любит Господь больше всех селений Иакова.","3":"Разнеслась о тебе слава, Божий град! [Музыка]","4":"Я возвещу, что Рахав и Вавилон, филистимляне, Тир и Куш – все узнали про Меня: «Вот кто родился там!»","5":"Будут люди говорить о Сионе: «Вот кто родился в нем!» Сам Бог Вышний укрепляет его!","6":"Господь в переписи народов напишет: «Вот кто родился там!» [Музыка]","7":"Поющие и танцующие: «Все мои источники – в тебе!»"},"87":{"1":"[Песнь. Псалом сынов Кореевых. Начальнику хора: поется на напев «Махалат леаннот». Искусная песнь Хемана Эзрахитянина.]","2":"О Господь, Бог спасения моего, я и днем и ночью взываю к Тебе!","3":"Пусть молитва моя до Тебя дойдет, склони ухо к мольбе!","4":"Страдание душит меня, моя жизнь – на краю Шеола.","5":"Я – как те, кто в могилу сошел, в ком уже не осталось сил;","6":"как никому не нужный мертвец, как убитые, спящие в гробнице, о которых забыл и Ты – они уже не в Твоих руках…","7":"Ты низверг меня в яму преисподней, в пучину, во тьму.","8":"Тяжек Твой гнев для меня, волны сбили с ног. [Музыка]","9":"Ты друзей от меня прогнал прочь: они брезгуют мной. Я как в тюрьме и не выйти мне…","10":"Меркнут от горя мои глаза. Весь день я звал Тебя, Господи, к Тебе я руки простер!","11":"Разве явишь Ты мертвым Свои чудеса? Разве встанут тени, чтоб славить Тебя? [Музыка]","12":"Говорят ли во гробе про милость Твою? Среди тлена – про верность Твою?","13":"Разве знают во тьме о Твоих чудесах, в стране забвенья – о правде Твоей?","14":"Я взываю к Тебе! Пусть наутро, Господь, моя мольба пред Тобою предстанет!","15":"Почему, Господь, Ты меня отверг, почему отвернулся от меня?","16":"С юности ждут меня горе и смерть. От Твоих ужасов я изнемог.","17":"Твой гнев меня захлестнул, как волна, Тобою посланные страхи сломили,","18":"затопили меня, словно вода, окружают отовсюду, всегда.","19":"Близких Ты прочь от меня прогнал, и мой спутник – мрак."},"88":{"1":"[Искусная песнь Этана Эзрахитянина.]","2":"Твои милости, Господи, я буду вечно воспевать, из рода в род прославлять Твою верность.","3":"Слушайте! Навечно милость создана, на небесах водрузил Ты верность Свою. [Бог: ]","4":"Я с избранником Моим заключил договор и поклялся Давиду, рабу Моему:","5":"«Я вечно буду поддерживать потомков твоих, и воздвигну престол тебе – из рода в род». [Музыка]","6":"Небеса прославляют чудеса Твои, Господи, сонм Святых – верность Твою.","7":"Кто на небесах сравнится с Господом? Кто из сынов Божьих подобен Ему?","8":"Грозен Бог средь сонма Святых, страшнее всех, кто окрест Его.","9":"О Господь, Бог воинств! Кто подобен Тебе? Господь Крепкий! Верность окружает Тебя.","10":"Ты властвуешь над яростью моря: Ты укрощаешь волны его.","11":"Ты намертво поразил Рахав; рукой могучей рассеял Своих врагов.","12":"Небеса – Твои и земля – Твоя; Ты создал вселенную и все, что в ней есть.","13":"Север и юг Ты сотворил; Фавор и Хермон славят имя Твое.","14":"Сильна Твоя рука, крепка Твоя длань, Твоя десница простерта!","15":"Правосудие и правда – опоры трона Твоего; милость и верность идут перед Тобой.","16":"Блажен народ, которому ведом победный клич! Господи! Во свете лица Твоего идут они,","17":"об имени Твоем радуются весь день и гордятся Твоею праведностью.","18":"Ты – сила и слава наша, и по милости Твоей мы возносим чело.","19":"Щит наш – Господь, царь наш – Святой Бог Израилев.","20":"Ты сказал, в видении, верным Своим, Ты сказал: «Я возвысил витязя, которого избрал из народа.","21":"Я нашел Давида, раба Моего, и святым елеем Моим помазал его.","22":"Рука Моя будет помогать ему, рука Моя поддержит его.","23":"Враг не одолеет его, нечестивый не унизит его.","24":"Сокрушу врагов его перед ним и сражу ненавидящих его.","25":"С ним милость Моя и верность, и с именем Моим он гордо рог вознесет.","26":"Дам ему протянуть руку до Моря, протянуть десницу до Рек.","27":"Он будет звать Меня: „Ты мой отец, Ты мой Бог и скала спасительная\".","28":"И Я сделаю его Своим первенцем, он будет выше всех царей земных,","29":"Моя милость навек будет с ним, Мой договор с ним нерушим.","30":"Его роду Я дам вечно длиться, и престол его вечен, как дни неба.","31":"Если дети его оставят Закон Мой и веленьям Моим следовать не будут,","32":"если нарушат уставы Мои и заповедей Моих не сохранят,","33":"Я обрушу на них Мой посох, покараю их неправду ударами –","34":"но любовь Моя к ним не иссякнет, и верности Своей не нарушу,","35":"не нарушу Моего договора, не откажусь от Своего обещания.","36":"Я поклялся раз и навсегда, святостью поклялся Моей, что Давида Я не обману.","37":"Его род будет длиться вечно, его престол предо Мною, как солнце;","38":"как луна, он будет тверд навек. На небесах – верный свидетель клятвы». [Музыка]","39":"Но Ты пренебрег, возненавидел, отверг помазанника Своего;","40":"расторг договор с ним, рабом Твоим, его корону втоптал в пыль.","41":"Сделал в стенах проломы, превратил твердыни в руины.","42":"Все прохожие грабят его, и соседи смеются над ним.","43":"Ты позволил врагам над ним руку занести, и обрадовал всех его противников;","44":"Ты заставил его меч обратиться вспять и во время битвы не помог;","45":"лишил его царского блеска и престол его на землю поверг;","46":"дни его юности сделал короткими, как одеждой, покрыл его стыдом. [Музыка]","47":"Доколе, Господи, будешь скрываться? Доколе ярость Твоя будет пылать, как огонь?","48":"Вспомни, как короток век мой. Кем сотворил всех людей? Они ничто!","49":"Кто может жить и не увидеть смерти? Кто спасет душу свою от Шеола? [Музыка]","50":"Где Твои прежние милости, Господи? Ведь Ты поклялся быть верным Давиду.","51":"Взгляни, Господь, как издевались над рабами Твоими, издевательства чужеземцев покрыли меня;","52":"вспомни, Господь, как смеются враги Твои, как бесславят Твоего помазанника на каждом шагу.","53":"Благословен Господь вовек! Аминь, аминь."},"89":{"1":"[Молитва Моисея, человека Божьего.]","2":"Господи! Ты нам прибежище из поколения в поколение.","3":"Прежде чем родились горы, и земля, и мир на свет явились, от века и до века Ты – Бог.","4":"Ты возвращаешь человека назад, в пыль, Ты говоришь: «Сыны людские, назад!»","5":"Для Тебя тысяча лет – день вчерашний, что промелькнул и ушел, – или смена стражи в ночи.","6":"Ты смываешь людей, как дождем, они уходят, как сон поутру, как трава, что утром растет, цветет, а под вечер сохнет.","7":"Так и мы исчезаем от гнева Твоего, Твоя ярость приводит нас в ужас.","8":"Ты грехи наши выложил перед Собой, наши тайны – пред светом лица Своего.","9":"Наши дни сокращаются гневом Твоим; наши годы пролетают, как вздох.","10":"Срок нашей жизни – семьдесят лет, для того, кто силен, – восемьдесят; и большая часть их – мука и труд, и все проходит, и мы отлетаем.","11":"Кто может постичь силу гнева Твоего? Страх пред Тобой силен, как ярость Твоя.","12":"Научи нас, как считать наши дни, дай обрести мудрость сердца.","13":"Обернись, Господи! Доколе? Смилуйся над рабами Твоими.","14":"Наутро дай досыта вкусить милость Твою, чтобы мы радовались и ликовали всю жизнь.","15":"Даруй нам радость – за все дни, что Ты карал нас, за годы горя.","16":"Яви нам, рабам Твоим, величье Твоих дел, сынам рабов Твоих – славу Твоя!","17":"Да будет милость Господа, Бога нашего, с нами! Направь, помоги нам в делах наших рук, направь, помоги!"},"90":{"1":"[Псалмопевец: ] Ты, живущий под сенью Вышнего, приют нашедший под кровом Сильного,","2":"говорящий о Господе: «Он мой оплот, моя крепость, мой Бог, моя надежда»!","3":"Господь спасет тебя от сетей ловца, от всего, что гибель несет.","4":"Он Своими крылами укроет тебя: Его крылья – защита тебе. Его верность – щит и стена.","5":"Ни ужас ночной не страшен тебе, ни днем пущенная стрела,","6":"ни чума, крадущаяся в ночи, ни мор среди бела дня.","7":"Тысяча павших рядом с тобой, десять тысяч по правую руку твою, но тебя минует беда!","8":"Ты всего лишь свидетель: смотри и увидишь расплату грешных! [Праведник: ]","9":"– О Господь, Ты прибежище мне! [Псалмопевец: ] – Ты Вышнего выбрал оплотом своим,","10":"и горе к тебе не придет, и беда не войдет в твой дом.","11":"Он ангелам даст о тебе наказ – хранить тебя, куда бы ты ни шел,","12":"они на руках понесут тебя, чтобы ты не споткнулся о камень.","13":"Льва и гадюку ты будешь попирать; злого льва и дракона растопчешь. [Бог: ]","14":"– Он Меня любит и Я его спасу, Я защищу его, знающего имя Мое.","15":"Он призовет Меня, и Я услышу его, Я с ним в беде, приду на помощь и прославлю его!","16":"Дам насытиться долгой жизнью, дам увидеть, как Я его спасу!"},"91":{"1":"[Псалом. Песнь на день субботний.]","2":"Как хорошо славить Господа, воспевать Твое имя, Бог Вышний,","3":"утром петь про Твои милости и ночью – про верность Твою,","4":"на десятиструнной арфе, под напевы лиры.","5":"Все, что Ты сделал, Господи, радует меня, и я в восторге пою про дела рук Твоих.","6":"Как велики, Господи, деянья Твои! Как глубоки Твои замыслы!","7":"Глупец не знает, невежда не понимает их.","8":"Да, злодеи растут как трава, и нечестивые процветают, но им суждено навсегда исчезнуть, –","9":"а Ты, Господи, навеки велик!","10":"Ибо враги Твои, Господи, – ибо враги Твои сгинут, нечестивые разбегутся.","11":"Ты возносишь рог мой, как рог быка, свежий елей возлит на главу мою;","12":"Ты даешь мне без страха смотреть на врагов, слышать о злодеях приближающихся.","13":"Праведник, словно пальма, цветет, как ливанский кедр – возвышается.","14":"Укоренившиеся в Храме Господа во дворах дома Божьего цветут!","15":"Даже в старости они плодовиты, и сочны, и свежи.","16":"Это всем говорит, как справедлив Господь. Он – скала моя, и нет неправды в Нем."},"92":{"1":"Господь – Царь. Одеяние Его – слава, пояс Его облачения – мощь! Мир стоит и не дрогнет,","2":"и Твой вечный престол незыблем, Ты – от начала времен!","3":"Шумят потоки, Господь, шумят потоки, ревут, потоки ревут как гром!","4":"Не так страшен пучины рев, не так страшны морские валы, как могуч Господь в высоте!","5":"Наставленья Твои незыблемы, Твой Храм, Господь, навеки украсила святость!"},"93":{"1":"Бог воздаянья, Господь, Бог воздаянья, явись!","2":"Подымись, Судия земли, и отплати надменным.","3":"Доколе нечестивцам, о Господи, доколе ликовать нечестивцам?","4":"Говорят слова наглые; творят неправду – и тем хвастают;","5":"попирают народ Твой, Господи, унижают Твое достояние;","6":"убивают бездомных и вдов, умерщвляют сирот,","7":"говорят: «Не увидит Господь, Бог Иаковлев не узнает».","8":"Образумьтесь, безумцы! Как же вы, глупцы, не поймете?","9":"Создавший ухо – разве может не слышать? Создавший глаз – разве может не видеть?","10":"Он Наставник народов и Учитель людей – неужели Он с вас не спросит?","11":"Господь знает людские мысли: они призрачны, как туман.","12":"Блажен тот, кого Ты, Господи, учишь, наставляешь Законом Твоим,","13":"чтобы в дни беды дать ему прибежище, пока пред грешным не разверзнется яма.","14":"Нет, Господь Свой народ не оставит, достояние Свое не забудет,","15":"и правда воцарится в суде, и пойдут за ней все праведные сердцем.","16":"Кто вместе со мной станет против злодеев? Против тех, кто творит зло?","17":"Если бы Господь мне не помогал, жизнь моя ушла бы в страну молчания.","18":"Стоило сказать мне: «Я вот – вот упаду», как милость Твоя, Господи, меня укрепляла.","19":"Сколько бы ни было печалей в сердце моем, утешенья Твои радуют душу.","20":"Не причастен Тебе престол преступлений, рассадник горя и беззаконий.","21":"Набросились, праведника хотят убить, осудить, пролить кровь неповинную.","22":"Но Господь – защита моя, мой Бог – скала, что меня укрывает.","23":"Он их зло обратит против них же самих, Он истребит их за их преступление, Он – Господь, наш Бог – истребит их!"},"94":{"1":"Придите, будем петь перед Господом, восклицать пред Ним, Скалой спасения нашего.","2":"Предстанем с хвалой пред лицом Его, предстанем с песнями и восклицаниями.","3":"Господь – это Бог Великий, Царь Великий над всеми богами.","4":"В Его руке – глубины земли, принадлежат Ему горные вершины,","5":"и море, которое Он создал, и суша, которую слепили Его руки.","6":"Придите, станем на колени, поклонимся, падем ниц перед Господом, создавшим нас.","7":"Он наш Бог, а мы – народ, который Он пасет, мы – овцы, которых ведет Его рука. Если сегодня услышите вы голос Его,","8":"сердец не делайте упрямыми, как это было в Мериве , как тогда – в пустыне, в Массе ,","9":"где отцы ваши хотели Меня испытать, испытали – и увидели, что сделал Я!","10":"На сорок лет Я отвернулся от их поколенья, Я сказал: «Сердца их сбились с пути, Мои пути неведомы этому народу».","11":"Разгневался – и поклялся Я, что не придти им туда, где Я готовил им покой."},"95":{"1":"Пойте Господу новую песнь; пой Господу, вся земля;","2":"пойте Господу, имя Его благословляйте, день за днем возвещайте, как Он нас спас!","3":"Расскажите народам о славе Его, племенам земным – о чудесах Его.","4":"Велик Господь и достоин хвалы, Он страшен и грозен больше всех богов.","5":"Боги других народов – истуканы, а Господь небеса сотворил.","6":"Честь и слава – как свита пред Ним, сила и величие – в святилище Его.","7":"Величайте Господа, племена людей, величайте Господа, Его славу и мощь!","8":"Величайте славу Господнего имени! Неся дары, входите во дворы дома Его.","9":"Падите ниц пред Ним во славе Его святой! Трепещи пред Господом, вся земля;","10":"возвестите средь народов: «Господь – Царь»! Тверда вселенная, не поколеблется; Он будет справедливо судить народы.","11":"Да веселятся небеса, да торжествует земля, грохочет море и все, чем пучина полна;","12":"рады степи – и все, чем степи полны, и ликуют все деревья в лесу","13":"перед Господом – ибо Господь грядет, грядет Господь землю судить. Он, Справедливый, будет судить весь мир, Он, Верный, будет судить народы."},"96":{"1":"Господь – Царь! Да радуется земля, да веселятся многочисленные страны приморские.","2":"Вокруг Него облако, тьма густая; а в основании престола – правда, праведный суд.","3":"Перед Ним идет огонь, испепеляет вокруг всех врагов Его.","4":"Молнии Его озаряют вселенную; видит их земля – и дрожит.","5":"Горы, как воск, перед Господом тают, перед Владыкою всей земли.","6":"Небеса возвещают правосудие Его, все народы видят славу Его.","7":"Пусть посрамятся все, кто идолам служат и прославляют своих божков. Все божества, падите ниц перед Ним!","8":"Слышит – и ликует Сион, рады дочери Иудеи, рады, Господи, правосудию Твоему!","9":"Высоко Ты, Господи, над всею землею, высоко, выше всех божеств!","10":"Любящие Господа, ненавидьте зло! Бережет Он жизнь праведников Своих, избавляет от рук злодеев.","11":"Свет воссиял для праведника, радость – для тех, кто чист сердцем.","12":"Радуйтесь, праведные, о Господе! Славьте имя святое Его."},"97":{"1":"[Псалом.] Воспойте Господу новую песнь, ибо Он сотворил чудеса. Его рука, святая десница Его даровала победу Ему.","2":"Явил Господь победу Свою, явил народам правосудие Свое.","3":"Не забыл Он милость Свою, Свою верность племени Израиля. И увидели все концы земли победу нашего Бога.","4":"Ликуй пред Господом, вся земля: веселитесь, радуйтесь, пойте;","5":"пойте Господу под звуки арф, под звуки арф пойте, под музыку;","6":"пойте под звуки труб и рога, ликуйте пред Царем Господом.","7":"Пусть, как гром, поет море и все, что в нем есть, и вся вселенная, и все, кто живет в ней;","8":"пусть рукоплещут реки, пусть ликуют горы","9":"пред Господом: грядет Он вершить суд на земле! Он будет судить вселенную праведно, беспристрастно судить народы."},"98":{"1":"Господь – Царь, пусть трепещут народы! На херувимах восседает Он, пусть дрожит земля!","2":"Велик на Сионе Господь, над всеми народами высок.","3":"Да восславят они имя Твое: велико и страшно и свято оно!","4":"Он Могучий Царь. Он справедливость любит. Ты утвердил правосудие; справедливость и правду Ты творишь в стране Иакова.","5":"Превозносите Господа, Бога нашего, поклоняйтесь подножию ног Его: свято оно!","6":"Моисей и Аарон в числе священников Его, Самуил средь призывающих имя Его: они к Господу взывали, и Он им дал ответ.","7":"В столпе облачном говорил Он к ним; дал им Закон; они хранили заповеди Его.","8":"Господи, Боже наш! Ты давал им ответ; Ты был для них Богом прощающим и карающим за проступки.","9":"Превозносите Господа, Бога нашего, и поклоняйтесь на святой Его горе, ибо свят Господь, Бог наш."},"99":{"1":"[Псалом хвалебный.] Восклицай пред Господом, вся земля!","2":"Служите Господу радостно! Приходите к Нему с весельем!","3":"Знайте: Господь есть Бог, Он нас создал, и мы народ Его. Мы овцы пастбищ Его!","4":"Входите с хвалой во врата Его, с благодарением – во дворы Его. Благословите, славьте имя Его!","5":"Господь добр, и верность Его – навек. Из поколения в поколение верность Его!"},"100":{"1":"[Псалом Давида.] Воспеваю верность и правосудие, песнь пою Тебе, Господи!","2":"Все мои мысли – о правом пути. Когда ж Ты придешь ко мне? С чистым сердцем иду я по дому:","3":"на дела Зла не взираю, ненавижу дела отступников – я непричастен им!","4":"Чуждо мне коварное сердце, я ведать не ведаю зла!","5":"Тех, кто в тайне клевещет на ближнего, заставляю умолкнуть, дерзких сердцем и смотрящих свысока не терплю.","6":"По всей земле – верных находит мой взгляд: они будут жить рядом со мной. Тот, кто следует правым путем, будет мне слугой.","7":"Для коварных нет места в доме моем, и нет места лжецу перед взором моим!","8":"Что ни утро – истребляю я преступников с земли, из Города Господня – всех, кто делает зло."},"101":{"1":"[Молитва бедняка, когда он унывает и изливает пред Господом печаль свою.]","2":"Господи! Услышь молитву мою, пусть дойдет до Тебя мой крик.","3":"Не отворачивайся от меня! Когда скорблю, склони ко мне ухо Твое; когда зову, услышь, поспеши, помоги.","4":"Дни мои исчезают, как дым, как головешки, мои кости обуглены;","5":"сердце сохнет, как скошенная трава, я даже о пище забыл.","6":"От стонов моих я стал – кожа и кости.","7":"Я как филин в пустыне; как сова средь руин;","8":"я не сплю и сижу, как одинокая птица на кровле.","9":"Весь день враги оскорбляют меня, меня считают безумным, мое имя для них – что проклятье.","10":"Моей пищей стал пепел, питье со слезами смешано.","11":"Это сделали гнев Твой и ярость Твоя, Ты меня взял и бросил прочь.","12":"Дни мои исчезают, как тень, и я сохну, словно трава.","13":"Ты же, Господи, вовек пребываешь, Твое имя – из рода в род.","14":"Поднимись, яви милость к Сиону, что время помиловать его – что пришел срок.","15":"Нам, рабам Твоим, дороги и камни его, даже пыль его нам дорога .","16":"Пусть пред именем Господа трепещут народы, все земные цари – перед славой Твоей.","17":"Да! Господь отстроит Сион и явится во славе Своей;","18":"Он примет молитву беспомощных, не отвергнет моления их.","19":"Пусть напишут об этом для грядущих поколений, чтобы люди будущего хвалили Господа.","20":"Потому что, взглянув со святой высоты Своей, посмотрел Господь с небес на землю,","21":"потому что услышал стон узников, освободил обреченных на смерть.","22":"Пусть на Сионе возвещают имя Господа, в Иерусалиме поют хвалу Ему,","23":"когда вместе соберутся народы и царства – чтобы служить Господу.","24":"На пути моем отнял Он силы у меня, дни моей жизни сократил.","25":"Я сказал Ему: «Боже мой! Не забирай меня, не дав прожить и полжизни. Из поколения в поколение длятся годы Твои.","26":"Ты издревле заложил основание Земли, небеса – создание рук Твоих.","27":"Они погибнут – но останешься Ты. Все они, как платье, износятся, как одежду, Ты их переменишь,","28":"но Ты – все Тот же, годам Твоим нет конца.","29":"Сыны рабов Твоих будут жить пред лицом Твоим, и не пресечется их род»."},"102":{"1":"Благослови, душа моя, Господа! Благослови, мое сердце, имя святое Его!","2":"Благослови, душа моя, Господа, не забывай всех благодеяний Его!","3":"Прощает Он все грехи твои, исцеляет все недуги твои,","4":"спасает от гибели жизнь твою, милостью и щедротами окружает тебя!","5":"Насыщает тебя дарами Своими – и, как орел, ты вновь молода!","6":"Правосудье вершит Господь – заступается за всех угнетенных.","7":"Он явил Моисею Свои пути, сынам Израиля – Свои чудеса.","8":"Щедр и милостив Господь, долготерпелив, милосерд.","9":"Не навеки ярость Его, не навсегда гнев Его.","10":"Не по нашим грехам поступает Он – не сполна за них воздает.","11":"Как высоко простерто небо над землей – так велика милость Его к чтущим Его.","12":"Как далек от заката восход – так удалил Он от нас наши грехи.","13":"Как любит отец своих сыновей – так Господь любит чтущих Его.","14":"Он знает, из чего сделаны мы, помнит, что мы лишь пыль.","15":"Жизнь человека – что жизнь травы, он отцветает, как цветок полевой:","16":"ветер дунет, и нет его, и даже места, где был он, не вспомнить.","17":"От начала времен до конца времен Господь верен чтущим Его,","18":"добром платит детям и внукам тех, кто соблюдал договор с Ним и законы Его.","19":"Господь на небе воздвиг Свой престол, над всем миром царствует Он.","20":"Благословите Господа, ангелы Его – сильные, исполняющие слово Его и послушные слову Его.","21":"Благословите Господа, все воинства Его – слуги, исполнители приказов Его!","22":"Благословите Господа, все творенья Его – повсюду, где держава Его! Благослови, душа моя, Господа!"},"103":{"1":"Благослови, душа моя, Господа! Господь, Бог мой, как Ты велик! Твои облачения – величье и слава,","2":"как плащом, Ты окутан светом. Небо, словно шатер, раскинул,","3":"над водами чертоги возвел. Облака – колесница Твоя, Ты летаешь на крыльях ветра.","4":"Ты ветры делаешь Своими посланцами, Своими слугами – огонь и пламя.","5":"На опорах поставил Ты Землю, чтобы вовек не сдвинулась с места.","6":"Как одеждой, ее Океаном покрыл. Выше горных вершин были воды.","7":"Ты прикрикнул на них – побежали они, заспешили, когда прогремел Твой гром,","8":"по горам промчались, спустились в дол – собрались там, где Ты повелел.","9":"И Ты границы назначил для них: впредь они не затопят землю!","10":"По ложбинам Ты посылаешь ручьи, и текут они среди гор,","11":"они поят всех полевых зверей, утоляют онагры жажду.","12":"Над ручьями селятся птицы, средь листвы слышны их голоса.","13":"Орошаешь Ты горы из чертогов Своих, и плодами Твоих рук насыщается земля.","14":"Ты траву растишь для скота и злаки, чтобы люди возделывали их, чтобы хлеб добывали у земли:","15":"чтоб сердца людей вино веселило, чтобы лица их от масла блестели, чтобы хлеб подкреплял их силы.","16":"Напоены водой деревья Господни – Им посаженные кедры ливанские.","17":"Птицы там гнезда вьют, аисты живут среди сосен.","18":"Вершины приют дают горным козлам, скалы – приют даманам.","19":"Ты луну сотворил, чтобы показывала время. Солнцу час заката назначен.","20":"Ты наводишь тьму, наступает ночь, когда звери рыщут в лесу.","21":"Львы, рыча, на охоту выходят – ищут пищу, что Бог им послал.","22":"Когда Солнце взойдет – уйдут, в своем логове лягут спать.","23":"На работу идет человек – и до самого вечера трудится.","24":"Как многочисленны Твои творенья, Господи, и как же мудро Ты все устроил! Твои созданья заполнили землю.","25":"Вот необъятное широкое море, и без числа в нем тварей морских. Там животные большие и маленькие.","26":"Там плавают корабли. Левиафан, Твое творение, резвится там.","27":"Все к Тебе обращают взор – чтобы Ты дал им пищу, когда нужно.","28":"Ты подашь им – они подберут, Ты с ладони их кормишь – и они сыты.","29":"Ты отвернешься – они в смятении. Отберешь у них дыхание – умрут, снова станут глиной.","30":"Пошлешь Свой дух – они воссозданы. Так обновляешь Ты лик Земли.","31":"Слава Господу – вовеки! Пусть радуется Он твореньям Своим!","32":"Он посмотрит на Землю – она дрожит. Прикоснется к горам – дымятся.","33":"Буду петь о Господе доколе я жив, пока я есть – буду славить Его.","34":"Пусть Его порадует песнь моя, как и я о Господе радуюсь.","35":"Да не будет грешников на Земле! Да не будет на ней злодеев! Благослови, душа моя, Господа! Аллилуия!"},"104":{"1":"Славьте Господа, призывайте имя Его; возвещайте народам о деяниях Его;","2":"пойте о Нем, воспевайте Его; проповедуйте о чудесах Его;","3":"восхваляйте святое имя Его; да веселятся сердца тех, кто к Господу стремится!","4":"Ищите Господа, силу Его, и всегда стремитесь к Нему.","5":"Вспоминайте чудеса, сотворенные Им, деяния Его и приговоры Его уст.","6":"Вы, племя Авраама, раба Его! Вы, дети Иакова, избранника Его.","7":"Он Господь, наш Бог, вся земля подвластна суду Его.","8":"Вечно помнит Он Свой договор, что длится тысячу поколений.","9":"Он заключил договор с Авраамом, подтвердил его клятвой Исааку.","10":"Законом его сделал для Иакова, договор Его с Израилем – вечен!","11":"Он говорил: «Отдам вам землю Ханаана, вся она будет вашим владением»,","12":"хотя было их мало там, немногочисленные скитальцы.","13":"Из страны в страну ходили они среди разных царств и народов.","14":"Но никому не позволил Он обидеть их и царям о них давал повеления:","15":"«Не прикасайтесь к Моим помазанникам и пророкам Моим не делайте зла».","16":"И призвал Он голод на землю, и не стало у них хлеба.","17":"Он послал перед ними посланца: в рабы продан был Иосиф.","18":"Цепи стиснули ноги его; железом сжато было горло его,","19":"но пришло время – сбылось предсказание! Так испытало его слово Господне.","20":"Царь велел освободить его, отпустил его владыка народов;","21":"и поставил над своим владением и вручил ему все, что было у него,","22":"чтобы вельможам он мог приказывать и старейшин учил мудрости.","23":"И пришел Израиль в Египет, переселился Иаков в землю Хамову.","24":"Бог сделал многочисленным народ Свой, дал ему стать сильнее врагов,","25":"и те возненавидели Божий народ, замышляли зло против рабов Его.","26":"Но Он послал Моисея, раба Своего, Аарона, Своего избранника,","27":"и они сотворили Его знамения: чудеса в земле Хамовой.","28":"Послал тьму, и страну объял мрак – они не ослушались приказа Его.","29":"По всей стране превратил воду в кровь и убил рыбу в реке.","30":"Земля их стала кишеть жабами, проникли они даже в царскую спальню.","31":"Он велел появиться оводам, мошки страну наполнили.","32":"Он превратил дождь в град и в огонь палящий – по всей земле их,","33":"побил у них виноград и смоковницы, по всей стране поломал деревья.","34":"Он повелел – и пришла саранча без числа, один рой за другим,","35":"и съела у них всю траву, и пожрала плоды на полях их.","36":"Он перебил в той стране всех первенцев, все первые плоды мужской силы их.","37":"И увел прочь, с серебром и золотом, невредимыми племена Израиля.","38":"И Египет был рад, что они ушли: такой страх перед ними был в Египте.","39":"А Бог сделал облако завесой для них, послал огонь, чтобы светить им ночью.","40":"По их просьбе послал им перепелов, хлебом небесным насыщал.","41":"Разверз скалу, и потекли воды, потекли рекой по пустыне.","42":"Вспомнил Он слово святое Свое – обещание Аврааму, рабу Его, –","43":"и вывел народ Свой в радости, избранников Своих – в веселии,","44":"и дал им земли других народов, они наследовали труды этих народов.","45":"Так пусть теперь соблюдают законы Его и хранят заповеди Его! Аллилуия!"},"105":{"1":"Аллилуия. Славьте Господа, ибо Он благ, ибо милость Его вовек.","2":"Кто опишет могущество Господа, восхвалит Его за все, что Он сделал?","3":"Блажен, кто следует заповедям и непрестанно живет по правде!","4":"Вспомни обо мне, Господи, когда творишь благодеянья народу Твоему; не забывай про меня, когда являешь спасение Твое.","5":"Дай видеть счастье Твоих избранников, веселиться вместе с народом Твоим, с ним – достояньем Твоим – славить Тебя!","6":"Мы согрешили вслед за нашими отцами, мы, как они, творили зло и неправду.","7":"Не вразумили их в Египте чудеса Твои, они забыли, сколько Ты сделал добра, и взбунтовались у Красного моря.","8":"Но спас Господь их – чтоб прославить имя Свое, чтобы явить могущество Свое.","9":"Пригрозил Красному морю – и иссохло оно; сквозь пучину их провел, как по суше;","10":"от неприятелей спас и от врага избавил.","11":"Воды покрыли врагов – никто из них не уцелел.","12":"Тогда они поверили словам Его, тогда они пели хвалы Ему.","13":"Но скоро забыли, что сделал Он, не стали ждать, пока свершится Его замысел;","14":"в пустыне поддались своим желаниям, в земле безводной Бога испытывали,","15":"и их просьбу Бог выполнил, но наслал на них мор.","16":"Начали в стане завидовать Моисею и Аарону, святому слуге Господа.","17":"Земля разверзлась, поглотила Дафана, погребла сборище Авирона:","18":"вспыхнул огонь в их скопище, и пламя сожгло нечестивых.","19":"Они сделали тельца при Хориве, они стали поклоняться истукану;","20":"Бога – Славу свою – променяли на подобие вола, траву жующего.","21":"Забыли Бога, своего Спасителя, совершившего в Египте великое,","22":"чудесное в земле Хамовой, страшное у Красного моря.","23":"И Он сказал: «Истреблю их!» Но встал Моисей, избранник Его, и своим телом эту брешь заслонил и не дал излиться гневу Его.","24":"Они отвергли землю желанную, не поверили Его обещанию;","25":"они роптали в шатрах своих и не послушались Господа.","26":"И занес Он руку Свою, чтобы пали они в пустыне,","27":"чтобы пали их дети в чужих странах, чтобы рассеялись они меж народами.","28":"Они Пеорскому Ваалу поклонялись, вкушали жертвы, принесенные мертвым,","29":"Бога делами своими оскорбляли – и начался у них мор.","30":"Пинехас совершил свой суд – и мор прекратился.","31":"Это стало его заслугой навеки, из рода в род.","32":"Они прогневали Бога у вод Меривы, из-за них пострадал Моисей:","33":"они разъярили дух его, и сказал он слово необдуманное.","34":"Не истребили они народы, как им повелел Господь,","35":"но смешались с другими племенами и научились поступать как они;","36":"они стали служить истуканам их – и те сделались для них западней.","37":"Они приносили сыновей своих и дочерей своих в жертву демонам;","38":"проливали кровь невинную, кровь своих сыновей и дочерей, приносили их в жертву Ханаанским идолам – и земля осквернилась кровью;","39":"запятнали себя преступлениями, все поступки их были – блуд.","40":"И прогневался Господь на народ Свой, стал гнушаться Своим достоянием","41":"и отдал их в руки язычников, враги стали повелевать ими.","42":"Неприятели их притесняли, приходилось им подчиняться.","43":"Сколько раз Господь избавлял их! Но они избирали бунт против Него, и терпели униженья – за грехи свои.","44":"Но когда Он видел беду их, и когда слышал вопль их,","45":"вспоминал Он про Свой договор с ними и раскаивался Он, многомилостивый,","46":"и заставлял притеснителей сострадать им, пленникам.","47":"Спаси нас, Господи, Боже наш, собери нас от чужих народов, дай славить имя Твое святое, дай хвалиться тем, что хвалим Тебя.","48":"Благословен Господь, Бог Израилев, от века и до века! И да скажет весь народ: «Аминь! Аллилуия!»"},"106":{"1":"Хвалите Господа, ибо Он добр! Навеки милость Его!","2":"Это скажут те, кого Господь освободил – избавил от рук врага,","3":"кого собрал Он со всех краев: и с востока, и с запада, и с севера, и с моря.","4":"Одни блуждали по безводной пустыне, потеряли дорогу к людским селеньям,","5":"их мучили голод и жажда, и жизнь покидала их.","6":"Но воззвали они к Господу в несчастье своем – и Он избавил их от беды:","7":"показал им правильный путь, дорогу к людским селеньям.","8":"И славят они Господа за Его доброту, за чудеса, что Он творит для людей.","9":"За то, что жаждущих Он напоил, накормил умирающих от голода.","10":"Другие сидели во тьме и мраке, в железных оковах мучились,","11":"за то, что отвергли слова Бога, не послушались воли Вышнего,","12":"они надрывались от тяжкого труда; упадут – никто не поможет!","13":"Но воззвали они к Господу в несчастье своем – и Он избавил их от беды:","14":"вывел Он их из мрака и тьмы, и их оковы разбил.","15":"И славят они Господа за Его доброту, за чудеса, что Он творит для людей.","16":"За то, что сокрушил медные двери, разломал железные засовы.","17":"Кого-то грех до болезни довел – и страдали они за свою вину.","18":"От любой пищи их душа отвращалась, они были уже у врат смерти.","19":"Но воззвали они к Господу в несчастье своем – и Он избавил их от беды:","20":"послал целительное слово Свое – и избавил их от могилы.","21":"И славят они Господа за Его доброту, за чудеса, что Он творит для людей,","22":"приносят они Ему жертву хвалы, радуясь, возвещают, что сделал Он.","23":"Иные плавали по морю на кораблях, по безбрежным водам прокладывали путь.","24":"Они – свидетели деяний Господа, чудес, что Он средь пучины творит.","25":"Он слово сказал – и подул ветер, поднял бурю на море.","26":"До небес неслись они, падали в бездну, их сердца сжимались от ужаса.","27":"Кружились они, шатались, как пьяный, все познания стали им ни к чему.","28":"Но воззвали они к Господу в несчастье своем – и Он избавил их от беды.","29":"Унял бурю, настала тишина, и волненье утихло.","30":"Как рады они были, что буря улеглась! Он привел их в желанную гавань.","31":"И славят они Господа за Его доброту, за чудеса, что Он творит для людей.","32":"В народном собрании превозносят Его, прославляют среди старейшин.","33":"Там, где реки текли, Он сделал пустыню, там, где били источники, – ныне сушь.","34":"Плодородную землю Он обратил в солончак за грехи живущих на ней людей.","35":"А на месте пустыни устроил Он озеро, там, где сушь была раньше, – источники бьют.","36":"Он приводит туда тех, кто прежде голодал; они строят селенья, живут в них,","37":"они засеивают поля, виноградники разводят и собирают урожай.","38":"И Он их благословляет: их становится все больше, и скотом они владеют немалым.","39":"А других становится все меньше, им плохо от невзгод, скорбей и бед.","40":"Знатных Он покрывает позором, заводит в пустыню, сбивает с пути.","41":"А бедняков возвышает, выводит из нужды – теперь их семьи многочисленны, словно стада!","42":"Смотрят праведные – и веселятся, а нечестие и рта не смеет раскрыть.","43":"Пусть же мудрый внимательно всмотрится в это, размышляя, как добр Господь!"},"107":{"1":"[Песнь. Псалом Давида.]","2":"Твердо сердце мое, Боже: буду петь, воспевать песнопенья. Душа моя!","3":"Пробудитесь, арфа и лира, и я разбужу рассвет.","4":"Среди народов прославлю Тебя, Господь, средь всех племен Тебя воспою.","5":"Велика милость Твоя – выше небес, верность Твоя – до облаков.","6":"Будь превознесен, Боже, выше небес, и над всею землей да будет слава Твоя!","7":"Чтобы уцелели те, кто дорог Тебе – спаси их рукой Своей. Дай нам ответ!","8":"В Своем святилище Бог сказал: «Торжествуя, буду земли Шехема делить, делить земли в долине Суккот.","9":"Галаад – мой, Манассия – Мой, Ефрем – шлем на главе Моей, Иудея – скипетр Мой.","10":"Моав – Мой умывальный таз, Эдому брошу сандалию Мою. Над Филистией Мой клич прозвучит!»","11":"Кто поможет войти в укрепленный город? Кто в поход на Эдом поведет?","12":"Ведь Ты, Боже, нас отверг! С нашим войском в бой не идешь!","13":"Помоги победить врага: нет надежды нам на людей.","14":"С Божьей помощью мы победим, Он одолеет наших врагов."},"108":{"1":"[Начальнику хора. Псалом Давида.] Боже! Тебе моя хвала! Не молчи!","2":"Уста лживые и злые распахнулись на меня. Язык коварный со мной говорит.","3":"Слова ненависти окружили меня. Без причины на меня нападают.","4":"За мою любовь – ненавидят меня. Я в ответ молюсь…","5":"За мое добро отплатили мне злом, и враждою – за дружбу.","6":"Боже, предай его в руки злодея, обвинитель да встанет рядом с ним,","7":"да будет он осужден на суде, молитва его да будет в грех.","8":"Да будут короткими дни его, а место его да займет другой.","9":"Да станут сиротами дети его, жена да станет вдовой.","10":"Пусть скитаются нищими дети его, из развалин их дома пусть гонят их прочь;","11":"пусть возьмет ростовщик все, что есть у него, пусть чужие разграбят все, что сделал он.","12":"Пусть никто не поможет ему, и не пожалеет сирот его;","13":"да будет его род обречен, чрез поколенье да забудется имя его.","14":"Да вспомнит Господь грех его отцов, да не забудет грехи матери его;","15":"пусть всегда пред взором Господа будут, пока весь этот род Господь с земли не сотрет!","16":"За то, что он не знал доброты, что бедного и нищего гнал, сокрушенного сердцем хотел добить.","17":"Ему любо проклятье – так пусть падет на него; благословенье не мило – пусть лишится его.","18":"Да станет проклятье одеяньем его, да войдет, как вода, в утробу его, да пройдет, как масло, в кости его;","19":"да станет рубахой на теле его, поясом, что всегда на нем.","20":"Так Господь да отплатит врагам моим – тем, кто злое замышляют на меня!","21":"Помоги мне, Господи, Господи, ради имени Твоего, Ты верен и добр, спаси!","22":"Я беден, я нищ, сердце мое болит.","23":"Я исчезаю, как тень, прочь стряхнули меня, как саранчу.","24":"Подкосились колени мои от поста, тело мое исхудало.","25":"Я стал для людей посмешищем: на меня смотрят, головами качают.","26":"Помоги мне, Господи, Боже мой, и по милости Твоей даруй спасенье,","27":"пусть поймут: Твоя рука даровала его, пусть поймут, что это сделал Ты, Господи.","28":"Проклинают они, а Ты благослови; они напали – пусть будут посрамлены, и возрадуюсь я, Твой раб.","29":"Позор да станет одеждою моих клеветников, пусть завернутся в бесчестье, как в плащ.","30":"А я прославлю Господа устами моими, среди множества людей восхвалю Его:","31":"Он стал по правую руку бедняка, спас бедняка от тех, кто вынес приговор ему."},"109":{"1":"[Псалом Давида.] Сказал Господь господину моему: восседай по правую руку Мою, а Я повергну Твоих врагов под ноги Твои.","2":"Жезл силы ниспошлет Тебе Господь с Сиона: будь повелителем среди врагов Твоих.","3":"Народ Твой – в ополченьи в день выхода на битву. На святых горах, как росу, из чрева зари Я родил Тебя.","4":"Клялся Господь и не возьмет назад слова: «Ты священник навек, по чину Мелхиседека».","5":"Господь по правую руку Твою. В день гнева Своего Он сразит царей;","6":"свершит суд над народами, все наполнит трупами, по всей земле головы сокрушит.","7":"По пути будет пить из потока, и гордо голову вознесет."},"110":{"1":"Аллилуия. Славлю Господа всем сердцем среди собранья праведных и среди общины.","2":"Велики дела, сделанные Господом, в них вникают все, кто любит их.","3":"Дела Его – величие и красота, Его праведность пребывает вовек.","4":"Прославил Он чудеса Свои, милостив и щедр Господь.","5":"Пищу дает тем, кто чтит Его; вечно помнит Он договор Свой.","6":"Мощь Свою Он явил народу Своему, дав ему овладеть страной язычников.","7":"Правосудие и истина – дела рук Его; все повеления Его нерушимы,","8":"утверждены во веки веков, в их основании – истина и правда.","9":"Он послал избавление народу Своему, велел вечно блюсти договор с Ним. Свято и страшно имя Его!","10":"Начало мудрости – страх пред Господом; здравый разум у всех, кто ему следует. Хвала Господу будет вечной!"},"111":{"1":"Аллилуия. Блажен, кто благоговеет пред Господом, кто крепко любит наставления Его.","2":"Могучим будет на земле потомство его; род праведных благословен.","3":"Слава и богатство у его семьи, его праведность вовек не забудется.","4":"Среди тьмы восходит свет для праведных; Господь милостив, щедр и праведен.","5":"Кто добр, тот милостив и взаймы дает, по справедливости вершит дела свои.","6":"Вовеки не пошатнется он; слава вечная будет праведнику.","7":"Не страшна ему худая молва: сердце его твердо уповает на Господа.","8":"Спокойно сердце его – и без страха смотрит он на своих врагов.","9":"Беднякам раздал дары, его праведность вовек не забудется. Гордо поднимет он голову.","10":"С завистью посмотрит на это нечестивец, заскрежещет зубами и растает. Желания нечестивцев не сбудутся!"},"112":{"1":"Аллилуия. Хвалите, рабы Господни, хвалите имя Господне.","2":"Да будет имя Господне благословенно и ныне и навек.","3":"От восхода солнца до запада прославлено имя Господне.","4":"Высоко над всеми народами Господь. Выше небес слава Его.","5":"Кто подобен Господу, нашему Богу? Высоко Господень престол,","6":"но Он смотрит на то, что внизу – на небе, на земле;","7":"из пыли Он поднимает бедного, из пепла поднимает нищего,","8":"чтобы посадить его со знатью, с вельможами народа его;","9":"бесплодной женщине дает воссесть в кругу семьи счастливой матерью. Аллилуия!"},"113":{"1":"Когда Израиль ушел из Египта, род Иакова – от чужеземцев,","2":"стал Иуда святынею Бога, Израиль – владением Его.","3":"Море, видя их, убежало, Иордан потек вспять.","4":"Горы прыгали, как барашки, и холмы – как ягнята.","5":"Что с тобой, море, почему ты бежишь? Что с тобой, Иордан, почему потек вспять?","6":"Что вы, горы, прыгаете, как барашки? И вы, холмы, как ягнята?","7":"Пред лицом Господа трепещи, земля, пред лицом Бога Иаковлева!","8":"Он скалу превращает в озеро, камень – в источник вод.","9":"Не нас, о Господь, не нас – но имя Свое прославь, яви Свою милость и верность!","10":"Зачем язычникам говорить про нас: «Так где же Он, их Бог»?","11":"Бог наш – на небесах, Он делает все, что захочет!","12":"А их идолы – серебро и золото, изделия рук человеческих:","13":"есть рот – но не говорят; есть глаза, но не видят;","14":"уши есть, но не слышат; есть ноздри, но не обоняют.","15":"Есть руки, но не осязают; есть ноги – но идти не могут. Ни звука их горло не произнесет.","16":"Пусть такими же станут все, кто делает их, и все, кто на них надеется!","17":"Израиль! Уповай на Господа. Он нам помощь и щит.","18":"Род Аарона! Уповай на Господа. Он нам помощь и щит.","19":"Чтущие Господа! Уповайте на Господа. Он нам помощь и щит.","20":"Господь помнит нас и благословляет: благословляет Он род Израиля, благословляет род Аарона.","21":"Благословляет Он чтущих Господа – и маленьких и больших.","22":"Пусть Господь сделает вас многочисленными – и вас, и ваших детей.","23":"Вас благословляет Господь, сотворивший небо и землю.","24":"Небо – небо для Господа, а землю дал Он сынам человеческим.","25":"Не мертвые поют хвалу Господу, не те, кто нисходит в Тишь, –","26":"но мы Господа благословляем – благословляем и сейчас, и вовек. Аллилуия."},"114":{"1":"Я люблю Господа; слышит Он мой крик, моленья мои.","2":"Склоняет ухо Свое ко мне, призывать Его буду, пока жив!","3":"Узы Смерти меня опутали, предо мной предстали беды Шеола, предстоят мне горе и скорбь!","4":"Господа по имени призвал я: «Господи! Спаси мне жизнь!»","5":"Милостив Господь и справедлив, сострадателен наш Бог,","6":"простецов Господь хранит, я изнемогал – Он спас меня.","7":"Жизнь моя! Вернись к покою и миру, ведь Господь творит тебе добро!","8":"Ты избавил жизнь мою от смерти, глаза – от слез, не дал ногам споткнуться. И пред лицом Господа пойдет жизнь моя на земле живых!"},"115":{"1":"Я говорю: «Я в беде», но все равно я веру храню.","2":"В смятении я говорю: «Ненадежен любой человек».","3":"За благодеянья Господа – чем могу я Ему отплатить?","4":"Вознесу чашу спасенья, имя Господа призову,","5":"и обеты, что я дал Господу, перед всем Его народом исполню.","6":"Дорого стоит для Господа смерть тех, кто верен Ему.","7":"Господи, я Твой раб, я Твой раб, сын рабыни Твоей. Ты избавил меня от уз!","8":"Благодарственную жертву принесу Тебе, имя Господа призову,","9":"и обеты, что я дал Господу, перед всем Его народом исполню –","10":"во дворах Господнего Храма, среди тебя, Иерусалим! Аллилуия."},"116":{"1":"[Аллилуия.] Хвалите Господа, все народы, все страны, славьте Его!","2":"Велика Его милость к нам, и вечна верность Господня. Аллилуия."},"117":{"1":"Славьте Господа! Ведь Он добр, и милость Его навек.","2":"Да скажет Израиль про Него: «Милость Его навек».","3":"Да скажет род Ааронов про Него: «Милость Его навек».","4":"Да скажут те, кто Господа чтит: «Милость Его навек».","5":"В беде Господа я призвал – и Он вывел меня на простор.","6":"Господь за меня – и я не боюсь: что сделает мне человек?","7":"Господь помогает мне: мне не страшно смотреть на врагов.","8":"Довериться Господу лучше, чем уповать на людей.","9":"Довериться Господу лучше, чем уповать на вельмож.","10":"Все народы меня обступили, именем Господа я низверг их;","11":"обступили меня, окружили, именем Господа я низверг их;","12":"окружили меня, как пчелы, – чадили, как огонь в терновнике, – именем Господа я низверг их!","13":"Они толкнули меня, чтобы я упал, но Господь поддержал меня.","14":"Господь – моя мощь, Он – сила моя! Он – спасенье Мое!","15":"В шатрах праведников – крики победы и веселья, рука Господа явила силу свою!","16":"Высока Господня рука, рука Господа явила силу свою!","17":"Не умру, но останусь жив и возвещу, что сделал Господь.","18":"Господь строго меня наказал, но смерти не предал меня.","19":"Отворите мне врата праведности, я войду в них и прославлю Господа.","20":"Вот они, врата Господа, праведные в них войдут.","21":"Я славлю Тебя, что Ты дал мне ответ, Ты стал для меня спасеньем.","22":"Камень, который отвергли строители, стал краеугольным камнем.","23":"Это сотворил Господь – у нас на глазах свершилось чудо.","24":"Вот что сделал Господь в этот день: будем радоваться и веселиться!","25":"Господи, спаси! Господи, поддержи!","26":"Благословен грядущий во имя Господне! Благословляем вас из дома Господнего.","27":"Бог – Господь, Он нас светом осиял. – Вяжите праздничную жертву, к рогам жертвенника несите ее!","28":"Ты – мой Бог, я буду Тебя прославлять, Ты – мой Бог, я буду Тебя превозносить.","29":"Славьте Господа! Ведь Он добр, и милость Его навек."},"118":{"1":"Блаженны, чей путь непорочен, кто соблюдает Закон Господа.","2":"Блаженны, кто хранит повеления Его, кто всем сердцем ищет Его,","3":"кто не делает зла и идет путями Его.","4":"Ты заповедал твердо хранить повеленья Твои.","5":"Пусть мой путь не отступает от законов Твоих,","6":"чтобы я мог без стыда взирать на все заповеди Твои.","7":"Чистым сердцем я славлю Тебя, учу уставы правды Твоей.","8":"Твои законы я соблюдаю. Не оставляй меня!","9":"– Как юноше соблюсти непорочным свой путь? – Пусть живет, как учит слово Твое.","10":"Всем сердцем моим я ищу Тебя; не дай от заповедей Твоих отойти.","11":"Глубоко в сердце храню я слово Твое, чтобы перед Тобой не грешить.","12":"Благословен Ты, Господи! Научи меня законам Твоим.","13":"Провозглашает язык мой все законы, изреченные устами Твоими.","14":"Путь Твоих заповедей – радость для меня, словно огромное богатство,","15":"Я учу повеления Твои, я взираю на пути Твои.","16":"Твои законы – радость для меня, я не забываю слова Твоего.","17":"Окажи милость мне, рабу Твоему, я буду жить и хранить слово Твое.","18":"Открой очи мои, дай видеть чудеса Закона Твоего.","19":"Я ведь гость на земле; не скрывай от меня заповедей Твоих.","20":"Всегда томится моя душа жаждой правых велений Твоих.","21":"Приструнил Ты надменных, прокляты они, отступившие от законов Твоих.","22":"Срам и позор удали от меня, ибо я храню заповеди Твои.","23":"Вельможи составляют заговор против меня, а я, раб Твой, углубляюсь в Закон Твой.","24":"Твои заповеди мне приносят радость, для меня они – советники мои.","25":"Жизнь моя повержена в прах; оживи меня словом Твоим.","26":"Я поведал Тебе путь свой, и Ты дал мне ответ; научи меня законам Твоим.","27":"Дай уразуметь путь повелений Твоих, и я буду размышлять о чудесах Твоих.","28":"Жизнь моя тает от горя; укрепи меня словом Твоим.","29":"Удали от меня путь лжи, будь милостив, даруй мне Закон Твой.","30":"Путь истины я избрал, я жажду заповедей Твоих.","31":"Наставлений Твоих я держусь, Господи, не посрами меня.","32":"Я спешу по пути велений Твоих, Ты даешь знание сердцу моему.","33":"Научи меня, Господи, идти путем заповедей Твоих, и я буду его держаться.","34":"Вразуми меня, и я буду соблюдать Закон Твой, всем сердцем буду его хранить.","35":"Веди меня по стезе заповедей Твоих, она желанна мне.","36":"Обрати мое сердце к заветам Твоим, а не к корысти.","37":"Отврати очи мои от лжи; даруй мне жизнь на пути Твоем.","38":"Исполни слово, что Ты дал мне, рабу Твоему, и я буду благоговеть перед Тобой.","39":"Я боюсь позора, не посрами меня! Законы Твои – это благо.","40":"Жажду я наставлений Твоих; Ты, Праведный, даруй мне жизнь.","41":"Да будут со мной милости Твои, Господи, спасение Твое по слову Твоему, –","42":"и я отвечу тому, кто поносит меня, ибо верю я слову Твоему.","43":"Не оставь мою речь без слова истины, я уповаю на Твое правосудие","44":"и буду соблюдать Закон Твой всегда, во веки веков.","45":"По простору я буду идти, ведь я стремлюсь исполнять повеления Твои.","46":"Я расскажу царям о наставлениях Твоих, и не придется мне стыдиться.","47":"Заповеди Твои – радость для меня, так я люблю их.","48":"С любовью руки простер я к заповедям Твоим и размышляю о повелениях Твоих.","49":"Вспомни слово Свое ко мне, рабу Твоему, на это слово Ты мне велел уповать.","50":"Чем мне утешиться в горе моем? Слово Твое дает мне жизнь.","51":"Надменные надо мной смеются, но я не отступил от Закона Твоего.","52":"Вспоминал Твои древние законы, Господи, – и тем утешался.","53":"Ярость овладевает мною, когда вижу грешников, оставивших Закон Твой.","54":"Законы Твои стали мне как песни на чужбине, где я живу.","55":"Ночами вспоминал я имя Твое, Господи! Я храню Закон Твой.","56":"Так поступаю я, живя по заповедям Твоим.","57":"Соблюдая слова Твои, я говорю: «Достоянье мое – Господь».","58":"Всем сердцем я умоляю Тебя: помилуй меня по слову Твоему.","59":"Размышляя о путях моих, я направил стопы мои к заветам Твоим.","60":"Я спешу и не медлю соблюдать заповеди Твои.","61":"Сети злодеев опутали меня, но я Закона Твоего не забыл.","62":"В полночь встаю славить Тебя за праведные законы Твои.","63":"Я с теми, кто чтит Тебя и Твои повеления хранит.","64":"Господи, земля полна Твоей любви, научи меня заповедям Твоим.","65":"Мне, рабу Твоему, Ты творишь добро по слову Твоему, Господи.","66":"Благоразумию и знанию меня научи, я твердо держусь заповедей Твоих.","67":"Я заблуждался, пока не прошел через страдание, а ныне слово Твое храню.","68":"Ты добр, Ты творишь добро, научи меня уставам Твоим.","69":"Надменные окружили меня ложью, но я всем сердцем храню повеления Твои.","70":"Сердца их заплыли жиром, а мне Твой Закон – радость.","71":"Благо мне, что я прошел через страдание, так я учусь уставам Твоим.","72":"Закон уст Твоих – благо для меня, лучше тысяч слитков золота и серебра.","73":"Руки Твои сотворили и создали меня; вразуми меня – и научусь заповедям Твоим.","74":"Чтущие Тебя на меня взглянут с радостью – ведь я на слово Твое уповал.","75":"Знаю, Господи, что решения Твои праведны, что по справедливости Ты наказал меня.","76":"Пусть милость Твоя утешит меня, как обещал Ты мне, рабу Твоему.","77":"Да будет со мной милость Твоя, да дарует жизнь, Твой Закон – радость для меня.","78":"Посрамятся надменные, ни за что притеснявшие меня; а я буду учиться предписаниям Твоим.","79":"Вокруг меня соберутся те, кто чтит Тебя и знает повеления Твои.","80":"Да будет сердце мое непорочно пред законами Твоими, тогда я не посрамлюсь.","81":"Томится моя душа, ожидая от Тебя спасения; я уповаю на слово Твое.","82":"Слепнут мои глаза, ожидая Твоего слова; я говорю: «Когда же Ты дашь мне утешение?»","83":"Стал я словно закоптившийся бурдюк, но уставов Твоих не забыл.","84":"Сколько дней остается мне, рабу Твоему? Когда осудишь Ты преследователей моих?","85":"Яму вырыли мне надменные, пренебрегая Законом Твоим.","86":"Все заповеди Твои – истина. Меня преследуют ни за что! Помоги мне!","87":"Едва не стерли меня с лица земли, но не оставил я заповедей Твоих.","88":"По милости Твоей подари мне жизнь, буду хранить предписания, данные Тобой.","89":"Навеки, Господи, слово Твое утверждено на небесах.","90":"Верность Твоя – из поколения в поколение. Ты поставил землю, и стоит она.","91":"Все доныне стоит по повелениям Твоим, все служит Тебе.","92":"Если бы не Закон Твой, ставший радостью моей, я бы погиб в беде моей.","93":"Вовеки не забуду повелений Твоих, через них Ты даешь мне жизнь.","94":"Твой я, спаси меня; к Твоим заповедям я обращаюсь.","95":"Злодеи подстерегают меня, чтобы погубить; а я углубляюсь в наставления Твои.","96":"У любого совершенства виден предел, беспредельны лишь заповеди Твои.","97":"Как люблю я Закон Твой! Я весь день размышляю о нем.","98":"Твоя заповедь навеки со мною, она сделала меня мудрее врагов моих.","99":"Я стал мудрее всех своих учителей, ведь Твои предписания – у меня на устах.","100":"Я стал мудрее старцев, потому что храню повеления Твои.","101":"Я не даю ногам моим ступать на путь зла, потому что храню слово Твое.","102":"От законов Твоих я не отступаю, потому что Ты учишь меня.","103":"Как сладки моему языку Твои слова! Они слаще меда для уст моих.","104":"Наставления Твои дают мне знание, я ненавижу пути лжи.","105":"Слово Твое – светильник ногам моим, оно освещает мне путь.","106":"Я клялся хранить праведные законы Твои и исполню клятву.","107":"Притесняют меня, Господи; даруй мне жизнь по слову Твоему.","108":"Добровольную жертву прими – мои слова, и законам Твоим, Господи, научи меня.","109":"Жизнь моя все время – на волоске, но Закона Твоего я не забыл.","110":"Злодеи расставили сети на меня, но от велений Твоих я не отклонился.","111":"Твои заветы – мое наследие навек, они – веселье для сердца моего.","112":"Я всем сердцем стремлюсь к тому, чтобы всегда жить по законам Твоим.","113":"Двоедушных я ненавижу, а Закон Твой люблю.","114":"Ты мое прибежище, Ты щит мой; я на слово Твое уповаю.","115":"Отойдите от меня, злодеи, я храню заповеди Бога моего.","116":"Укрепи меня по слову Твоему, даруй жизнь, не посрами меня в надежде моей.","117":"Поддержи меня, чтобы я был спасен; и в уставы Твои буду непрестанно вникать.","118":"Ты отверг всех отступников от уставов Твоих, ухищрения их – ложь.","119":"Ты прочь отбросил, как шлак, всех злодеев земли; а я люблю установления Твои.","120":"Трепещет от страха пред Тобой моя плоть, правосудия Твоего я боюсь.","121":"Я поступал по Закону и по правде; не оставь меня на произвол тех, кто гонит меня.","122":"Стань поручителем, что ждут меня мир и добро, не дай надменным притеснять меня, раба Твоего.","123":"Слепнут мои глаза, ожидая от Тебя спасения, правосудного решения Твоего.","124":"Поступи со мной, рабом Твоим, по милости Твоей, и законам Твоим научи меня.","125":"Я раб Твой: вразуми меня, чтобы я познал заповеди Твои.","126":"Время Господу действовать, ибо попран Закон Твой.","127":"Но мне заповеди Твои милей золота, дороже злата червонного.","128":"Я иду прямым путем повелений Твоих; всякий путь лжи ненавижу.","129":"Уставы Твои – чудо; и хранит их душа моя.","130":"Откровение слов Твоих несет свет и вразумляет простецов.","131":"Я от волнения задыхаюсь, так жажду я заповедей Твоих.","132":"Взгляни на меня и помилуй меня, как Ты делаешь с любящими имя Твое.","133":"Пусть слово Твое сделает твердым мой шаг, не дай беззаконию мной овладеть;","134":"избавь меня от притеснения людского, и буду хранить повеления Твои;","135":"светлым взором взгляни на меня, раба Твоего, научи меня законам Твоим.","136":"Из глаз моих потоки текут: не исполняют люди Твой Закон.","137":"Праведен Ты, Господи, и праведен суд Твой.","138":"Наставления Ты заповедал, они – правда и совершенная истина.","139":"Я в ярости от того, что враги мои забыли слова Твои.","140":"Как металл переплавленный слово Твое, и я, раб Твой, люблю его.","141":"Я презрен и ничтожен, но повелений Твоих не забыл.","142":"Правда Твоя – правда вечная, и Закон Твой – истина.","143":"Скорби и беды постигли меня; заповеди Твои – радость для меня.","144":"Наставления Твои вовек справедливы, вразуми меня, чтобы я был жив.","145":"Я взываю всем сердцем: ответь мне, Господи, и буду хранить законы Твои.","146":"Призываю Тебя: спаси меня, и я буду соблюдать наставления Твои.","147":"Не дожидаясь рассвета, взываю к Тебе; я на слово Твое уповаю,","148":"Очи мои не ждут зари, а уже углубляются в слово Твое.","149":"Услышь голос мой, Господи, по милости Твоей, по Твоему правосудию даруй мне жизнь.","150":"Приближаются творящие зло; как далеки они от Закона Твоего!","151":"Близок Ты, Господи, и все заповеди Твои – истина.","152":"Давно известны мне наставления Твои, Ты утвердил их навеки.","153":"Взгляни на мое горе и избавь меня, ведь я Закона Твоего не забыл.","154":"Рассуди мою тяжбу, защити меня; по слову Твоему даруй мне жизнь.","155":"Далеко от злодеев спасение, они не следуют законам Твоим.","156":"Велики щедроты Твои, Господи; по правосудию Твоему даруй мне жизнь.","157":"Много у меня гонителей и врагов, но я не уклоняюсь от наставлений Твоих.","158":"С отвращением смотрю на отступников, которые не хранят слова Твоего.","159":"Смотри, как люблю я повеленья Твои, Господи, по милости Твоей даруй мне жизнь.","160":"Суть слова Твоего – истина, Твои законы праведны и вечны.","161":"Власти гонят меня безвинно, мое сердце благоговеет перед словом Твоим.","162":"Радуюсь я слову Твоему, как нашедший сокровище.","163":"Ненавижу ложь и гнушаюсь ею, а Закон Твой люблю.","164":"Семь раз в день прославляю Тебя за праведные законы Твои.","165":"Мир и благоденствие у любящих Закон Твой, и споткнуться опасности нет.","166":"Уповаю на спасение Твое, Господи, и заповеди Твои исполняю.","167":"Душа моя хранит наставления Твои, и я люблю их крепко.","168":"Я храню повеления и наставления Твои, все пути мои – пред очами Твоими.","169":"Пусть мой крик дойдет до Тебя, Господи; по слову Твоему вразуми меня.","170":"Пусть моление мое предстанет пред Тобою; по слову Твоему спаси меня.","171":"Уста мои провозгласят хвалу, Ты меня учишь наставлениям Твоим.","172":"Язык мой возгласит слово Твое, все Твои заповеди справедливы.","173":"Да поможет мне рука Твоя, я избрал жизнь по повелениям Твоим.","174":"Жажду спасения Твоего, Господи, и Закон Твой – радость для меня.","175":"Да живет душа моя и славит Тебя, и законы Твои пусть поддержат меня.","176":"Я заблудился, как потерянная овца: найди меня, раба Твоего, ибо заповедей Твоих я не забыл."},"119":{"1":"[Песнь восхождения.] К Господу в скорби моей я воззвал, и на зов мой ответил Он.","2":"Господи, от лживых уст спаси, от коварного языка.","3":"Что за плата тебя ждет, коварный язык? И что будет прибавлено к плате?","4":"– Стрелы воина острые! – Стрелы с углями горящими!","5":"Горе мне: в стране Мешеха я, средь кедарских шатров.","6":"Долго я живу среди тех, кто не любит жить мирно!","7":"Я говорю им о мире, они – о войне."},"120":{"1":"[Песнь восхождения.] Возведу мои очи к горам. Откуда мне помощи ждать?","2":"Помощь придет ко мне от Господа, сотворившего небо и землю!","3":"– Он не даст оступиться ноге твоей. Он не дремлет, Хранитель твой.","4":"Он не дремлет, не спит, охраняя Израиль.","5":"Твой Хранитель – Господь, Он тебя укрывает, как тень, Он по правую руку твою.","6":"Солнце днем тебя не сразит, не сразит ночью луна.","7":"Господь да хранит тебя, от всех бед да хранит твою жизнь.","8":"Везде, куда бы ты ни шел, да хранит тебя, и ныне и вовек!"},"121":{"1":"[Песнь восхождения. Сложена Давидом.] Радостно слышать слова: «В Дом Господень идем!»","2":"Наши ноги вступили во врата твои, Иерусалим.","3":"Иерусалим, град отстроенный! Вместе здесь собираются,","4":"восходят сюда племена, племена Господа, по Закону Израиля, чтобы имя Господне славить.","5":"Здесь престолы стоят для суда, престолы царства Давидова.","6":"Молитесь, чтобы в мире жил Иерусалим: «Да наслаждаются миром твои друзья,","7":"мир да пребудет в твоих стенах, да наслаждаются миром чертоги твои!»","8":"Ради братьев моих, ради ближних моих я желаю ему: «В мире живи!»","9":"Ради Храма Господа, нашего Бога, я молю: «Благополучие да будет с тобой!»"},"122":{"1":"[Песнь восхождения.] К Тебе мой взор устремлен, о Живущий на небесах!","2":"Как взор рабов следит за рукой господина, как взор рабыни – за рукой госпожи, так наш взор устремляется к Господу, Богу нашему, и ждет Его милостей.","3":"Милостив будь к нам, Господи, милостив будь к нам. Мы по горло насмешками сыты,","4":"по горло сыта душа наша издевательством благополучных, глумлением гордых."},"123":{"1":"[Песнь восхождения. Сложена Давидом.] Если б не был с нами Господь – так пусть скажет Израиль –","2":"если б не был с нами Господь, когда люди напали на нас,","3":"когда гнев их пылал против нас, они съели бы нас живьем!","4":"Затопили бы нас воды, наводнение смело бы нас,","5":"воды бурные нас смели бы.","6":"Благословен Господь – Он не дал их зубам растерзать нас!","7":"Мы, как птицы, спаслись из силков, сеть порвалась, и мы спасены.","8":"Помощь нам – имя Господа, сотворившего небо и землю."},"124":{"1":"[Песнь восхождения.] Кто на Господа надеется – тот как гора Сион: он не поколеблется, стоит вовек.","2":"Как Иерусалим кругом горами защищен, Господь народ Свой окружает и ныне и вовек.","3":"Не поднимется жезл злодея над законным владением праведных! Не то и праведники начнут злые дела творить.","4":"Добрым, Господь, сотвори добро – тем, чье праведно сердце.","5":"А избравших кривые пути и тех, кто зло творит, – уведи прочь! Мир да пребудет с Израилем!"},"125":{"1":"[Песнь восхождения.] Когда Господь пленников Сиону вернул, нам казалось, мы видим сон.","2":"Уста наши были смеха полны, уста наши пели хвалу. Говорили народы, глядя на нас: «Сотворил с ними чудо Господь!»","3":"Да! Сотворил с нами чудо Господь! Как веселились мы!","4":"Пленников наших верни, Господь, как воды – в иссохшие русла юга!","5":"Тот, кто со слезами сеял, будет с радостью жать урожай!","6":"Шел сеятель, шел и плакал, он вернется с весельем, неся снопы!"},"126":{"1":"[Песнь восхождения. Сложена Соломоном.] Если не станет Господь строить дом – напрасно строители трудятся. Если Господь города не охраняет – стража напрасно бдит.","2":"Напрасно вам рано вставать и бодрствовать допоздна! Кто ест хлеб, заработанный своими трудами, тем, любимцам Своим, Господь дает сон.","3":"Дар Господа – дети, награда Его – плод чрева.","4":"Сыновья, рожденные в юности, – что стрелы в богатырской руке.","5":"Блажен, кто наполнил ими колчан свой! Не посрамится он, когда встретится с врагом у городских ворот!"},"127":{"1":"[Песнь восхождения.] Блаженны все чтущие Господа, идущие путями Его!","2":"Ты вкусишь плод, что взрастили руки твои. Блажен ты, счастье тебе!","3":"Жена твоя, как плодовитая лоза, в доме твоем, сыновья твои, как масличные ветви, вокруг стола твоего.","4":"Так будет благословен тот, кто чтит Господа!","5":"Благословит тебя Господь с Сиона, ты будешь радоваться счастью Иерусалима все дни жизни своей!","6":"Увидишь внуков своих! Мир да пребудет с Израилем!"},"128":{"1":"[Песнь восхождения.] С юности многие теснили меня, – так пусть скажет Израиль –","2":"с юности многие теснили меня, теснили, но не одолели.","3":"Спину мою пахари распахали, длинными бороздами.","4":"Но Господь справедлив, Он ярмо нечестивых сломал!","5":"Пусть посрамятся и обратятся вспять все, кто ненавидит Сион!","6":"Пусть они станут как трава на крыше, что засыхает, суховеем опаленная:","7":"не коснутся ее руки жнеца, не подберет ее вяжущий снопы.","8":"И не скажут им прохожие: «Благослови вас Господь, благословляем вас именем Господа!»"},"129":{"1":"[Песнь восхождения.] Из глубины я взываю к Тебе, Господь!","2":"О Господь, услышь голос мой! Твой слух да внемлет моим мольбам!","3":"Если Ты, Господь, всмотришься в наши грехи, – Господи, кто устоит?","4":"В Твоей власти прощение, грозен Ты.","5":"Надеюсь я, о Господь, ожидает душа моя, на Твое слово надеюсь я.","6":"Душа моя Господа ждет сильней, чем стражи – рассвета! Сильней, чем стражи – рассвета,","7":"пусть Израиль Господа ждет! Милосердье во власти Его, избавленье во власти Его.","8":"Он избавит Израиль от всех грехов."},"130":{"1":"[Песнь восхождения. Сложена Давидом.] Господи! Сердце мое не было надменным, глаза мои свысока не смотрели, не покушался я на то, что выше меня, на то, что для меня недоступно.","2":"Я унимал, успокаивал душу мою, и как ребенок у матери на руках, как ребенок – душа моя.","3":"Да уповает Израиль на Господа отныне и вовек!"},"131":{"1":"[Песнь восхождения.] Вспомни, Господи, про Давида, вспомни его страдания –","2":"как поклялся Давид Господу, дал обет Сильному Богу Иакова:","3":"«Не войду я под кров шатра моего, и на ложе мое не лягу,","4":"сон прогоню от глаз моих, дремоту сгоню с век моих,","5":"пока не найду места для Господа – жилища Богатырю Иакова!»","6":"– Мы в Эфрате о нем услышали; в полях Яара мы нашли его!","7":"– Так пойдем же к Его жилищу, поклонимся подножию ног Его!","8":"Взойди, Господь, в Свою обитель, Ты, о Могучий, и Твой ковчег!","9":"Пусть священники Твои облачатся в праведность, пусть возликуют верные Твои!","10":"Ради Давида, слуги Твоего, не отвергни помазанника Твоего!","11":"Поклялся Господь Давиду клятвой верной и непреложной: «Твоих детей, потомков твоих Я возведу на престол твой!","12":"Если будут верны договору со Мной, если станут соблюдать наставления Мои, тогда и их дети, из века в век, будут восседать на престоле твоем!»","13":"Господь полюбил Сион, сделал Своим жилищем:","14":"«Здесь навеки Моя обитель, Я люблю ее и буду жить в ней!","15":"Ее пищу Я благословлю, бедняков ее хлебом накормлю,","16":"ее священников облачу торжеством, пусть веселятся ее люди, верные Мне.","17":"Там взращу Я силу Давида: не дам угаснуть светильнику Помазанника Моего!","18":"Его врагов Я покрою позором. И венец будет сиять на главе его»."},"132":{"1":"[Песнь восхождения. Сложена Давидом.] Как хорошо и приятно братьям вместе собраться!","2":"Это как лучший елей, что течет с головы на бороду, на бороду Ааронову, течет на ворот одежд его!","3":"Словно роса Хермонская, что нисходит на горы Сионские: Господь этому месту дал благословенье и жизнь навеки!"},"133":{"1":"[Песнь восхождения.] Благословите Господа, все рабы Господни, стоящие в Храме Господнем!","2":"Ночью, к святилищу руки воздев, благословите Господа!","3":"Благословит тебя с Сиона Господь, сотворивший небо и землю."},"134":{"1":"Аллилуия. Хвалите имя Господа! Хвалите, рабы Господни,","2":"стоящие в доме Господнем, во дворах дома Бога нашего!","3":"Хвалите Господа, ибо добр Господь! Как прекрасно воспевать Его имя!","4":"Господь избрал Себе народ Иакова, сделал Израиль владением Своим.","5":"Я познал, как велик Господь, наш Господь – превыше всех богов.","6":"Все, что захочет, сделает Господь на небесах и на земле, на морях и в пучинах.","7":"Облака приводит от краев земли, творит молнии при дожде, выводит ветер из тех мест, где хранит его.","8":"Он убил всех первенцев в Египте, первенцев людей и скота,","9":"сотворил знамения и чудеса среди тебя, Египет, с фараоном и со всеми людьми его,","10":"сразил многочисленные племена и убил могучих царей:","11":"Сихона, царя амореев, и Ога, царя Башанского, и все царства Ханаана разбил.","12":"А землю их отдал во владение, во владение Израилю, народу Своему.","13":"Господи! Имя Твое вечно! Господи! Твое имя из века в век!","14":"Господь рассудит тяжбу народа Своего, сжалится над рабами Своими.","15":"Идолы язычников – серебро и золото, изделия рук человеческих:","16":"есть рот – но не говорят; есть глаза, но не видят;","17":"уши есть, но не слышат, да и в устах их дыхания нет.","18":"Пусть такими же станут все, кто делает их, и все, кто на них надеется.","19":"Род Израиля! Благословите Господа. Род Аарона! Благословите Господа.","20":"Род Левия! Благословите Господа. Чтущие Господа! Благословите Господа.","21":"Благословен Господь Сиона, обитающий в Иерусалиме! Аллилуия!"},"135":{"1":"Славьте Господа! Ведь Он добр, милость Его навек.","2":"Славьте Бога богов, милость Его навек.","3":"Славьте Владыку владык, милость Его навек.","4":"Он, лишь Он, чудеса великие творит, милость Его навек.","5":"Он создал небеса Своей мудростью, милость Его навек.","6":"Он распростер землю над водами, милость Его навек.","7":"Он сотворил светила великие, милость Его навек.","8":"Солнце – чтоб управлять днями, милость Его навек.","9":"Луну и звезды – чтоб управлять ночами, милость Его навек.","10":"Поразил Он египетских первенцев, милость Его навек.","11":"И вывел оттуда народ Израиля, милость Его навек.","12":"Рукой Своей сильной, десницей простертой, милость Его навек.","13":"Разделил Красное море надвое, милость Его навек.","14":"И провел посредине народ Израиля, милость Его навек.","15":"А фараона с его войском вверг в Красное море, милость Его навек.","16":"Провел народ Свой через пустыню, милость Его навек.","17":"И сразил царей великих, милость Его навек.","18":"И убил царей сильных, милость Его навек.","19":"Сихона, царя аморейского, милость Его навек.","20":"И Ога, царя Башанского, милость Его навек.","21":"А землю их отдал во владение, милость Его навек.","22":"Во владение Израилю, рабу Своему, милость Его навек.","23":"Угнетали нас, но Господь о нас вспомнил, милость Его навек.","24":"И избавил от наших врагов, милость Его навек.","25":"Он дает пищу всему живому, милость Его навек.","26":"Славьте Бога небесного, милость Его навек."},"136":{"1":"Там, у рек Вавилонских сидели и плакали мы, вспоминая Сион.","2":"Там на ветви ив мы повесили наши лиры.","3":"Те, кто в плен нас увел, приказали, чтобы мы пели песни. Притеснители наши велели, чтоб мы веселились: «Ну-ка спойте нам песни Сиона!»","4":"Как петь нам песнь Господу на чужой земле?","5":"Если я позабуду тебя, Иерусалим, пусть рука моя правая тоже меня позабудет,","6":"и пусть к небу присохнет язык, если помнить не буду тебя я, если выше всех радостей мира не будет мне Иерусалим.","7":"…Припомни, Господь, как сыны Эдома, говорили в день гибели Иерусалима: «Сровняйте, сровняйте его с землей!»","8":"Вавилон, ты страна грабежа! Благословен, кто поступит с тобой, как ты – с нами!","9":"Благословен, кто размозжит твоих детей о камень!"},"137":{"1":"[Давида.] Славлю Тебя всем сердцем моим, в окружении божеств воспеваю Тебя.","2":"Ниц падаю пред святым Храмом Твоим и славлю имя Твое за милость Твою и за верность Твою. Ты надо всем возвеличил Свое имя, Свое слово.","3":"В день, когда я зову, Ты даешь мне ответ, мою жизнь наполняешь силой.","4":"Да прославят Тебя, Господи, все цари земли, услышавшие слова уст Твоих,","5":"да воспоют они Господни пути: велика слава Господня!","6":"Высоко Господь! Он униженного видит, гордого издали узнает.","7":"На пути средь скорбей Ты даешь мне жизнь, Своей рукою смиряешь ярость врагов, и десница Твоя мне спасенье несет.","8":"Господь отомстит за меня! Господи, милость Твоя вовек, не забывай творение рук Твоих!"},"138":{"1":"[Начальнику хора. Псалом Давида.] Господи! Ты испытал меня и все знаешь.","2":"Ты знаешь, когда я сажусь, когда встаю; Ты издали видишь все мысли мои.","3":"Иду ли я, сплю – Ты смотришь за мной, все мои пути известны Тебе.","4":"Еще слово не слетело с моего языка, – а Ты, Господи, уже знаешь его.","5":"Со всех сторон Ты окружаешь меня, Ты меня держишь рукою Своей.","6":"Твое ведение непостижимо для меня – мне не достичь его высоты!","7":"Куда могу я уйти от Духа Твоего, от взгляда Твоего куда убегу?","8":"Если на небо взойду – Ты там; если сойду в Шеол – и там Ты.","9":"Полечу я на крыльях зари, поселюсь у последнего моря –","10":"и там рука Твоя будет вести меня, и там будет держать меня десница Твоя.","11":"Скажу: «Пусть тьма укроет меня, пусть свет вокруг станет ночью» –","12":"но и эта тьма для Тебя – не тьма: ночь светла как день, мрак – что свет.","13":"Ты создал внутренности мои, в материнском чреве соткал меня.","14":"Я сотворен непостижимо и чудесно! Слава Тебе! Я вижу, сколь чудесны дела Твои!","15":"Не сокрыты от Тебя были кости мои, когда в тайне творилось тело мое, вышивалось в глуби земной.","16":"Меня, зародышем, видели очи Твои. В Твоей книге записано все: все дни, что Ты мне определил, ни один из них не забыт.","17":"Как трудно мне понять Твои замыслы, и сколько их, о Боже!","18":"Попробовать пересчитать – их больше, чем песчинок! …Я пробуждаюсь – и по – прежнему с Тобой!","19":"О, если бы Ты, Боже, сразил злодея! Удалитесь от меня, убийцы!","20":"Они говорят о Тебе ложь; произносят попусту имя Твое.","21":"Как ненавижу я, Господи, тех, кто ненавидит Тебя, как презираю тех, кто противится Тебе!","22":"Всей душой я ненавижу их: они – мои враги.","23":"Испытай меня, Боже, и узнай сердце мое; испытай меня, узнай мысли мои.","24":"Смотри, не ложен ли мой путь? Ты Сам направь меня на путь вечный!"},"139":{"1":"[Начальнику хора. Псалом Давида.]","2":"Спаси меня, Господи, от злых людей, от насильников меня избавь:","3":"они зло замышляют в сердце, во вражде проводят всю жизнь,","4":"отточили свой язык, как змеиное жало, на губах у них яд гадючий… [Музыка]","5":"Сохрани меня, Господи, от злодеев, от насильников избавь: они хотят сбить меня с ног,","6":"они, надменные, ставят капкан на меня, злодеи сеть разложили у дороги, на меня ловушки расставили. [Музыка]","7":"Говорю я Господу: «Ты мой Бог, услышь, Господи, мою мольбу!","8":"Господи, Господи, меня спасет Твоя сила! Ты защищаешь голову мою в день битвы.","9":"Господи, не дай, чтобы сбылся умысел злодея, его планам свершиться не дай». [Музыка]","10":"Окружили меня, глядят свысока, пусть коварство их уст поглотит их самих!","11":"Горящие угли на них падут; их бросят в яму, впредь не встанут они.","12":"Не устоит клеветник на земле; зло преследует насильника и губит его.","13":"Знаю я, что Господь вершит суд, что Он вступится за бедных и нищих.","14":"Прославят праведники имя Твое, кто честен – будет жить пред лицом Твоим."},"140":{"1":"[Псалом Давида.] Господи, я Тебя зову, поспеши мне на помощь! Услышь мой голос, зовущий Тебя!","2":"Да взойдет молитва моя к Тебе, как дым благовоний; мои руки, к Тебе воздетые, – это жертва вечерняя.","3":"Приставь, Господи, стражу к моим устам, охраняй двери уст моих.","4":"Не дай сердцу склониться к дурным делам, делать зло с нечестивцами, есть за их столом.","5":"«Пусть праведник бьет и обличает меня, а елей грешника да не умастит моей головы». Пока я молился против их злодейств,","6":"их низвергла рука Скалы, их Судьи ! Слушайте слова мои: сладки они!","7":"– Раздроблены, разбиты, по земле раскиданы кости наши – в челюстях Шеола.","8":"– На Тебя Господи, Господи, устремлен мой взгляд, на Тебя я надеюсь: не погуби мою жизнь!","9":"Сохрани меня от подстроенной мне западни, от злодейских сетей.","10":"Попадутся нечестивые в ловушки свои, а я пройду и избегну их."},"141":{"1":"[Песнь искусная. Молитва Давида, когда он был в пещере.] Громко к Господу я взываю, громко Господу я молюсь.","2":"Я излил перед Ним мое моление; возвестил Ему горе мое.","3":"Ослабел, изнемог мой дух, но Тебе ведом мой путь! На дороге, которой я шел, для меня расставлены сети.","4":"Оглянусь, кто там справа от меня – но никто меня не узнает. Нет для меня убежища, моя жизнь никому не нужна.","5":"Я воззвал к Тебе, Господи, и сказал: «Ты Один – пристанище мне, Ты мой удел на земле живых!»","6":"Я в беде, услышь мой крик! От преследователей спаси! Ведь они сильнее меня.","7":"Из темницы меня выведи, и прославлю я имя Твое. Ты явишь мне милость Свою, вокруг меня соберутся праведники."},"142":{"1":"[Псалом Давида.] Услышь, Господи, молитву мою! Ты верен – выслушай моленья мои! Ты праведен – ответь на мольбу!","2":"Не судись со мною, Твоим рабом: перед Тобой не оправдаться никому.","3":"Враг за мною погнался и в землю втоптал, вверг во тьму, словно я давно мертв.","4":"Изнемог мой дух, замерло сердце.","5":"Вспоминаю я древние времена, речь веду о том, что Ты совершил, и дивлюсь я делам Твоим.","6":"Руки мои простираю к Тебе, душа моя пред Тобой – жаждущая земля!","7":"Отзовись скорее, Господь, – изнемогает мой дух! Не скрывай от меня Свой лик – я словно в могилу спускаюсь!","8":"Дай мне наутро услышать про милость Твою! Ты – надежда моя. Покажи, каким путем мне идти! К Тебе стремится душа моя.","9":"Господи, спаси меня от врагов! У Тебя я защиты ищу.","10":"Научи Твою волю творить! Ты мой Бог! Дух Твой благой выведет меня на простор!","11":"Даруй мне жизнь, ради имени Твоего, Господи! Ты праведен – вызволи меня из беды!","12":"Ты верен – моих врагов сокруши! Тех, кто душит мою жизнь, уничтожь! Ибо я раб Твой."},"143":{"1":"[Сложено Давидом.] Благословен Господь, моя Скала, Он мои руки учит воевать, мои пальцы – сжимать оружие.","2":"Он мне опора, прибежище, оплот, Он мой щит и моя надежда, Он подчиняет мне мой народ.","3":"Что такое человек? А Ты заботишься о нем! Что любой из людей? А Ты думаешь о нем!","4":"Человек – что дуновение ветра, дни его исчезают, как тень.","5":"Господи, склони небеса и сойди, прикоснись к горам – пусть задымятся.","6":"Блесни молнией – и рассей врагов, обрати их стрелами в бегство.","7":"Протяни с высоты Свою руку, из пучины меня вытащи, от чужеземцев спаси:","8":"их уста говорят ложь, и рука их неправду творит.","9":"Боже! Новую песнь воспою Тебе, на арфе десятиструнной буду играть Тебе,","10":"Ты даруешь спасение царям, избавляешь Давида, раба Твоего, от меча лютого.","11":"От чужеземцев избавь меня, спаси: их уста говорят ложь, и рука их неправду творит.","12":"Да будут сыны наши как поросль молодая, а дочери – как колонны, украшение дворца.","13":"Да будут наши закрома полны, обильны всяким добром. Да пасутся на наших лугах тысячи, десятки тысяч овец.","14":"Пусть быки наши будут крепки, пусть не будет ни падежа, ни выкидыша. Пусть не будет вопля на улицах наших.","15":"Блажен народ, который так живет! Блажен тот народ, чей Бог – Господь!"},"144":{"1":"[Песнь хвалы. Сложена Давидом.] Я Тебя буду славить, мой Бог и Царь, благословлять Твое имя во веки веков,","2":"каждый день Тебя буду благословлять, восхвалять Твое имя во веки веков.","3":"Велик Господь, превыше любой хвалы, непостижимо величие Его.","4":"Поколенье за поколением будут славить Твои дела, возвещать о Твоем могуществе.","5":"О блеске, о славе, о величии Твоем, о Твоих чудесах размышляю я.","6":"Люди мощь Твоих грозных дел возвестят. О величии Твоем я поведаю.","7":"Провозгласят они о благодеяниях Твоих, воспевать будут Твою праведность.","8":"Щедр и милостив Господь, долготерпелив, многомилостив.","9":"Благ Господь ко всем, милосерден ко всем своим созданиям.","10":"Все создания Твои, Господи, славят Тебя, Твои верные Тебя благословляют.","11":"Проповедуют славу царства Твоего, повествуют о могуществе Твоем.","12":"Возвещают людям о могуществе Твоем, о сияющей славе царства Твоего.","13":"Все века подвластны царской власти Твоей, и владычество Твое – из рода в род.","14":"Господь падающих поддерживает и согбенных до земли поднимает.","15":"Очи всех устремлены к Тебе, приходит время – и Ты каждому пищу даешь.","16":"Протягиваешь руку Твою – и насыщаешь все живое: все, что нужно, даешь.","17":"Праведен Господь во всех путях Своих и верен во всем, что бы ни делал Он.","18":"Господь близок ко всем призывающим Его, к тем, кто искренне взывает к Нему.","19":"Он исполняет желание тех, кто чтит Его, слышит их вопль – и спасает их.","20":"Хранит Господь всех, кто любит Его, и уничтожит всех нечестивцев.","21":"Хвалу Господу мои уста изрекут, и благословит все живое имя святое Его во веки веков."},"145":{"1":"[Аллилуия.] Хвали, душа моя, Господа.","2":"Я буду петь хвалу Господу, пока я жив; пока существую, буду петь Богу моему.","3":"Не надейтесь на богатых и сильных, на человека – не принесет он спасенья.","4":"Дух покинет его, и вернется он в землю свою, и в тот день разрушатся все его замыслы.","5":"Блажен, кому помогает Бог Иакова, кто уповает на Господа, Бога своего,","6":"сотворившего небо и землю, и море, и все, что их наполняет; хранящего верность вовек;","7":"творящего правосудие обиженным; подающего хлеб голодным. Господь освобождает узников,","8":"Господь дает зрение слепым, Господь поднимает согбенных до земли, Господь любит праведников.","9":"Господь хранит живущих на чужбине, вдове и сироте помогает, а нечестивых заставляет блуждать.","10":"Царствовать будет Господь во веки, Бог твой, Сион, – из поколения в поколение. Аллилуия."},"146":{"1":"[Аллилуия.] Хвалите Господа: хорошо песнь петь Богу нашему, сладко и радостно хвалить Его.","2":"Господь строит Иерусалим, соберет изгнанников Израиля.","3":"Господь лечит сокрушенных сердцем, перевязывает их раны.","4":"Пересчитывает Он звезды – всех их по имени выкликает.","5":"Велик Господь наш, и сила Его велика, и безмерно знанье Его.","6":"Нищих подкрепляет Господь, а злодеев повергает наземь.","7":"Пойте Господу песнь хвалы, Богу нашему пойте под лиру.","8":"Он заволакивает небо облаками, посылает на землю дождь, покрывает горы травой.","9":"Скоту домашнему пищу дает и пищащим вороньим птенцам.","10":"Не смотрит Он на силу коня, на быстроту ног человеческих.","11":"А угодны Ему те, кто почитает Его и уповает на милость Его."},"147":{"1":"Иерусалим, славь Господа! Сион, хвали Бога твоего!","2":"Он укрепляет засовы твоих ворот, Он благословляет сынов твоих!","3":"Он дает земле твоей мир, сытной пшеницей питает тебя.","4":"Он земле посылает приказы Свои, и быстро доносятся приказы Его!","5":"Он снег расстилает, как белую шерсть, Он сыплет иней, как пепел.","6":"Кидает градины, как хлебные крошки. И кто мороз Его сможет выдержать?","7":"Послал Он слово Свое – и растаяло все, подул ветром – и воды потекли.","8":"Он возвестил Иакову слово Свое, Израилю – законы и веленья Свои.","9":"Для других народов Он такого не делал, и не знают они законов Его. Аллилуия!"},"148":{"1":"[Аллилуия.] Хвалите Господа с небес, хвалите Его в вышних.","2":"Хвалите Его, все Ангелы Его, хвалите Его, все воинства Его.","3":"Хвалите Его, солнце и луна, хвалите Его, все светоносные звезды.","4":"Хвалите Его, небеса небес и воды, которые превыше небес.","5":"Пусть все они имя Господне хвалят – они сотворены повеленьем Его.","6":"Он поставил их твердо, на веки веков, дал Закон – и они не нарушат его.","7":"Хвалите Господа с земли, великие рыбы и глубины морские,","8":"огонь и град, снег и туман, бурный ветер, исполняющий слово Его,","9":"все горы и все холмы, все плодоносные деревья и кедры,","10":"все звери, все домашние животные, зверьки снующие и птицы крылатые.","11":"Все земные цари, все народы, все правители и судьи земные,","12":"юноши и девушки, стар и млад –","13":"пусть все они имя Господа хвалят. Имя Его превыше всего, слава Его на земле и на небе.","14":"Он народу дал гордо рога вознести – прославил тех, кто верен Ему, – Израиль, народ, родной для Него. Аллилуия."},"149":{"1":"[Аллилуия.] Пойте Господу новую песнь, хвалебную песнь в собрании верных.","2":"Да веселится Израиль пред Создателем своим; сыны Сиона да радуются пред своим Царем.","3":"С плясками имя Его хвалите, под бубен и лиры пойте Ему.","4":"Ибо Господь любит Свой народ, прославляет смиренных, спасает их!","5":"Верные да торжествуют во славе, да ликуют на ложах своих.","6":"Хвала Богу у них на устах, и меч обоюдоострый в руке,","7":"чтобы покарать народы, наказать племена людей,","8":"заковать их царей в кандалы и вельмож их – в оковы железные","9":"и свершить приговор, что написан для них. Эта честь выпадет всем, кто верен Ему!"},"150":{"1":"[Аллилуия.] Хвалите Бога во святилище Его, хвалите на тверди Его небес,","2":"хвалите за могучие деяния Его, хвалите за безмерное величие Его.","3":"Хвалите его гласом трубы, хвалите Его на арфе и лире,","4":"хвалите Его плясками с бубнами, хвалите Его с лютнями и флейтами!","5":"Хвалите Его с цимбалами громкими, хвалите Его с цимбалами звонкими!","6":"Все живое – да хвалит Господа! Аллилуия!"}};
